594:     /**
595:      * Relocates the default log directory of ForSt with the Flink log directory. Finds the Flink
596:      * log directory using log.file Java property that is set during startup.
597:      *
598:      * @param dbOptions The ForSt {@link DBOptions}.
599:      */
600:     private void relocateDefaultDbLogDir(DBOptions dbOptions) {
601:         String logFilePath = System.getProperty("log.file");
602:         if (logFilePath != null) {
603:             File logFile = resolveFileLocation(logFilePath);
604:             if (logFile != null && resolveFileLocation(logFile.getParent()) != null) {
605:                 String relocatedDbLogDir = logFile.getParent();
606:                 this.relocatedDbLogBaseDir = new File(relocatedDbLogDir).toPath();
607:                 dbOptions.setDbLogDir(relocatedDbLogDir);
608:             } else {
609:                 setLocalForStPathAsLogDir(dbOptions);
610:             }
611:         } else {
612:             setLocalForStPathAsLogDir(dbOptions);
613:         }
614:     }
615: 
616:     private void setLocalForStPathAsLogDir(DBOptions dbOptions) {
617:         // Currently, ForStDB does not support mixing local-dir and remote-dir, and ForStDB will
618:         // concatenates the dfs directory with the local directory as working dir when using flink
619:         // env. We expect to directly use the dfs directory in flink env or local directory as
620:         // working dir. We will implement this in ForStDB later, but before that, we achieved this
621:         // by setting the dbPath to "/" when the dfs directory existed. Another problem is that when
622:         // the system property "log.file" is not set, ForSt directly uses the instance path as the
623:         // log dir, which results in "/" being used as the log directory. This often has permission
624:         // issues, so the db log dir is temporarily set explicitly here.
625:         // TODO: remove this method after ForSt deal log dir well
626:         if (localForStPath != null) {
627:             this.relocatedDbLogBaseDir = java.nio.file.Path.of(localForStPath.toUri().toString());
628:             dbOptions.setDbLogDir(localForStPath.getPath());
629:         }
630:     }
