633:      * Verify log file location.
634:      *
635:      * @param logFilePath Path to log file
636:      * @return File or null if not a valid log file
637:      */
638:     private File resolveFileLocation(String logFilePath) {
639:         File logFile = new File(logFilePath);
640:         return (logFile.exists() && logFile.canRead()) ? logFile : null;
641:     }
