643:     /** Clean all relocated ForSt logs. */
644:     private void cleanRelocatedDbLogs() {
645:         if (localForStPath != null && relocatedDbLogBaseDir != null) {
646:             LOG.info("Cleaning up relocated ForSt logs: {}.", relocatedDbLogBaseDir);
647: 
648:             String relocatedDbLogPrefix = resolveRelocatedDbLogPrefix(localForStPath.getPath());
649:             try {
650:                 Arrays.stream(FileUtils.listDirectory(relocatedDbLogBaseDir))
651:                         .filter(
652:                                 path ->
653:                                         !Files.isDirectory(path)
654:                                                 && path.toFile()
655:                                                         .getName()
656:                                                         .startsWith(relocatedDbLogPrefix))
657:                         .forEach(IOUtils::deleteFileQuietly);
658:             } catch (IOException e) {
659:                 LOG.warn("Could not list relocated ForSt log directory: {}", relocatedDbLogBaseDir);
660:             }
661:         }
662:     }
