664:     /**
665:      * Resolve the prefix of ForSt's log file name according to ForSt's log file name rules.
666:      *
667:      * @param instanceForStAbsolutePath The path where the ForSt directory is located.
668:      * @return Resolved ForSt log name prefix.
669:      */
670:     private String resolveRelocatedDbLogPrefix(String instanceForStAbsolutePath) {
671:         if (!instanceForStAbsolutePath.isEmpty()
672:                 && !instanceForStAbsolutePath.matches("^[a-zA-Z0-9\\-._].*")) {
673:             instanceForStAbsolutePath = instanceForStAbsolutePath.substring(1);
674:         }
675:         return instanceForStAbsolutePath.replaceAll("[^a-zA-Z0-9\\-._]", "_")
676:                 + FORST_RELOCATE_LOG_SUFFIX;
677:     }
