844:     @VisibleForTesting
845:     static void ensureForStIsLoaded(
846:             String tempDirectory,
847:             Supplier<NativeLibraryLoader> nativeLibraryLoaderSupplier,
848:             Executor executor)
849:             throws IOException {
850:         synchronized (ForStStateBackend.class) {
851:             if (!forStInitialized) {
852: 
853:                 final File tempDirParent = new File(tempDirectory).getAbsoluteFile();
854:                 LOG.info(
855:                         "Attempting to load ForSt native library and store it under '{}'",
856:                         tempDirParent);
857: 
858:                 Throwable lastException = null;
859:                 for (int attempt = 1; attempt <= FORST_LIB_LOADING_ATTEMPTS; attempt++) {
860:                     AtomicReference<File> rocksLibFolder = new AtomicReference<>(null);
861:                     try {
862:                         // when multiple instances of this class and ForSt exist in different
863:                         // class loaders, then we can see the following exception:
864:                         // "java.lang.UnsatisfiedLinkError: Native Library
865:                         // /path/to/temp/dir/librocksdbjni-linux64.so
866:                         // already loaded in another class loader"
867: 
868:                         // to avoid that, we need to add a random element to the library file path
869:                         // (I know, seems like an unnecessary hack, since the JVM obviously can
870:                         // handle multiple
871:                         //  instances of the same JNI library being loaded in different class
872:                         // loaders, but
873:                         //  apparently not when coming from the same file path, so there we go)
874: 
875:                         // We use an async procedure to load the library, to make current thread be
876:                         // able to interrupt for a fast quit.
877:                         CompletableFuture<Void> future =
878:                                 FutureUtils.runAsync(
879:                                         () -> {
880:                                             File libFolder =
881:                                                     new File(
882:                                                             tempDirParent,
883:                                                             "rocksdb-lib-" + new AbstractID());
884:                                             rocksLibFolder.set(libFolder);
885: 
886:                                             // make sure the temp path exists
887:                                             LOG.debug(
888:                                                     "Attempting to create ForSt native library folder {}",
889:                                                     libFolder);
890:                                             // noinspection ResultOfMethodCallIgnored
891:                                             libFolder.mkdirs();
892: 
893:                                             // explicitly load the JNI dependency if it has not been
894:                                             // loaded before
895:                                             nativeLibraryLoaderSupplier
896:                                                     .get()
897:                                                     .loadLibrary(libFolder.getAbsolutePath());
898: 
899:                                             // this initialization here should validate that the
900:                                             // loading succeeded
901:                                             RocksDB.loadLibrary();
902:                                         },
903:                                         executor);
904: 
905:                         // wait for finish or be interrupted.
906:                         future.get();
907: 
908:                         // seems to have worked
909:                         LOG.info("Successfully loaded ForSt native library");
910:                         forStInitialized = true;
911:                         return;
912:                     } catch (Throwable t) {
913:                         lastException = t;
914:                         LOG.debug("ForSt JNI library loading attempt {} failed", attempt, t);
915: 
916:                         // try to force ForSt to attempt reloading the library
917:                         try {
918:                             resetForStLoadedFlag();
919:                         } catch (Throwable tt) {
920:                             LOG.debug(
921:                                     "Failed to reset 'initialized' flag in ForSt native code loader",
922:                                     tt);
923:                         }
924: 
925:                         FileUtils.deleteDirectoryQuietly(rocksLibFolder.get());
926:                     }
927:                 }
928: 
929:                 throw new IOException("Could not load the native ForSt library", lastException);
930:             }
931:         }
932:     }
933: 
934:     @VisibleForTesting
935:     static void resetForStLoadedFlag() throws Exception {
936:         final Field initField = NativeLibraryLoader.class.getDeclaredField("initialized");
937:         initField.setAccessible(true);
938:         initField.setBoolean(null, false);
939:     }
