297:     private void revertRequiredBuffers(int size) {
298:         synchronized (factoryLock) {
299:             numTotalRequiredBuffers -= size;
300: 
301:             // note: if this fails, we're fine for the buffer pool since we already recycled the
302:             // segments
303:             redistributeBuffers();
304:         }
305:     }
