291:     /**
292:      * Utility method to extract network related parameters from the configuration and to sanity
293:      * check them.
294:      *
295:      * @param configuration configuration object
296:      * @param networkMemorySize the size of memory reserved for shuffle environment
297:      * @param localTaskManagerCommunication true, to skip initializing the network stack
298:      * @param taskManagerAddress identifying the IP address under which the TaskManager will be
299:      *     accessible
300:      * @return NettyShuffleEnvironmentConfiguration
301:      */
302:     public static NettyShuffleEnvironmentConfiguration fromConfiguration(
303:             Configuration configuration,
304:             MemorySize networkMemorySize,
305:             boolean localTaskManagerCommunication,
306:             InetAddress taskManagerAddress) {
307: 
308:         final PortRange dataBindPortRange = getDataBindPortRange(configuration);
309: 
310:         final int pageSize = ConfigurationParserUtils.getPageSize(configuration);
311: 
312:         final NettyConfig nettyConfig =
313:                 createNettyConfig(
314:                         configuration,
315:                         localTaskManagerCommunication,
316:                         taskManagerAddress,
317:                         dataBindPortRange);
318: 
319:         final int numberOfNetworkBuffers =
320:                 calculateNumberOfNetworkBuffers(configuration, networkMemorySize, pageSize);
321: 
322:         int initialRequestBackoff =
323:                 configuration.get(NettyShuffleEnvironmentOptions.NETWORK_REQUEST_BACKOFF_INITIAL);
324:         int maxRequestBackoff =
325:                 configuration.get(NettyShuffleEnvironmentOptions.NETWORK_REQUEST_BACKOFF_MAX);
326:         int listenerTimeout =
327:                 (int)
328:                         configuration
329:                                 .get(
330:                                         NettyShuffleEnvironmentOptions
331:                                                 .NETWORK_PARTITION_REQUEST_TIMEOUT)
332:                                 .toMillis();
333: 
334:         int buffersPerChannel =
335:                 configuration.get(NettyShuffleEnvironmentOptions.NETWORK_BUFFERS_PER_CHANNEL);
336:         int extraBuffersPerGate =
337:                 configuration.get(NettyShuffleEnvironmentOptions.NETWORK_EXTRA_BUFFERS_PER_GATE);
338: 
339:         Optional<Integer> maxRequiredBuffersPerGate =
340:                 configuration.getOptional(
341:                         NettyShuffleEnvironmentOptions.NETWORK_READ_MAX_REQUIRED_BUFFERS_PER_GATE);
342: 
343:         int maxBuffersPerChannel =
344:                 configuration.get(NettyShuffleEnvironmentOptions.NETWORK_MAX_BUFFERS_PER_CHANNEL);
345: 
346:         int maxOverdraftBuffersPerGate =
347:                 configuration.get(
348:                         NettyShuffleEnvironmentOptions.NETWORK_MAX_OVERDRAFT_BUFFERS_PER_GATE);
349: 
350:         long batchShuffleReadMemoryBytes =
351:                 configuration.get(TaskManagerOptions.NETWORK_BATCH_SHUFFLE_READ_MEMORY).getBytes();
352: 
353:         int sortShuffleMinBuffers =
354:                 configuration.get(NettyShuffleEnvironmentOptions.NETWORK_SORT_SHUFFLE_MIN_BUFFERS);
355:         int sortShuffleMinParallelism =
356:                 configuration.get(
357:                         NettyShuffleEnvironmentOptions.NETWORK_SORT_SHUFFLE_MIN_PARALLELISM);
358: 
359:         boolean isNetworkDetailedMetrics =
360:                 configuration.get(NettyShuffleEnvironmentOptions.NETWORK_DETAILED_METRICS);
361: 
362:         String[] tempDirs = ConfigurationUtils.parseTempDirectories(configuration);
363:         // Shuffle the data directories to make it fairer for directory selection between different
364:         // TaskManagers, which is good for load balance especially when there are multiple disks.
365:         List<String> shuffleDirs = Arrays.asList(tempDirs);
366:         Collections.shuffle(shuffleDirs);
367: 
368:         Duration requestSegmentsTimeout =
369:                 configuration.get(NettyShuffleEnvironmentOptions.NETWORK_BUFFERS_REQUEST_TIMEOUT);
370: 
371:         BoundedBlockingSubpartitionType blockingSubpartitionType =
372:                 getBlockingSubpartitionType(configuration);
373: 
374:         CompressionCodec compressionCodec =
375:                 configuration.get(NettyShuffleEnvironmentOptions.SHUFFLE_COMPRESSION_CODEC);
376: 
377:         boolean batchShuffleCompressionEnabled;
378:         if (compressionCodec == CompressionCodec.NONE) {
379:             batchShuffleCompressionEnabled = false;
380:         } else {
381:             batchShuffleCompressionEnabled =
382:                     configuration.get(
383:                             NettyShuffleEnvironmentOptions.BATCH_SHUFFLE_COMPRESSION_ENABLED);
384: 
385:             if (!batchShuffleCompressionEnabled) {
386:                 LOG.warn(
387:                         "Deprecated configuration key {} is used to disable the compression. "
388:                                 + "Please set the {} to \"None\" to disable the compression.",
389:                         NettyShuffleEnvironmentOptions.BATCH_SHUFFLE_COMPRESSION_ENABLED.key(),
390:                         NettyShuffleEnvironmentOptions.SHUFFLE_COMPRESSION_CODEC.key());
391:             }
392:         }
393: 
394:         int maxNumConnections =
395:                 Math.max(
396:                         1,
397:                         configuration.get(NettyShuffleEnvironmentOptions.MAX_NUM_TCP_CONNECTIONS));
398: 
399:         boolean connectionReuseEnabled =
400:                 configuration.get(
401:                         NettyShuffleEnvironmentOptions.TCP_CONNECTION_REUSE_ACROSS_JOBS_ENABLED);
402: 
403:         int hybridShuffleSpilledIndexSegmentSize =
404:                 configuration.get(
405:                         NettyShuffleEnvironmentOptions
406:                                 .HYBRID_SHUFFLE_SPILLED_INDEX_REGION_GROUP_SIZE);
407: 
408:         long hybridShuffleNumRetainedInMemoryRegionsMax =
409:                 configuration.get(
410:                         NettyShuffleEnvironmentOptions
411:                                 .HYBRID_SHUFFLE_NUM_RETAINED_IN_MEMORY_REGIONS_MAX);
412: 
413:         checkArgument(buffersPerChannel >= 0, "Must be non-negative.");
414:         checkArgument(
415:                 !maxRequiredBuffersPerGate.isPresent() || maxRequiredBuffersPerGate.get() >= 1,
416:                 String.format(
417:                         "At least one buffer is required for each gate, please increase the value of %s.",
418:                         NettyShuffleEnvironmentOptions.NETWORK_READ_MAX_REQUIRED_BUFFERS_PER_GATE
419:                                 .key()));
420:         checkArgument(
421:                 extraBuffersPerGate >= 1,
422:                 String.format(
423:                         "The configured floating buffer should be at least 1, please increase the value of %s.",
424:                         NettyShuffleEnvironmentOptions.NETWORK_EXTRA_BUFFERS_PER_GATE.key()));
425: 
426:         TieredStorageConfiguration tieredStorageConfiguration = null;
427:         if ((configuration.get(BATCH_SHUFFLE_MODE) == ALL_EXCHANGES_HYBRID_FULL
428:                         || configuration.get(BATCH_SHUFFLE_MODE) == ALL_EXCHANGES_HYBRID_SELECTIVE)
429:                 && configuration.get(NETWORK_HYBRID_SHUFFLE_ENABLE_NEW_MODE)) {
430:             tieredStorageConfiguration =
431:                     TieredStorageConfiguration.fromConfiguration(configuration);
432:         }
433:         return new NettyShuffleEnvironmentConfiguration(
434:                 numberOfNetworkBuffers,
435:                 pageSize,
436:                 initialRequestBackoff,
437:                 maxRequestBackoff,
438:                 listenerTimeout,
439:                 buffersPerChannel,
440:                 extraBuffersPerGate,
441:                 maxRequiredBuffersPerGate,
442:                 requestSegmentsTimeout,
443:                 isNetworkDetailedMetrics,
444:                 nettyConfig,
445:                 shuffleDirs.toArray(tempDirs),
446:                 blockingSubpartitionType,
447:                 batchShuffleCompressionEnabled,
448:                 compressionCodec,
449:                 maxBuffersPerChannel,
450:                 batchShuffleReadMemoryBytes,
451:                 sortShuffleMinBuffers,
452:                 sortShuffleMinParallelism,
453:                 BufferDebloatConfiguration.fromConfiguration(configuration),
454:                 maxNumConnections,
455:                 connectionReuseEnabled,
456:                 maxOverdraftBuffersPerGate,
457:                 hybridShuffleSpilledIndexSegmentSize,
458:                 hybridShuffleNumRetainedInMemoryRegionsMax,
459:                 tieredStorageConfiguration);
460:     }
