462:     /**
463:      * Parses the hosts / ports for communication and data exchange from configuration.
464:      *
465:      * @param configuration configuration object
466:      * @return the data port
467:      */
468:     private static PortRange getDataBindPortRange(Configuration configuration) {
469:         if (configuration.contains(NettyShuffleEnvironmentOptions.DATA_BIND_PORT)) {
470:             String dataBindPort = configuration.get(NettyShuffleEnvironmentOptions.DATA_BIND_PORT);
471: 
472:             return new PortRange(dataBindPort);
473:         }
474: 
475:         int dataBindPort = configuration.get(NettyShuffleEnvironmentOptions.DATA_PORT);
476:         ConfigurationParserUtils.checkConfigParameter(
477:                 dataBindPort >= 0,
478:                 dataBindPort,
479:                 NettyShuffleEnvironmentOptions.DATA_PORT.key(),
480:                 "Leave config parameter empty or use 0 to let the system choose a port automatically.");
481: 
482:         return new PortRange(dataBindPort);
483:     }
