485:     /**
486:      * Calculates the number of network buffers based on configuration and jvm heap size.
487:      *
488:      * @param configuration configuration object
489:      * @param networkMemorySize the size of memory reserved for shuffle environment
490:      * @param pageSize size of memory segment
491:      * @return the number of network buffers
492:      */
493:     private static int calculateNumberOfNetworkBuffers(
494:             Configuration configuration, MemorySize networkMemorySize, int pageSize) {
495: 
496:         logIfIgnoringOldConfigs(configuration);
497: 
498:         // tolerate offcuts between intended and allocated memory due to segmentation (will be
499:         // available to the user-space memory)
500:         long numberOfNetworkBuffersLong = networkMemorySize.getBytes() / pageSize;
501:         if (numberOfNetworkBuffersLong > Integer.MAX_VALUE) {
502:             throw new IllegalArgumentException(
503:                     "The given number of memory bytes ("
504:                             + networkMemorySize.getBytes()
505:                             + ") corresponds to more than MAX_INT pages.");
506:         }
507: 
508:         return (int) numberOfNetworkBuffersLong;
509:     }
510: 
511:     @SuppressWarnings("deprecation")
512:     private static void logIfIgnoringOldConfigs(Configuration configuration) {
513:         if (configuration.contains(NettyShuffleEnvironmentOptions.NETWORK_NUM_BUFFERS)) {
514:             LOG.info(
515:                     "Ignoring old (but still present) network buffer configuration via {}.",
516:                     NettyShuffleEnvironmentOptions.NETWORK_NUM_BUFFERS.key());
517:         }
518:     }
