520:     /**
521:      * Generates {@link NettyConfig} from Flink {@link Configuration}.
522:      *
523:      * @param configuration configuration object
524:      * @param localTaskManagerCommunication true, to skip initializing the network stack
525:      * @param taskManagerAddress identifying the IP address under which the TaskManager will be
526:      *     accessible
527:      * @param dataPortRange data port range for communication and data exchange
528:      * @return the netty configuration or {@code null} if communication is in the same task manager
529:      */
530:     @Nullable
531:     private static NettyConfig createNettyConfig(
532:             Configuration configuration,
533:             boolean localTaskManagerCommunication,
534:             InetAddress taskManagerAddress,
535:             PortRange dataPortRange) {
536: 
537:         final NettyConfig nettyConfig;
538:         if (!localTaskManagerCommunication) {
539:             final InetSocketAddress taskManagerInetSocketAddress =
540:                     new InetSocketAddress(taskManagerAddress, 0);
541: 
542:             nettyConfig =
543:                     new NettyConfig(
544:                             taskManagerInetSocketAddress.getAddress(),
545:                             dataPortRange,
546:                             ConfigurationParserUtils.getPageSize(configuration),
547:                             ConfigurationParserUtils.getSlot(configuration),
548:                             configuration);
549:         } else {
550:             nettyConfig = null;
551:         }
552: 
553:         return nettyConfig;
554:     }
