556:     private static BoundedBlockingSubpartitionType getBlockingSubpartitionType(
557:             Configuration config) {
558:         String transport = config.get(NettyShuffleEnvironmentOptions.NETWORK_BLOCKING_SHUFFLE_TYPE);
559: 
560:         switch (transport) {
561:             case "mmap":
562:                 return BoundedBlockingSubpartitionType.FILE_MMAP;
563:             case "file":
564:                 return BoundedBlockingSubpartitionType.FILE;
565:             default:
566:                 return BoundedBlockingSubpartitionType.AUTO;
567:         }
568:     }
