371:         NetworkBufferPool globalPool = new NetworkBufferPool(10, bufferSize);
372:         BufferPool localPool = globalPool.createBufferPool(1, 1, 1, 1, Integer.MAX_VALUE, 0);
373:         BufferWritingResultPartition resultPartition =
374:                 (BufferWritingResultPartition)
375:                         new ResultPartitionBuilder().setBufferPoolFactory(() -> localPool).build();
376:         resultPartition.setup();
377: 
378:         resultPartition.emitRecord(ByteBuffer.allocate(bufferSize), 0);
379:         ResultSubpartitionView readView =
380:                 resultPartition.createSubpartitionView(
381:                         new ResultSubpartitionIndexSet(0), new NoOpBufferAvailablityListener());
382:         Buffer buffer = readView.getNextBuffer().buffer();
383:         assertThat(buffer).isNotNull();
384: 
385:         // back-pressured time is zero when there is buffer available.
386:         assertThat(resultPartition.getHardBackPressuredTimeMsPerSecond().getValue()).isZero();
387: 
388:         CountDownLatch syncLock = new CountDownLatch(1);
389:         final Thread requestThread =
390:                 new Thread(
391:                         () -> {
392:                             try {
393:                                 // notify that the request thread start to run.
394:                                 syncLock.countDown();
395:                                 // wait for buffer.
396:                                 resultPartition.emitRecord(ByteBuffer.allocate(bufferSize), 0);
397:                             } catch (Exception e) {
398:                             }
399:                         });
400:         requestThread.start();
401: 
402:         // wait until request thread start to run.
403:         syncLock.await();
404: 
405:         // wait until request buffer blocking.
406:         while (!isInBlockingBufferRequest(requestThread.getStackTrace())) {
407:             Thread.sleep(50);
408:         }
409:         // there is an extreme case where the request thread recovers from blocking very
410:         // quickly, resulting in a calculated back-pressure time is equal to 0. This is used to
411:         // avoid this case.
412:         Thread.sleep(5);
413:         // recycle the buffer
414:         buffer.recycleBuffer();
415:         requestThread.join();
416: 
417:         assertThat(resultPartition.getHardBackPressuredTimeMsPerSecond().getCount())
418:                 .isGreaterThan(0L);
419:         assertThat(readView.getNextBuffer().buffer()).isNotNull();
