144:     /** Creates an input gate and all of its input channels. */
145:     public SingleInputGate create(
146:             @Nonnull ShuffleIOOwnerContext owner,
147:             int gateIndex,
148:             @Nonnull InputGateDeploymentDescriptor igdd,
149:             @Nonnull PartitionProducerStateProvider partitionProducerStateProvider,
150:             @Nonnull InputChannelMetrics metrics) {
151:         // This variable describes whether it is supported to have one input channel consume
152:         // multiple subpartitions, if multiple subpartitions from the same partition are
153:         // assigned to this input gate.
154:         //
155:         // For now this function is only supported in the new mode of Hybrid Shuffle.
156:         boolean isSharedInputChannelSupported =
157:                 igdd.getConsumedPartitionType().isHybridResultPartition()
158:                         && tieredStorageConfiguration != null;
159: 
160:         GateBuffersSpec gateBuffersSpec =
161:                 createGateBuffersSpec(
162:                         maxRequiredBuffersPerGate,
163:                         configuredNetworkBuffersPerChannel,
164:                         floatingNetworkBuffersPerGate,
165:                         igdd.getConsumedPartitionType(),
166:                         calculateNumChannels(
167:                                 igdd.getShuffleDescriptors().length,
168:                                 igdd.getConsumedSubpartitionIndexRange().size(),
169:                                 isSharedInputChannelSupported),
170:                         tieredStorageConfiguration != null);
171:         SupplierWithException<BufferPool, IOException> bufferPoolFactory =
172:                 createBufferPoolFactory(
173:                         networkBufferPool,
174:                         gateBuffersSpec.getExpectedBuffersPerGate(),
175:                         gateBuffersSpec.getTotalFloatingBuffers(),
176:                         gateBuffersSpec.getMaxBuffersPerGate());
177: 
178:         BufferDecompressor bufferDecompressor = null;
179:         if (igdd.getConsumedPartitionType().supportCompression()
180:                 && batchShuffleCompressionEnabled) {
181:             bufferDecompressor = new BufferDecompressor(networkBufferSize, compressionCodec);
182:         }
183: 
184:         final String owningTaskName = owner.getOwnerName();
185:         final MetricGroup networkInputGroup = owner.getInputGroup();
186: 
187:         ResultSubpartitionIndexSet subpartitionIndexSet =
188:                 new ResultSubpartitionIndexSet(igdd.getConsumedSubpartitionIndexRange());
189:         SingleInputGate inputGate =
190:                 new SingleInputGate(
191:                         owningTaskName,
192:                         gateIndex,
193:                         igdd.getConsumedResultId(),
194:                         igdd.getConsumedPartitionType(),
195:                         calculateNumChannels(
196:                                 igdd.getShuffleDescriptors().length,
197:                                 subpartitionIndexSet.size(),
198:                                 isSharedInputChannelSupported),
199:                         partitionProducerStateProvider,
200:                         bufferPoolFactory,
201:                         bufferDecompressor,
202:                         networkBufferPool,
203:                         networkBufferSize,
204:                         new ThroughputCalculator(SystemClock.getInstance()),
205:                         maybeCreateBufferDebloater(
206:                                 owningTaskName, gateIndex, networkInputGroup.addGroup(gateIndex)));
207: 
208:         createInputChannelsAndTieredStorageService(
209:                 owningTaskName,
210:                 igdd,
211:                 inputGate,
212:                 subpartitionIndexSet,
213:                 gateBuffersSpec,
214:                 metrics,
215:                 isSharedInputChannelSupported);
216:         return inputGate;
217:     }
