43:     private final LatencyTrackingStateConfig latencyTrackingStateConfig;
44:     private final Map<StateDescriptor.Type, SupplierWithException<IS, Exception>> stateFactories;
45: 
46:     private LatencyTrackingStateFactory(
47:             InternalKvState<K, N, ?> kvState,
48:             StateDescriptor<S, V> stateDescriptor,
49:             LatencyTrackingStateConfig latencyTrackingStateConfig) {
50:         this.kvState = kvState;
51:         this.stateDescriptor = stateDescriptor;
52:         this.latencyTrackingStateConfig = latencyTrackingStateConfig;
53:         this.stateFactories = createStateFactories();
54:     }
