56:     /** Create latency tracking state if enabled. */
57:     public static <K, N, V, S extends State>
58:             InternalKvState<K, N, ?> createStateAndWrapWithLatencyTrackingIfEnabled(
59:                     InternalKvState<K, N, ?> kvState,
60:                     StateDescriptor<S, V> stateDescriptor,
61:                     LatencyTrackingStateConfig latencyTrackingStateConfig)
62:                     throws Exception {
63:         if (latencyTrackingStateConfig.isEnabled()) {
64:             return new LatencyTrackingStateFactory<>(
65:                             kvState, stateDescriptor, latencyTrackingStateConfig)
66:                     .createState();
67:         }
68:         return kvState;
69:     }
70: 
71:     private Map<StateDescriptor.Type, SupplierWithException<IS, Exception>> createStateFactories() {
72:         return Stream.of(
73:                         Tuple2.of(
74:                                 StateDescriptor.Type.VALUE,
75:                                 (SupplierWithException<IS, Exception>) this::createValueState),
76:                         Tuple2.of(
77:                                 StateDescriptor.Type.LIST,
78:                                 (SupplierWithException<IS, Exception>) this::createListState),
79:                         Tuple2.of(
80:                                 StateDescriptor.Type.MAP,
81:                                 (SupplierWithException<IS, Exception>) this::createMapState),
