346:          * @param jobManagerState the state that the task got assigned from the job manager (this
347:          *     state lives in remote storage).
348:          * @param alternativesByPriority local alternatives to the job manager state, ordered by
349:          *     priority.
350:          * @param identityExtractor function to extract an identifier from a state object.
351:          * @return prioritized state alternatives.
352:          * @param <STATE_OBJ_TYPE> the type of the state objects we process.
353:          * @param <ID_TYPE> the type of object that represents the id the state object type.
354:          */
355:         <STATE_OBJ_TYPE extends StateObject, ID_TYPE>
356:                 List<StateObjectCollection<STATE_OBJ_TYPE>> computePrioritizedAlternatives(
357:                         StateObjectCollection<STATE_OBJ_TYPE> jobManagerState,
358:                         List<StateObjectCollection<STATE_OBJ_TYPE>> alternativesByPriority,
359:                         Function<STATE_OBJ_TYPE, ID_TYPE> identityExtractor) {
360: 
361:             if (alternativesByPriority != null
362:                     && !alternativesByPriority.isEmpty()
363:                     && jobManagerState.hasState()) {
364: 
365:                 Optional<StateObjectCollection<STATE_OBJ_TYPE>> mergedAlternative =
366:                         tryComputeMixedLocalAndRemoteAlternative(
367:                                 jobManagerState, alternativesByPriority, identityExtractor);
368: 
369:                 // Return the mix of local/remote state as first and pure remote state as second
370:                 // alternative (in case that we fail to recover from the local state, e.g. because
371:                 // of corruption).
372:                 if (mergedAlternative.isPresent()) {
373:                     return Arrays.asList(mergedAlternative.get(), jobManagerState);
374:                 }
375:             }
376: 
377:             return Collections.singletonList(jobManagerState);
