443:         /**
444:          * This helper method resolves the dependencies between the ground truth of the operator
445:          * state obtained from the job manager and potential alternatives for recovery, e.g. from a
446:          * task-local source.
447:          */
448:         <T extends StateObject> List<StateObjectCollection<T>> resolvePrioritizedAlternatives(
449:                 StateObjectCollection<T> jobManagerState,
450:                 List<StateObjectCollection<T>> alternativesByPriority,
451:                 BiFunction<T, T, Boolean> approveFun) {
452: 
453:             // Nothing to resolve if there are no alternatives, or the ground truth has already no
454:             // state, or if we can assume that a rescaling happened because we find more than one
455:             // handle in the JM state
456:             // (this is more a sanity check).
457:             if (alternativesByPriority == null
458:                     || alternativesByPriority.isEmpty()
459:                     || !jobManagerState.hasState()
460:                     || jobManagerState.size() != 1) {
461: 
462:                 return Collections.singletonList(jobManagerState);
463:             }
464: 
465:             // As we know size is == 1
466:             T reference = jobManagerState.iterator().next();
467: 
468:             // This will contain the end result, we initialize it with the potential max. size.
469:             List<StateObjectCollection<T>> approved =
470:                     new ArrayList<>(1 + alternativesByPriority.size());
471: 
472:             for (StateObjectCollection<T> alternative : alternativesByPriority) {
473: 
474:                 // We found an alternative to the JM state if it has state, we have a 1:1
475:                 // relationship, and the approve-function signaled true.
476:                 if (alternative != null
477:                         && alternative.hasState()
478:                         && alternative.size() == 1
479:                         && BooleanUtils.isTrue(
480:                                 approveFun.apply(reference, alternative.iterator().next()))) {
481: 
482:                     approved.add(alternative);
483:                 }
484:             }
485: 
486:             // Of course we include the ground truth as last alternative.
487:             approved.add(jobManagerState);
488:             return Collections.unmodifiableList(approved);
489:         }
490:     }
