394:          * @param <ID_TYPE> the type of object that represents the id the state object type.
395:          */
396:         static <STATE_OBJ_TYPE extends StateObject, ID_TYPE>
397:                 Optional<StateObjectCollection<STATE_OBJ_TYPE>>
398:                         tryComputeMixedLocalAndRemoteAlternative(
399:                                 StateObjectCollection<STATE_OBJ_TYPE> jobManagerState,
400:                                 List<StateObjectCollection<STATE_OBJ_TYPE>> alternativesByPriority,
401:                                 Function<STATE_OBJ_TYPE, ID_TYPE> identityExtractor) {
402: 
403:             List<STATE_OBJ_TYPE> result = Collections.emptyList();
404: 
405:             // Build hash index over ids of the JM state
406:             Map<ID_TYPE, STATE_OBJ_TYPE> indexById =
407:                     jobManagerState.stream()
408:                             .collect(Collectors.toMap(identityExtractor, Function.identity()));
409: 
410:             // Move through all alternative in order from high to low priority
411:             for (StateObjectCollection<STATE_OBJ_TYPE> alternative : alternativesByPriority) {
412:                 // Check all the state objects in the alternative if they can replace JM state
413:                 for (STATE_OBJ_TYPE stateHandle : alternative) {
414:                     // Remove the current state object's id from the index to check for a match
415:                     if (indexById.remove(identityExtractor.apply(stateHandle)) != null) {
416:                         if (result.isEmpty()) {
417:                             // Lazy init result collection
418:                             result = new ArrayList<>(jobManagerState.size());
419:                         }
420:                         // If the id was still in the index, replace with higher prio alternative
421:                         result.add(stateHandle);
422: 
423:                         // If the index is empty we are already done, all JM state was replaces with
424:                         // the best alternative.
425:                         if (indexById.isEmpty()) {
426:                             return Optional.of(new StateObjectCollection<>(result));
427:                         }
428:                     }
429:                 }
430:             }
431: 
432:             // Nothing useful to return
433:             if (result.isEmpty()) {
434:                 return Optional.empty();
435:             }
436: 
437:             // Add all remaining JM state objects that we could not replace from the index to the
438:             // final result
439:             result.addAll(indexById.values());
440:             return Optional.of(new StateObjectCollection<>(result));
441:         }
442: 
443:         /**
444:          * This helper method resolves the dependencies between the ground truth of the operator
445:          * state obtained from the job manager and potential alternatives for recovery, e.g. from a
446:          * task-local source.
447:          */
448:         <T extends StateObject> List<StateObjectCollection<T>> resolvePrioritizedAlternatives(
449:                 StateObjectCollection<T> jobManagerState,
450:                 List<StateObjectCollection<T>> alternativesByPriority,
451:                 BiFunction<T, T, Boolean> approveFun) {
452: 
453:             // Nothing to resolve if there are no alternatives, or the ground truth has already no
454:             // state, or if we can assume that a rescaling happened because we find more than one
455:             // handle in the JM state
456:             // (this is more a sanity check).
457:             if (alternativesByPriority == null
458:                     || alternativesByPriority.isEmpty()
459:                     || !jobManagerState.hasState()
460:                     || jobManagerState.size() != 1) {
461: 
462:                 return Collections.singletonList(jobManagerState);
463:             }
464: 
465:             // As we know size is == 1
466:             T reference = jobManagerState.iterator().next();
467: 
468:             // This will contain the end result, we initialize it with the potential max. size.
469:             List<StateObjectCollection<T>> approved =
470:                     new ArrayList<>(1 + alternativesByPriority.size());
471: 
472:             for (StateObjectCollection<T> alternative : alternativesByPriority) {
473: 
474:                 // We found an alternative to the JM state if it has state, we have a 1:1
475:                 // relationship, and the approve-function signaled true.
476:                 if (alternative != null
477:                         && alternative.hasState()
478:                         && alternative.size() == 1
479:                         && BooleanUtils.isTrue(
480:                                 approveFun.apply(reference, alternative.iterator().next()))) {
481: 
482:                     approved.add(alternative);
483:                 }
484:             }
485: 
486:             // Of course we include the ground truth as last alternative.
487:             approved.add(jobManagerState);
488:             return Collections.unmodifiableList(approved);
489:         }
490:     }
491: 
492:     private static <T extends ChannelState, Info> BiFunction<T, T, Boolean> channelStateApprover(
493:             Comparator<Info> comparator) {
494:         return (ref, alt) -> approveChannelState(ref, alt, comparator);
495:     }
496: 
497:     private static <Info> boolean approveChannelState(
498:             ChannelState ref, ChannelState alt, Comparator<Info> comparator) {
499:         List<Info> refInfos = extractInfos(ref, comparator);
500:         List<Info> altInfos = extractInfos(alt, comparator);
501: 
502:         if (refInfos.size() != altInfos.size()) {
503:             return false;
504:         }
505: 
506:         Iterator<Info> refInfoIterator = refInfos.iterator();
507:         Iterator<Info> altInfoIterator = altInfos.iterator();
508:         while (refInfoIterator.hasNext()) {
509:             Info refInfo = refInfoIterator.next();
510:             Info altInfo = altInfoIterator.next();
511:             if (!refInfo.equals(altInfo)) {
512:                 return false;
513:             }
514:         }
515: 
516:         return true;
517:     }
518: 
519:     /** return sorted info list extracted from the passed in handle. */
520:     private static <Info> List<Info> extractInfos(
521:             ChannelState handle, Comparator<Info> comparator) {
522:         if (handle instanceof AbstractChannelStateHandle) {
523:             return Collections.singletonList(((AbstractChannelStateHandle<Info>) handle).getInfo());
524:         } else {
525:             throw new IllegalStateException(
526:                     "Not supported InputStateHandle : " + handle.getClass());
527:         }
528:     }
529: 
530:     private static <T, E> BiFunction<T, T, Boolean> eqStateApprover(
531:             Function<T, E> identityExtractor) {
532:         return (ref, alt) -> identityExtractor.apply(ref).equals(identityExtractor.apply(alt));
533:     }
534: }
