108:     private static void acknowledgeCheckpoint(
109:             CheckpointCoordinator coordinator,
110:             ExecutionGraph executionGraph,
111:             ExecutionJobVertex jobVertex,
112:             long checkpointId)
113:             throws Exception {
114:         final List<KeyGroupRange> partitions =
115:                 StateAssignmentOperation.createKeyGroupPartitions(
116:                         jobVertex.getMaxParallelism(), jobVertex.getParallelism());
117:         for (int partitionIdx = 0; partitionIdx < partitions.size(); partitionIdx++) {
118:             TaskStateSnapshot subtaskState =
119:                     mockSubtaskState(
120:                             jobVertex.getJobVertexId(), partitionIdx, partitions.get(partitionIdx));
121:             final AcknowledgeCheckpoint acknowledgeCheckpoint =
122:                     new AcknowledgeCheckpoint(
123:                             executionGraph.getJobID(),
124:                             jobVertex
125:                                     .getTaskVertices()[partitionIdx]
126:                                     .getCurrentExecutionAttempt()
127:                                     .getAttemptId(),
128:                             checkpointId,
129:                             new CheckpointMetrics(),
130:                             subtaskState);
131:             coordinator.receiveAcknowledgeMessage(
132:                     acknowledgeCheckpoint, TASK_MANAGER_LOCATION_INFO);
133:         }
134:     }
