196:     private Collection<CompletedCheckpoint>
197:             testSuccessfulCheckpointsArePersistedToCompletedCheckpointStore(
198:                     List<TestingVertex> vertices) throws Exception {
199:         final ExecutionGraph executionGraph = createExecutionGraph(vertices);
200:         final EmbeddedCompletedCheckpointStore store = new EmbeddedCompletedCheckpointStore();
201: 
202:         // set up the coordinator and validate the initial state
203:         final CheckpointCoordinator coordinator =
204:                 new CheckpointCoordinatorBuilder()
205:                         .setTimer(manuallyTriggeredScheduledExecutor)
206:                         .setCompletedCheckpointStore(store)
207:                         .build(executionGraph);
208: 
209:         // trigger the checkpoint
210:         coordinator.triggerCheckpoint(false);
211:         manuallyTriggeredScheduledExecutor.triggerAll();
212: 
213:         // we should have a single pending checkpoint
214:         assertThat(coordinator.getPendingCheckpoints().size()).isOne();
215:         final long checkpointId =
216:                 Iterables.getOnlyElement(coordinator.getPendingCheckpoints().keySet());
217: 
218:         // acknowledge checkpoints from all vertex partitions
219:         for (TestingVertex vertex : vertices) {
220:             final ExecutionJobVertex executionVertex =
221:                     Objects.requireNonNull(executionGraph.getJobVertex(vertex.getId()));
222:             acknowledgeCheckpoint(coordinator, executionGraph, executionVertex, checkpointId);
223:         }
224: 
225:         final List<CompletedCheckpoint> completedCheckpoints =
226:                 coordinator.getSuccessfulCheckpoints();
227:         assertThat(completedCheckpoints.size()).isOne();
228: 
229:         // shutdown the store
230:         store.shutdown(JobStatus.SUSPENDED, new CheckpointsCleaner());
231: 
232:         return store.getAllCheckpoints();
233:     }
