235:     private void testRestoreLatestCheckpointedState(
236:             List<TestingVertex> vertices, Collection<CompletedCheckpoint> completedCheckpoints)
237:             throws Exception {
238:         final ExecutionGraph executionGraph = createExecutionGraph(vertices);
239:         final EmbeddedCompletedCheckpointStore store =
240:                 new EmbeddedCompletedCheckpointStore(
241:                         completedCheckpoints.size(),
242:                         completedCheckpoints,
243:                         RecoveryClaimMode.DEFAULT);
244: 
245:         // set up the coordinator and validate the initial state
246:         final CheckpointCoordinator coordinator =
247:                 new CheckpointCoordinatorBuilder()
248:                         .setTimer(manuallyTriggeredScheduledExecutor)
249:                         .setCompletedCheckpointStore(store)
250:                         .build(executionGraph);
251: 
252:         final Set<ExecutionJobVertex> executionVertices =
253:                 vertices.stream()
254:                         .map(TestingVertex::getId)
255:                         .map(executionGraph::getJobVertex)
256:                         .collect(Collectors.toSet());
257:         assertThat(coordinator.restoreLatestCheckpointedStateToAll(executionVertices, false))
258:                 .isTrue();
259: 
260:         // validate that all shared states are registered again after the recovery.
261:         for (CompletedCheckpoint completedCheckpoint : completedCheckpoints) {
262:             for (OperatorState taskState : completedCheckpoint.getOperatorStates().values()) {
263:                 for (OperatorSubtaskState subtaskState : taskState.getStates()) {
264:                     verify(subtaskState, times(2))
265:                             .registerSharedStates(
266:                                     any(SharedStateRegistry.class),
267:                                     eq(completedCheckpoint.getCheckpointID()));
268:                 }
269:             }
270:         }
271: 
272:         // verify the restored state
273:         for (ExecutionJobVertex executionVertex : executionVertices) {
274:             verifyStateRestore(executionVertex);
275:         }
276:     }
