952:     static CompletedCheckpointStore storeFor(
953:             SharedStateRegistry sharedStateRegistry,
954:             Runnable postCleanupAction,
955:             CompletedCheckpoint... checkpoints)
956:             throws Exception {
957:         StandaloneCompletedCheckpointStore store =
958:                 new StandaloneCompletedCheckpointStore(checkpoints.length);
959:         CheckpointsCleaner checkpointsCleaner = new CheckpointsCleaner();
960:         for (final CompletedCheckpoint checkpoint : checkpoints) {
961:             store.addCheckpointAndSubsumeOldestOne(
962:                     checkpoint, checkpointsCleaner, postCleanupAction);
963:         }
964:         return store;
965:     }
