50: /**
51:  * This runnable executes the asynchronous parts of all involved backend snapshots for the subtask.
52:  */
53: final class AsyncCheckpointRunnable implements Runnable, Closeable {
54: 
55:     public static final Logger LOG = LoggerFactory.getLogger(AsyncCheckpointRunnable.class);
56:     private final String taskName;
57:     private final Consumer<AsyncCheckpointRunnable> unregisterConsumer;
58:     private final boolean isTaskDeployedAsFinished;
59:     private final boolean isTaskFinished;
60:     private final Supplier<Boolean> isTaskRunning;
61:     private final Environment taskEnvironment;
62:     private final CompletableFuture<Void> finishedFuture = new CompletableFuture<>();
63: 
64:     public boolean isRunning() {
65:         return asyncCheckpointState.get() == AsyncCheckpointState.RUNNING;
66:     }
67: 
68:     enum AsyncCheckpointState {
69:         RUNNING,
70:         DISCARDED,
71:         COMPLETED
72:     }
73: 
74:     private final AsyncExceptionHandler asyncExceptionHandler;
75:     private final Map<OperatorID, OperatorSnapshotFutures> operatorSnapshotsInProgress;
76:     private final CheckpointMetaData checkpointMetaData;
77:     private final CheckpointMetricsBuilder checkpointMetrics;
78:     private final long asyncConstructionNanos;
79:     private final AtomicReference<AsyncCheckpointState> asyncCheckpointState =
80:             new AtomicReference<>(AsyncCheckpointState.RUNNING);
81: 
82:     AsyncCheckpointRunnable(
83:             Map<OperatorID, OperatorSnapshotFutures> operatorSnapshotsInProgress,
84:             CheckpointMetaData checkpointMetaData,
85:             CheckpointMetricsBuilder checkpointMetrics,
86:             long asyncConstructionNanos,
87:             String taskName,
88:             Consumer<AsyncCheckpointRunnable> unregister,
89:             Environment taskEnvironment,
90:             AsyncExceptionHandler asyncExceptionHandler,
91:             boolean isTaskDeployedAsFinished,
92:             boolean isTaskFinished,
93:             Supplier<Boolean> isTaskRunning) {
94: 
95:         this.operatorSnapshotsInProgress = checkNotNull(operatorSnapshotsInProgress);
96:         this.checkpointMetaData = checkNotNull(checkpointMetaData);
97:         this.checkpointMetrics = checkNotNull(checkpointMetrics);
98:         this.asyncConstructionNanos = asyncConstructionNanos;
99:         this.taskName = checkNotNull(taskName);
100:         this.unregisterConsumer = unregister;
101:         this.taskEnvironment = checkNotNull(taskEnvironment);
102:         this.asyncExceptionHandler = checkNotNull(asyncExceptionHandler);
103:         this.isTaskDeployedAsFinished = isTaskDeployedAsFinished;
104:         this.isTaskFinished = isTaskFinished;
105:         this.isTaskRunning = isTaskRunning;
106:     }
107: 
108:     @Override
109:     public void run() {
110:         final long asyncStartNanos = System.nanoTime();
111:         final long asyncStartDelayMillis = (asyncStartNanos - asyncConstructionNanos) / 1_000_000L;
112:         LOG.debug(
113:                 "{} - started executing asynchronous part of checkpoint {}. Asynchronous start delay: {} ms",
114:                 taskName,
115:                 checkpointMetaData.getCheckpointId(),
116:                 asyncStartDelayMillis);
117: 
118:         FileSystemSafetyNet.initializeSafetyNetForThread();
119:         try {
120: 
121:             SnapshotsFinalizeResult snapshotsFinalizeResult =
122:                     isTaskDeployedAsFinished
123:                             ? finalizedFinishedSnapshots()
124:                             : finalizeNonFinishedSnapshots();
125: 
126:             final long asyncEndNanos = System.nanoTime();
127:             final long asyncDurationMillis = (asyncEndNanos - asyncConstructionNanos) / 1_000_000L;
128: 
129:             checkpointMetrics.setBytesPersistedDuringAlignment(
130:                     snapshotsFinalizeResult.bytesPersistedDuringAlignment);
131:             checkpointMetrics.setAsyncDurationMillis(asyncDurationMillis);
132: 
133:             if (asyncCheckpointState.compareAndSet(
134:                     AsyncCheckpointState.RUNNING, AsyncCheckpointState.COMPLETED)) {
135: 
136:                 reportCompletedSnapshotStates(
137:                         snapshotsFinalizeResult.jobManagerTaskOperatorSubtaskStates,
138:                         snapshotsFinalizeResult.localTaskOperatorSubtaskStates,
139:                         asyncDurationMillis);
140: 
141:             } else {
142:                 LOG.debug(
143:                         "{} - asynchronous part of checkpoint {} could not be completed because it was closed before.",
144:                         taskName,
145:                         checkpointMetaData.getCheckpointId());
146:             }
147: 
148:             finishedFuture.complete(null);
149:         } catch (Exception e) {
150:             LOG.info(
151:                     "{} - asynchronous part of checkpoint {} could not be completed.",
152:                     taskName,
153:                     checkpointMetaData.getCheckpointId(),
154:                     e);
155:             handleExecutionException(e);
156:             finishedFuture.completeExceptionally(e);
157:         } finally {
158:             unregisterConsumer.accept(this);
159:             FileSystemSafetyNet.closeSafetyNetAndGuardedResourcesForThread();
160:         }
161:     }
162: 
163:     private SnapshotsFinalizeResult finalizedFinishedSnapshots() throws Exception {
164:         for (Map.Entry<OperatorID, OperatorSnapshotFutures> entry :
165:                 operatorSnapshotsInProgress.entrySet()) {
166:             OperatorSnapshotFutures snapshotInProgress = entry.getValue();
167:             // We should wait for the channels states get completed before continuing,
168:             // otherwise the alignment of barriers might have not finished yet.
169:             snapshotInProgress.getInputChannelStateFuture().get();
170:             snapshotInProgress.getOutputStateHandleFuture().get();
171:         }
172: 
173:         return new SnapshotsFinalizeResult(
174:                 TaskStateSnapshot.FINISHED_ON_RESTORE, TaskStateSnapshot.FINISHED_ON_RESTORE, 0L);
175:     }
176: 
177:     private SnapshotsFinalizeResult finalizeNonFinishedSnapshots() throws Exception {
178:         TaskStateSnapshot jobManagerTaskOperatorSubtaskStates =
179:                 new TaskStateSnapshot(operatorSnapshotsInProgress.size(), isTaskFinished);
180:         TaskStateSnapshot localTaskOperatorSubtaskStates =
181:                 new TaskStateSnapshot(operatorSnapshotsInProgress.size(), isTaskFinished);
182: 
183:         long bytesPersistedDuringAlignment = 0;
184:         for (Map.Entry<OperatorID, OperatorSnapshotFutures> entry :
185:                 operatorSnapshotsInProgress.entrySet()) {
186: 
187:             OperatorID operatorID = entry.getKey();
188:             OperatorSnapshotFutures snapshotInProgress = entry.getValue();
189: 
190:             // finalize the async part of all by executing all snapshot runnables
191:             OperatorSnapshotFinalizer finalizedSnapshots =
192:                     new OperatorSnapshotFinalizer(snapshotInProgress);
193: 
194:             jobManagerTaskOperatorSubtaskStates.putSubtaskStateByOperatorID(
195:                     operatorID, finalizedSnapshots.getJobManagerOwnedState());
196: 
197:             localTaskOperatorSubtaskStates.putSubtaskStateByOperatorID(
198:                     operatorID, finalizedSnapshots.getTaskLocalState());
199: 
200:             bytesPersistedDuringAlignment +=
201:                     finalizedSnapshots
202:                             .getJobManagerOwnedState()
203:                             .getResultSubpartitionState()
204:                             .getStateSize();
205:             bytesPersistedDuringAlignment +=
206:                     finalizedSnapshots
207:                             .getJobManagerOwnedState()
208:                             .getInputChannelState()
209:                             .getStateSize();
210:         }
211: 
212:         return new SnapshotsFinalizeResult(
213:                 jobManagerTaskOperatorSubtaskStates,
214:                 localTaskOperatorSubtaskStates,
215:                 bytesPersistedDuringAlignment);
216:     }
217: 
218:     private void reportCompletedSnapshotStates(
219:             TaskStateSnapshot acknowledgedTaskStateSnapshot,
220:             TaskStateSnapshot localTaskStateSnapshot,
221:             long asyncDurationMillis) {
222: 
223:         boolean hasAckState = acknowledgedTaskStateSnapshot.hasState();
224:         boolean hasLocalState = localTaskStateSnapshot.hasState();
225: 
226:         checkState(
227:                 hasAckState || !hasLocalState,
228:                 "Found cached state but no corresponding primary state is reported to the job "
229:                         + "manager. This indicates a problem.");
230: 
231:         // we signal stateless tasks by reporting null, so that there are no attempts to assign
232:         // empty state
233:         // to stateless tasks on restore. This enables simple job modifications that only concern
234:         // stateless without the need to assign them uids to match their (always empty) states.
235:         taskEnvironment
236:                 .getTaskStateManager()
237:                 .reportTaskStateSnapshots(
238:                         checkpointMetaData,
239:                         checkpointMetrics
240:                                 .setBytesPersistedOfThisCheckpoint(
241:                                         acknowledgedTaskStateSnapshot.getCheckpointedSize())
242:                                 .setTotalBytesPersisted(
243:                                         acknowledgedTaskStateSnapshot.getStateSize())
244:                                 .build(),
245:                         hasAckState ? acknowledgedTaskStateSnapshot : null,
246:                         hasLocalState ? localTaskStateSnapshot : null);
247: 
248:         LOG.debug(
249:                 "{} - finished asynchronous part of checkpoint {}. Asynchronous duration: {} ms",
250:                 taskName,
251:                 checkpointMetaData.getCheckpointId(),
252:                 asyncDurationMillis);
253: 
254:         LOG.trace(
255:                 "{} - reported the following states in snapshot for checkpoint {}: {}.",
256:                 taskName,
257:                 checkpointMetaData.getCheckpointId(),
258:                 acknowledgedTaskStateSnapshot);
259:     }
260: 
261:     private void reportAbortedSnapshotStats(long stateSize, long checkpointedSize) {
262:         CheckpointMetrics metrics =
263:                 checkpointMetrics
264:                         .setTotalBytesPersisted(stateSize)
265:                         .setBytesPersistedOfThisCheckpoint(checkpointedSize)
266:                         .buildIncomplete();
267:         LOG.trace(
268:                 "{} - report failed checkpoint stats: {} {}",
269:                 taskName,
270:                 checkpointMetaData.getCheckpointId(),
271:                 metrics);
272: 
273:         taskEnvironment
274:                 .getTaskStateManager()
275:                 .reportIncompleteTaskStateSnapshots(checkpointMetaData, metrics);
276:     }
277: 
278:     private void handleExecutionException(Exception e) {
279: 
280:         boolean didCleanup = false;
281:         AsyncCheckpointState currentState = asyncCheckpointState.get();
282: 
283:         while (AsyncCheckpointState.DISCARDED != currentState) {
284: 
285:             if (asyncCheckpointState.compareAndSet(currentState, AsyncCheckpointState.DISCARDED)) {
286: 
287:                 didCleanup = true;
288: 
289:                 try {
290:                     cleanup();
291:                 } catch (Exception cleanupException) {
292:                     e.addSuppressed(cleanupException);
293:                 }
294: 
295:                 Exception checkpointException =
296:                         new Exception(
297:                                 "Could not materialize checkpoint "
298:                                         + checkpointMetaData.getCheckpointId()
299:                                         + " for operator "
300:                                         + taskName
301:                                         + '.',
302:                                 e);
303: 
304:                 if (isTaskRunning.get()) {
305:                     // We only report the exception for the original cause of fail and cleanup.
306:                     // Otherwise this followup exception could race the original exception in
307:                     // failing the task.
308:                     try {
309:                         Optional<CheckpointException> underlyingCheckpointException =
310:                                 ExceptionUtils.findThrowable(
311:                                         checkpointException, CheckpointException.class);
312: 
313:                         // If this failure is already a CheckpointException, do not overwrite the
314:                         // original CheckpointFailureReason
315:                         CheckpointFailureReason reportedFailureReason =
316:                                 underlyingCheckpointException
317:                                         .map(exception -> exception.getCheckpointFailureReason())
318:                                         .orElse(CheckpointFailureReason.CHECKPOINT_ASYNC_EXCEPTION);
319:                         taskEnvironment.declineCheckpoint(
320:                                 checkpointMetaData.getCheckpointId(),
321:                                 new CheckpointException(
322:                                         reportedFailureReason, checkpointException));
323:                     } catch (Exception unhandled) {
324:                         AsynchronousException asyncException = new AsynchronousException(unhandled);
325:                         asyncExceptionHandler.handleAsyncException(
326:                                 "Failure in asynchronous checkpoint materialization",
327:                                 asyncException);
328:                     }
329:                 } else {
330:                     // We never decline checkpoint after task is not running to avoid unexpected job
331:                     // failover, which caused by exceeding checkpoint tolerable failure threshold.
332:                     LOG.info(
333:                             "Ignore decline of checkpoint {} as task is not running anymore.",
334:                             checkpointMetaData.getCheckpointId());
335:                 }
336: 
337:                 currentState = AsyncCheckpointState.DISCARDED;
338:             } else {
339:                 currentState = asyncCheckpointState.get();
340:             }
341:         }
342: 
343:         if (!didCleanup) {
344:             LOG.trace(
345:                     "Caught followup exception from a failed checkpoint thread. This can be ignored.",
346:                     e);
347:         }
348:     }
349: 
350:     @Override
351:     public void close() {
352:         if (asyncCheckpointState.compareAndSet(
353:                 AsyncCheckpointState.RUNNING, AsyncCheckpointState.DISCARDED)) {
354: 
355:             try {
356:                 final Tuple2<Long, Long> tuple = cleanup();
357:                 reportAbortedSnapshotStats(tuple.f0, tuple.f1);
358:             } catch (Exception cleanupException) {
359:                 LOG.warn(
360:                         "Could not properly clean up the async checkpoint runnable.",
361:                         cleanupException);
362:             }
363:         } else {
364:             logFailedCleanupAttempt();
365:         }
366:     }
367: 
368:     long getCheckpointId() {
369:         return checkpointMetaData.getCheckpointId();
370:     }
371: 
372:     public CompletableFuture<Void> getFinishedFuture() {
373:         return finishedFuture;
374:     }
375: 
376:     /**
377:      * @return discarded full/incremental size (if available).
378:      */
379:     private Tuple2<Long, Long> cleanup() throws Exception {
380:         LOG.debug(
381:                 "Cleanup AsyncCheckpointRunnable for checkpoint {} of {}.",
382:                 checkpointMetaData.getCheckpointId(),
383:                 taskName);
384: 
385:         Exception exception = null;
386: 
387:         // clean up ongoing operator snapshot results and non partitioned state handles
388:         long stateSize = 0, checkpointedSize = 0;
389:         for (OperatorSnapshotFutures operatorSnapshotResult :
390:                 operatorSnapshotsInProgress.values()) {
391:             if (operatorSnapshotResult != null) {
392:                 try {
393:                     Tuple2<Long, Long> tuple2 = operatorSnapshotResult.cancel();
394:                     stateSize += tuple2.f0;
395:                     checkpointedSize += tuple2.f1;
396:                 } catch (Exception cancelException) {
397:                     exception = ExceptionUtils.firstOrSuppressed(cancelException, exception);
398:                 }
399:             }
400:         }
401: 
402:         if (null != exception) {
403:             throw exception;
404:         }
405:         return Tuple2.of(stateSize, checkpointedSize);
406:     }
407: 
408:     private void logFailedCleanupAttempt() {
409:         LOG.debug(
410:                 "{} - asynchronous checkpointing operation for checkpoint {} has "
411:                         + "already been completed. Thus, the state handles are not cleaned up.",
412:                 taskName,
413:                 checkpointMetaData.getCheckpointId());
414:     }
415: 
416:     private static class SnapshotsFinalizeResult {
417:         final TaskStateSnapshot jobManagerTaskOperatorSubtaskStates;
418:         final TaskStateSnapshot localTaskOperatorSubtaskStates;
419:         final long bytesPersistedDuringAlignment;
420: 
421:         public SnapshotsFinalizeResult(
422:                 TaskStateSnapshot jobManagerTaskOperatorSubtaskStates,
423:                 TaskStateSnapshot localTaskOperatorSubtaskStates,
424:                 long bytesPersistedDuringAlignment) {
425:             this.jobManagerTaskOperatorSubtaskStates = jobManagerTaskOperatorSubtaskStates;
426:             this.localTaskOperatorSubtaskStates = localTaskOperatorSubtaskStates;
427:             this.bytesPersistedDuringAlignment = bytesPersistedDuringAlignment;
428:         }
429:     }
430: }
