278:     private void handleExecutionException(Exception e) {
279: 
280:         boolean didCleanup = false;
281:         AsyncCheckpointState currentState = asyncCheckpointState.get();
282: 
283:         while (AsyncCheckpointState.DISCARDED != currentState) {
284: 
285:             if (asyncCheckpointState.compareAndSet(currentState, AsyncCheckpointState.DISCARDED)) {
286: 
287:                 didCleanup = true;
288: 
289:                 try {
290:                     cleanup();
291:                 } catch (Exception cleanupException) {
292:                     e.addSuppressed(cleanupException);
293:                 }
