295:                 Exception checkpointException =
296:                         new Exception(
297:                                 "Could not materialize checkpoint "
298:                                         + checkpointMetaData.getCheckpointId()
299:                                         + " for operator "
300:                                         + taskName
301:                                         + '.',
302:                                 e);
303: 
304:                 if (isTaskRunning.get()) {
305:                     // We only report the exception for the original cause of fail and cleanup.
306:                     // Otherwise this followup exception could race the original exception in
307:                     // failing the task.
308:                     try {
309:                         Optional<CheckpointException> underlyingCheckpointException =
310:                                 ExceptionUtils.findThrowable(
311:                                         checkpointException, CheckpointException.class);
312: 
313:                         // If this failure is already a CheckpointException, do not overwrite the
314:                         // original CheckpointFailureReason
315:                         CheckpointFailureReason reportedFailureReason =
316:                                 underlyingCheckpointException
317:                                         .map(exception -> exception.getCheckpointFailureReason())
318:                                         .orElse(CheckpointFailureReason.CHECKPOINT_ASYNC_EXCEPTION);
319:                         taskEnvironment.declineCheckpoint(
320:                                 checkpointMetaData.getCheckpointId(),
321:                                 new CheckpointException(
322:                                         reportedFailureReason, checkpointException));
323:                     } catch (Exception unhandled) {
324:                         AsynchronousException asyncException = new AsynchronousException(unhandled);
325:                         asyncExceptionHandler.handleAsyncException(
