95:     @GuardedBy("lock")
96:     private State state = State.RUNNING;
97: 
98:     @GuardedBy("lock")
99:     private CompletableFuture<Void> sequentialOperation = FutureUtils.completedVoidFuture();
100: 
101:     @GuardedBy("lock")
102:     private JobMasterServiceProcess jobMasterServiceProcess =
103:             JobMasterServiceProcess.waitingForLeadership();
104: 
105:     @GuardedBy("lock")
106:     private CompletableFuture<JobMasterGateway> jobMasterGatewayFuture = new CompletableFuture<>();
107: 
108:     @GuardedBy("lock")
109:     private boolean hasCurrentLeaderBeenCancelled = false;
110: 
111:     public JobMasterServiceLeadershipRunner(
112:             JobMasterServiceProcessFactory jobMasterServiceProcessFactory,
113:             LeaderElection leaderElection,
114:             JobResultStore jobResultStore,
115:             LibraryCacheManager.ClassLoaderLease classLoaderLease,
116:             FatalErrorHandler fatalErrorHandler) {
117:         this.jobMasterServiceProcessFactory = jobMasterServiceProcessFactory;
118:         this.leaderElection = leaderElection;
119:         this.jobResultStore = jobResultStore;
120:         this.classLoaderLease = classLoaderLease;
121:         this.fatalErrorHandler = fatalErrorHandler;
122:     }
123: 
124:     @Override
125:     public CompletableFuture<Void> closeAsync() {
126:         final CompletableFuture<Void> processTerminationFuture;
127:         synchronized (lock) {
128:             if (state == State.STOPPED) {
129:                 return terminationFuture;
130:             }
131: 
132:             state = State.STOPPED;
133: 
134:             LOG.debug("Terminating the leadership runner for job {}.", getJobID());
135: 
136:             jobMasterGatewayFuture.completeExceptionally(
137:                     new FlinkException(
138:                             "JobMasterServiceLeadershipRunner is closed. Therefore, the corresponding JobMaster will never acquire the leadership."));
139: 
140:             resultFuture.complete(
141:                     JobManagerRunnerResult.forSuccess(
142:                             createExecutionGraphInfoWithJobStatus(JobStatus.SUSPENDED)));
143: 
144:             processTerminationFuture = jobMasterServiceProcess.closeAsync();
145:         }
146: 
147:         final CompletableFuture<Void> serviceTerminationFuture =
148:                 FutureUtils.runAfterwards(
149:                         processTerminationFuture,
150:                         () -> {
151:                             classLoaderLease.release();
152:                             leaderElection.close();
153:                         });
154: 
155:         FutureUtils.forward(serviceTerminationFuture, terminationFuture);
156: 
157:         terminationFuture.whenComplete(
158:                 (unused, throwable) ->
159:                         LOG.debug("Leadership runner for job {} has been terminated.", getJobID()));
160:         return terminationFuture;
161:     }
162: 
163:     @Override
164:     public void start() throws Exception {
165:         LOG.debug("Start leadership runner for job {}.", getJobID());
166:         leaderElection.startLeaderElection(this);
167:     }
168: 
169:     @Override
170:     public CompletableFuture<JobMasterGateway> getJobMasterGateway() {
171:         synchronized (lock) {
172:             return jobMasterGatewayFuture;
173:         }
174:     }
175: 
176:     @Override
177:     public CompletableFuture<JobManagerRunnerResult> getResultFuture() {
178:         return resultFuture;
179:     }
180: 
181:     @Override
182:     public JobID getJobID() {
183:         return jobMasterServiceProcessFactory.getJobId();
184:     }
185: 
186:     @Override
187:     public CompletableFuture<Acknowledge> cancel(Duration timeout) {
188:         synchronized (lock) {
189:             hasCurrentLeaderBeenCancelled = true;
190:             return getJobMasterGateway()
191:                     .thenCompose(jobMasterGateway -> jobMasterGateway.cancel(timeout))
192:                     .exceptionally(
193:                             e -> {
194:                                 throw new CompletionException(
195:                                         new JobCancellationFailedException(
196:                                                 "Cancellation failed.",
197:                                                 ExceptionUtils.stripCompletionException(e)));
198:                             });
199:         }
200:     }
201: 
202:     @Override
203:     public CompletableFuture<JobStatus> requestJobStatus(Duration timeout) {
204:         return requestJob(timeout)
205:                 .thenApply(
206:                         executionGraphInfo ->
207:                                 executionGraphInfo.getArchivedExecutionGraph().getState());
208:     }
209: 
210:     @Override
211:     public CompletableFuture<JobDetails> requestJobDetails(Duration timeout) {
212:         return requestJob(timeout)
213:                 .thenApply(
214:                         executionGraphInfo ->
215:                                 JobDetails.createDetailsForJob(
216:                                         executionGraphInfo.getArchivedExecutionGraph()));
217:     }
218: 
219:     @Override
220:     public CompletableFuture<ExecutionGraphInfo> requestJob(Duration timeout) {
221:         synchronized (lock) {
222:             if (state == State.RUNNING) {
223:                 if (jobMasterServiceProcess.isInitializedAndRunning()) {
224:                     return getJobMasterGateway()
225:                             .thenCompose(jobMasterGateway -> jobMasterGateway.requestJob(timeout));
226:                 } else {
227:                     return CompletableFuture.completedFuture(
228:                             createExecutionGraphInfoWithJobStatus(
229:                                     hasCurrentLeaderBeenCancelled
230:                                             ? JobStatus.CANCELLING
231:                                             : JobStatus.INITIALIZING));
232:                 }
233:             } else {
234:                 return resultFuture.thenApply(JobManagerRunnerResult::getExecutionGraphInfo);
235:             }
236:         }
237:     }
238: 
239:     @Override
240:     public boolean isInitialized() {
241:         synchronized (lock) {
242:             return jobMasterServiceProcess.isInitializedAndRunning();
243:         }
244:     }
245: 
246:     @Override
247:     public void grantLeadership(UUID leaderSessionID) {
248:         runIfStateRunning(
249:                 () -> startJobMasterServiceProcessAsync(leaderSessionID),
250:                 "starting a new JobMasterServiceProcess");
251:     }
252: 
253:     @GuardedBy("lock")
254:     private void startJobMasterServiceProcessAsync(UUID leaderSessionId) {
255:         sequentialOperation =
256:                 sequentialOperation.thenCompose(
257:                         unused ->
258:                                 jobResultStore
259:                                         .hasJobResultEntryAsync(getJobID())
260:                                         .thenAccept(
261:                                                 hasJobResult -> {
262:                                                     if (hasJobResult) {
263:                                                         handleJobAlreadyDoneIfValidLeader(
264:                                                                 leaderSessionId);
265:                                                     } else {
266:                                                         createNewJobMasterServiceProcessIfValidLeader(
267:                                                                 leaderSessionId);
268:                                                     }
269:                                                 }));
270:         handleAsyncOperationError(sequentialOperation, "Could not start the job manager.");
271:     }
272: 
273:     private void handleJobAlreadyDoneIfValidLeader(UUID leaderSessionId) {
274:         runIfValidLeader(
275:                 leaderSessionId, () -> jobAlreadyDone(leaderSessionId), "check completed job");
276:     }
277: 
278:     private void createNewJobMasterServiceProcessIfValidLeader(UUID leaderSessionId) {
279:         runIfValidLeader(
280:                 leaderSessionId,
281:                 () ->
282:                         ThrowingRunnable.unchecked(
283:                                         () -> createNewJobMasterServiceProcess(leaderSessionId))
284:                                 .run(),
285:                 "create new job master service process");
286:     }
287: 
288:     private void printLogIfNotValidLeader(String actionDescription, UUID leaderSessionId) {
289:         LOG.debug(
290:                 "Ignore leader action '{}' because the leadership runner is no longer the valid leader for {}.",
291:                 actionDescription,
292:                 leaderSessionId);
293:     }
294: 
295:     private ExecutionGraphInfo createExecutionGraphInfoWithJobStatus(JobStatus jobStatus) {
296:         return new ExecutionGraphInfo(
297:                 jobMasterServiceProcessFactory.createArchivedExecutionGraph(jobStatus, null));
298:     }
299: 
300:     private void jobAlreadyDone(UUID leaderSessionId) {
301:         LOG.info(
302:                 "{} for job {} was granted leadership with leader id {}, but job was already done.",
303:                 getClass().getSimpleName(),
304:                 getJobID(),
305:                 leaderSessionId);
306:         resultFuture.complete(
307:                 JobManagerRunnerResult.forSuccess(
308:                         new ExecutionGraphInfo(
309:                                 jobMasterServiceProcessFactory.createArchivedExecutionGraph(
310:                                         JobStatus.FAILED,
311:                                         new JobAlreadyDoneException(getJobID())))));
312:     }
313: 
314:     @GuardedBy("lock")
315:     private void createNewJobMasterServiceProcess(UUID leaderSessionId) {
316:         Preconditions.checkState(jobMasterServiceProcess.closeAsync().isDone());
317: 
318:         LOG.info(
319:                 "{} for job {} was granted leadership with leader id {}. Creating new {}.",
320:                 getClass().getSimpleName(),
321:                 getJobID(),
322:                 leaderSessionId,
323:                 JobMasterServiceProcess.class.getSimpleName());
324: 
325:         jobMasterServiceProcess = jobMasterServiceProcessFactory.create(leaderSessionId);
326: 
327:         forwardIfValidLeader(
328:                 leaderSessionId,
329:                 jobMasterServiceProcess.getJobMasterGatewayFuture(),
330:                 jobMasterGatewayFuture,
331:                 "JobMasterGatewayFuture from JobMasterServiceProcess");
332:         forwardResultFuture(leaderSessionId, jobMasterServiceProcess.getResultFuture());
333:         confirmLeadership(leaderSessionId, jobMasterServiceProcess.getLeaderAddressFuture());
334:     }
335: 
336:     private void confirmLeadership(
337:             UUID leaderSessionId, CompletableFuture<String> leaderAddressFuture) {
338:         FutureUtils.assertNoException(
339:                 leaderAddressFuture.thenAccept(
340:                         address ->
341:                                 runIfStateRunning(
342:                                         () -> {
343:                                             LOG.debug("Confirm leadership {}.", leaderSessionId);
344:                                             leaderElection.confirmLeadershipAsync(
345:                                                     leaderSessionId, address);
346:                                         },
347:                                         "confirming leadership")));
348:     }
349: 
350:     private void forwardResultFuture(
351:             UUID leaderSessionId, CompletableFuture<JobManagerRunnerResult> resultFuture) {
352:         resultFuture.whenComplete(
353:                 (jobManagerRunnerResult, throwable) ->
354:                         runIfValidLeader(
355:                                 leaderSessionId,
356:                                 () -> onJobCompletion(jobManagerRunnerResult, throwable),
357:                                 "result future forwarding"));
358:     }
359: 
360:     @GuardedBy("lock")
361:     private void onJobCompletion(
362:             JobManagerRunnerResult jobManagerRunnerResult, Throwable throwable) {
363:         state = State.JOB_COMPLETED;
364: 
365:         LOG.debug("Completing the result for job {}.", getJobID());
366: 
367:         if (throwable != null) {
368:             resultFuture.completeExceptionally(throwable);
369:             jobMasterGatewayFuture.completeExceptionally(
370:                     new FlinkException(
371:                             "Could not retrieve JobMasterGateway because the JobMaster failed.",
372:                             throwable));
373:         } else {
374:             if (!jobManagerRunnerResult.isSuccess()) {
375:                 jobMasterGatewayFuture.completeExceptionally(
376:                         new FlinkException(
377:                                 "Could not retrieve JobMasterGateway because the JobMaster initialization failed.",
378:                                 jobManagerRunnerResult.getInitializationFailure()));
379:             }
380: 
381:             resultFuture.complete(jobManagerRunnerResult);
382:         }
383:     }
384: 
385:     @Override
386:     public void revokeLeadership() {
387:         runIfStateRunning(
388:                 this::stopJobMasterServiceProcessAsync,
389:                 "revoke leadership from JobMasterServiceProcess");
390:     }
391: 
392:     @GuardedBy("lock")
393:     private void stopJobMasterServiceProcessAsync() {
394:         sequentialOperation =
395:                 sequentialOperation.thenCompose(
396:                         ignored ->
397:                                 callIfRunning(
398:                                                 this::stopJobMasterServiceProcess,
399:                                                 "stop leading JobMasterServiceProcess")
400:                                         .orElse(FutureUtils.completedVoidFuture()));
401: 
402:         handleAsyncOperationError(sequentialOperation, "Could not suspend the job manager.");
403:     }
404: 
405:     @GuardedBy("lock")
406:     private CompletableFuture<Void> stopJobMasterServiceProcess() {
407:         LOG.info(
408:                 "{} for job {} was revoked leadership with leader id {}. Stopping current {}.",
409:                 getClass().getSimpleName(),
410:                 getJobID(),
411:                 jobMasterServiceProcess.getLeaderSessionId(),
412:                 JobMasterServiceProcess.class.getSimpleName());
413: 
414:         jobMasterGatewayFuture.completeExceptionally(
415:                 new FlinkException(
416:                         "Cannot obtain JobMasterGateway because the JobMaster lost leadership."));
417:         jobMasterGatewayFuture = new CompletableFuture<>();
418: 
419:         hasCurrentLeaderBeenCancelled = false;
420: 
421:         return jobMasterServiceProcess.closeAsync();
422:     }
423: 
424:     @Override
425:     public void handleError(Exception exception) {
426:         fatalErrorHandler.onFatalError(exception);
427:     }
428: 
429:     private void handleAsyncOperationError(CompletableFuture<Void> operation, String message) {
430:         operation.whenComplete(
431:                 (unused, throwable) -> {
432:                     if (throwable != null) {
433:                         runIfStateRunning(
434:                                 () ->
435:                                         handleJobMasterServiceLeadershipRunnerError(
436:                                                 new FlinkException(message, throwable)),
437:                                 "handle JobMasterServiceLeadershipRunner error");
438:                     }
439:                 });
440:     }
441: 
442:     private void handleJobMasterServiceLeadershipRunnerError(Throwable cause) {
443:         if (ExceptionUtils.isJvmFatalError(cause)) {
444:             fatalErrorHandler.onFatalError(cause);
445:         } else {
446:             resultFuture.completeExceptionally(cause);
447:         }
448:     }
449: 
450:     private void runIfStateRunning(Runnable action, String actionDescription) {
451:         synchronized (lock) {
452:             if (isRunning()) {
453:                 action.run();
454:             } else {
455:                 LOG.debug(
456:                         "Ignore '{}' because the leadership runner is no longer running.",
457:                         actionDescription);
458:             }
459:         }
460:     }
461: 
462:     private <T> Optional<T> callIfRunning(
463:             Supplier<? extends T> supplier, String supplierDescription) {
464:         synchronized (lock) {
465:             if (isRunning()) {
466:                 return Optional.of(supplier.get());
467:             } else {
468:                 LOG.debug(
469:                         "Ignore '{}' because the leadership runner is no longer running.",
470:                         supplierDescription);
471:                 return Optional.empty();
472:             }
473:         }
474:     }
475: 
476:     @GuardedBy("lock")
477:     private boolean isRunning() {
478:         return state == State.RUNNING;
479:     }
480: 
481:     private void runIfValidLeader(
482:             UUID expectedLeaderId, Runnable action, Runnable noLeaderFallback) {
483:         synchronized (lock) {
484:             if (isValidLeader(expectedLeaderId)) {
485:                 action.run();
486:             } else {
487:                 noLeaderFallback.run();
488:             }
489:         }
490:     }
491: 
492:     private void runIfValidLeader(
493:             UUID expectedLeaderId, Runnable action, String noLeaderFallbackCommandDescription) {
494:         runIfValidLeader(
495:                 expectedLeaderId,
496:                 action,
497:                 () ->
498:                         printLogIfNotValidLeader(
499:                                 noLeaderFallbackCommandDescription, expectedLeaderId));
500:     }
501: 
502:     @GuardedBy("lock")
503:     private boolean isValidLeader(UUID expectedLeaderId) {
504:         return isRunning()
505:                 && leaderElection != null
506:                 && leaderElection.hasLeadership(expectedLeaderId);
507:     }
508: 
509:     private <T> void forwardIfValidLeader(
510:             UUID expectedLeaderId,
511:             CompletableFuture<? extends T> source,
512:             CompletableFuture<T> target,
513:             String forwardDescription) {
514:         source.whenComplete(
515:                 (t, throwable) ->
516:                         runIfValidLeader(
517:                                 expectedLeaderId,
518:                                 () -> {
519:                                     if (throwable != null) {
520:                                         target.completeExceptionally(throwable);
521:                                     } else {
522:                                         target.complete(t);
523:                                     }
524:                                 },
525:                                 forwardDescription));
526:     }
527: 
528:     enum State {
529:         RUNNING,
530:         STOPPED,
531:         JOB_COMPLETED,
532:     }
533: }
