587:         JobVertex reduceSinkVertex = jobGraph.getVerticesSortedTopologicallyFromSources().get(1);
588: 
589:         assertThat(sourceMapFilterVertex.getMinResources())
590:                 .isEqualTo(resource3.merge(resource2).merge(resource1));
