2054:     void testSupportConcurrentExecutionAttempts() {
2055:         final StreamExecutionEnvironment env =
2056:                 StreamExecutionEnvironment.getExecutionEnvironment(new Configuration());
2057:         env.setRuntimeMode(RuntimeExecutionMode.BATCH);
2058: 
2059:         final DataStream<Integer> source = env.fromData(1, 2, 3).name("source");
2060:         // source -> (map1 -> map2) -> sink
2061:         source.rebalance()
2062:                 .map(v -> v)
2063:                 .name("map1")
2064:                 .map(v -> v)
2065:                 .name("map2")
2066:                 .rebalance()
2067:                 .sinkTo(new PrintSink<>())
2068:                 .name("sink");
2069: 
2070:         final StreamGraph streamGraph = env.getStreamGraph();
2071:         final List<StreamNode> streamNodes =
2072:                 streamGraph.getStreamNodes().stream()
2073:                         .sorted(Comparator.comparingInt(StreamNode::getId))
2074:                         .collect(Collectors.toList());
2075: 
2076:         final StreamNode sourceNode = streamNodes.get(0);
2077:         final StreamNode map1Node = streamNodes.get(1);
2078:         final StreamNode map2Node = streamNodes.get(2);
2079:         final StreamNode sinkNode = streamNodes.get(3);
2080:         streamGraph.setSupportsConcurrentExecutionAttempts(sourceNode.getId(), true);
2081:         // map1 and map2 are chained
2082:         // map1 supports concurrent execution attempt however map2 does not
2083:         streamGraph.setSupportsConcurrentExecutionAttempts(map1Node.getId(), true);
2084:         streamGraph.setSupportsConcurrentExecutionAttempts(map2Node.getId(), false);
2085:         streamGraph.setSupportsConcurrentExecutionAttempts(sinkNode.getId(), false);
2086: 
2087:         final JobGraph jobGraph = StreamingJobGraphGenerator.createJobGraph(streamGraph);
2088:         assertThat(jobGraph.getNumberOfVertices()).isEqualTo(3);
2089:         for (JobVertex jobVertex : jobGraph.getVertices()) {
2090:             if (jobVertex.getName().contains("source")) {
2091:                 assertThat(jobVertex.isSupportsConcurrentExecutionAttempts()).isTrue();
2092:             } else if (jobVertex.getName().contains("map")) {
2093:                 // chained job vertex does not support concurrent execution attempt if any operator
2094:                 // in chain does not support it
2095:                 assertThat(jobVertex.isSupportsConcurrentExecutionAttempts()).isFalse();
2096:             } else if (jobVertex.getName().contains("sink")) {
2097:                 assertThat(jobVertex.isSupportsConcurrentExecutionAttempts()).isFalse();
2098:             } else {
2099:                 Assertions.fail("Unexpected job vertex " + jobVertex.getName());
2100:             }
2101:         }
