519:         ResourceSpec resource4 = ResourceSpec.newBuilder(0.4, 400).build();
520:         ResourceSpec resource5 = ResourceSpec.newBuilder(0.5, 500).build();
521: 
522:         Method opMethod = getSetResourcesMethodAndSetAccessible(SingleOutputStreamOperator.class);
523:         Method sinkMethod = getSetResourcesMethodAndSetAccessible(DataStreamSink.class);
524: 
525:         StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
526: 
527:         DataStream<Tuple2<Integer, Integer>> source =
528:                 env.addSource(
529:                         new ParallelSourceFunction<Tuple2<Integer, Integer>>() {
530:                             @Override
531:                             public void run(SourceContext<Tuple2<Integer, Integer>> ctx)
532:                                     throws Exception {}
533: 
534:                             @Override
535:                             public void cancel() {}
536:                         });
537:         opMethod.invoke(source, resource1);
538: 
539:         DataStream<Tuple2<Integer, Integer>> map =
540:                 source.map(
541:                         new MapFunction<Tuple2<Integer, Integer>, Tuple2<Integer, Integer>>() {
542:                             @Override
543:                             public Tuple2<Integer, Integer> map(Tuple2<Integer, Integer> value)
544:                                     throws Exception {
545:                                 return value;
546:                             }
547:                         });
548:         opMethod.invoke(map, resource2);
549: 
550:         // CHAIN(Source -> Map -> Filter)
551:         DataStream<Tuple2<Integer, Integer>> filter =
552:                 map.filter(
553:                         new FilterFunction<Tuple2<Integer, Integer>>() {
554:                             @Override
555:                             public boolean filter(Tuple2<Integer, Integer> value) throws Exception {
556:                                 return false;
557:                             }
558:                         });
559:         opMethod.invoke(filter, resource3);
560: 
561:         DataStream<Tuple2<Integer, Integer>> reduce =
562:                 filter.keyBy(x -> x.f0)
563:                         .reduce(
564:                                 new ReduceFunction<Tuple2<Integer, Integer>>() {
565:                                     @Override
566:                                     public Tuple2<Integer, Integer> reduce(
567:                                             Tuple2<Integer, Integer> value1,
568:                                             Tuple2<Integer, Integer> value2)
569:                                             throws Exception {
570:                                         return new Tuple2<>(value1.f0, value1.f1 + value2.f1);
571:                                     }
572:                                 });
573:         opMethod.invoke(reduce, resource4);
