1145:     @Test
1146:     void testDeterministicUnionOrder() {
1147:         StreamExecutionEnvironment env = StreamExecutionEnvironment.createLocalEnvironment(1);
1148: 
1149:         JobGraph jobGraph = getUnionJobGraph(env);
1150:         JobVertex jobSink = Iterables.getLast(jobGraph.getVerticesSortedTopologicallyFromSources());
1151:         List<String> expectedSourceOrder =
1152:                 jobSink.getInputs().stream()
1153:                         .map(edge -> edge.getSource().getProducer().getName())
1154:                         .collect(Collectors.toList());
1155: 
1156:         for (int i = 0; i < 100; i++) {
1157:             JobGraph jobGraph2 = getUnionJobGraph(env);
1158:             JobVertex jobSink2 =
1159:                     Iterables.getLast(jobGraph2.getVerticesSortedTopologicallyFromSources());
1160:             assertThat(jobSink)
1161:                     .withFailMessage("Different runs should yield different vertexes")
1162:                     .isNotEqualTo(jobSink2);
1163:             List<String> actualSourceOrder =
1164:                     jobSink2.getInputs().stream()
1165:                             .map(edge -> edge.getSource().getProducer().getName())
1166:                             .collect(Collectors.toList());
1167:             assertThat(actualSourceOrder)
1168:                     .withFailMessage("Union inputs reordered")
1169:                     .isEqualTo(expectedSourceOrder);
1170:         }
1171:     }
