1173:     private JobGraph getUnionJobGraph(StreamExecutionEnvironment env) {
1174: 
1175:         createSource(env, 1)
1176:                 .union(createSource(env, 2))
1177:                 .union(createSource(env, 3))
1178:                 .union(createSource(env, 4))
1179:                 .sinkTo(new DiscardingSink<>());
1180: 
1181:         return StreamingJobGraphGenerator.createJobGraph(env.getStreamGraph());
1182:     }
