1285:     private JobGraph createJobGraphForManagedMemoryFractionTest(
1286:             final List<ResourceSpec> resourceSpecs,
1287:             final List<Map<ManagedMemoryUseCase, Integer>> operatorScopeUseCaseWeights,
1288:             final List<Set<ManagedMemoryUseCase>> slotScopeUseCases)
1289:             throws Exception {
1290: 
1291:         final Method opMethod =
1292:                 getSetResourcesMethodAndSetAccessible(SingleOutputStreamOperator.class);
1293: 
1294:         final StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
1295: 
1296:         final DataStream<Integer> source =
1297:                 env.addSource(
1298:                         new ParallelSourceFunction<Integer>() {
1299:                             @Override
1300:                             public void run(SourceContext<Integer> ctx) {}
1301: 
1302:                             @Override
1303:                             public void cancel() {}
1304:                         });
1305:         opMethod.invoke(source, resourceSpecs.get(0));
1306: 
1307:         // CHAIN(source -> map1) in default slot sharing group
1308:         final DataStream<Integer> map1 = source.map((MapFunction<Integer, Integer>) value -> value);
1309:         opMethod.invoke(map1, resourceSpecs.get(1));
1310: 
1311:         // CHAIN(map2) in default slot sharing group
1312:         final DataStream<Integer> map2 =
1313:                 map1.rebalance().map((MapFunction<Integer, Integer>) value -> value);
1314:         opMethod.invoke(map2, resourceSpecs.get(2));
1315: 
1316:         // CHAIN(map3) in test slot sharing group
1317:         final DataStream<Integer> map3 =
1318:                 map2.rebalance().map(value -> value).slotSharingGroup("test");
1319:         opMethod.invoke(map3, resourceSpecs.get(3));
1320: 
1321:         declareManagedMemoryUseCaseForTranformation(
1322:                 source.getTransformation(),
1323:                 operatorScopeUseCaseWeights.get(0),
1324:                 slotScopeUseCases.get(0));
1325:         declareManagedMemoryUseCaseForTranformation(
1326:                 map1.getTransformation(),
1327:                 operatorScopeUseCaseWeights.get(1),
1328:                 slotScopeUseCases.get(1));
1329:         declareManagedMemoryUseCaseForTranformation(
1330:                 map2.getTransformation(),
1331:                 operatorScopeUseCaseWeights.get(2),
1332:                 slotScopeUseCases.get(2));
1333:         declareManagedMemoryUseCaseForTranformation(
1334:                 map3.getTransformation(),
1335:                 operatorScopeUseCaseWeights.get(3),
1336:                 slotScopeUseCases.get(3));
1337: 
1338:         return StreamingJobGraphGenerator.createJobGraph(env.getStreamGraph());
1339:     }
1340: 
1341:     private void declareManagedMemoryUseCaseForTranformation(
1342:             Transformation<?> transformation,
1343:             Map<ManagedMemoryUseCase, Integer> operatorScopeUseCaseWeights,
1344:             Set<ManagedMemoryUseCase> slotScopeUseCases) {
1345:         for (Map.Entry<ManagedMemoryUseCase, Integer> entry :
1346:                 operatorScopeUseCaseWeights.entrySet()) {
1347:             transformation.declareManagedMemoryUseCaseAtOperatorScope(
1348:                     entry.getKey(), entry.getValue());
1349:         }
1350:         for (ManagedMemoryUseCase useCase : slotScopeUseCases) {
1351:             transformation.declareManagedMemoryUseCaseAtSlotScope(useCase);
1352:         }
1353:     }
