1611:     public JobGraph createGraphWithMultipleInputs(
1612:             boolean chain, String sinkName, String... inputNames) {
1613:         StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
1614:         MultipleInputTransformation<Long> transform =
1615:                 new MultipleInputTransformation<>(
1616:                         "mit", new UnusedOperatorFactory(), Types.LONG, env.getParallelism());
1617:         Arrays.stream(inputNames)
1618:                 .map(
1619:                         name ->
1620:                                 env.fromSource(
1621:                                                 new NumberSequenceSource(1, 2),
1622:                                                 WatermarkStrategy.noWatermarks(),
1623:                                                 name)
1624:                                         .getTransformation())
1625:                 .forEach(transform::addInput);
1626:         transform.setChainingStrategy(
1627:                 chain ? ChainingStrategy.HEAD_WITH_SOURCES : ChainingStrategy.NEVER);
1628: 
1629:         DataStream<Long> dataStream = new DataStream<>(env, transform);
1630:         // do not chain with sink operator.
1631:         dataStream.rebalance().sinkTo(new DiscardingSink<>()).name(sinkName);
1632: 
1633:         env.addOperator(transform);
1634: 
1635:         return StreamingJobGraphGenerator.createJobGraph(env.getStreamGraph());
1636:     }
