2529:         } else {
2530:             MultipleInputTransformation<Long> transform =
2531:                     new MultipleInputTransformation<>(
2532:                             "mit", new UnusedOperatorFactory(), Types.LONG, env.getParallelism());
2533:             transform.setDescription("operator chained with source");
2534:             transform.setChainingStrategy(ChainingStrategy.HEAD_WITH_SOURCES);
2535:             Arrays.stream(inputNames)
2536:                     .map(
2537:                             name ->
2538:                                     env.fromSource(
2539:                                                     new NumberSequenceSource(1, 2),
2540:                                                     WatermarkStrategy.noWatermarks(),
2541:                                                     name)
2542:                                             .setDescription(name)
2543:                                             .getTransformation())
2544:                     .forEach(transform::addInput);
2545: 
2546:             source = new DataStream<>(env, transform);
2547:         }
2548:         DataStream<Long> map1 = source.map(x -> x + 1).setDescription("x + 1");
2549:         DataStream<Long> map2 = source.map(x -> x + 2).setDescription("x + 2");
2550:         map1.print().setDescription("first print of map1");
2551:         map1.print().setDescription("second print of map1");
2552:         map2.print().setDescription("first print of map2");
2553:         map2.print().setDescription("second print of map2");
2554:         return StreamingJobGraphGenerator.createJobGraph(env.getStreamGraph());
