845:     /**
846:      * This method is used to reset or set job vertices' parallelism for dynamic graph:
847:      *
848:      * <p>1. Reset parallelism for job vertices whose parallelism is not configured.
849:      *
850:      * <p>2. Set parallelism and maxParallelism for job vertices in forward group, to ensure the
851:      * parallelism and maxParallelism of vertices in the same forward group to be the same; set the
852:      * parallelism at early stage if possible, to avoid invalid partition reuse.
853:      */
854:     private void setVertexParallelismsForDynamicGraphIfNecessary() {
855:         final Map<Integer, JobVertex> jobVertices = jobVertexBuildContext.getJobVerticesInOrder();
856:         // Note that the jobVertices are reverse topological order
857:         final List<JobVertex> topologicalOrderVertices =
858:                 IterableUtils.toStream(jobVertices.values()).collect(Collectors.toList());
859:         Collections.reverse(topologicalOrderVertices);
860: 
861:         // reset parallelism for job vertices whose parallelism is not configured
862:         jobVertices.forEach(
863:                 (startNodeId, jobVertex) -> {
864:                     final OperatorChainInfo chainInfo =
865:                             jobVertexBuildContext.getChainInfo(startNodeId);
866:                     if (!jobVertex.isParallelismConfigured()
867:                             && streamGraph.isAutoParallelismEnabled()) {
868:                         jobVertex.setParallelism(ExecutionConfig.PARALLELISM_DEFAULT);
869:                         chainInfo
870:                                 .getAllChainedNodes()
871:                                 .forEach(
872:                                         n ->
873:                                                 n.setParallelism(
874:                                                         ExecutionConfig.PARALLELISM_DEFAULT,
875:                                                         false));
876:                     }
877:                 });
878: 
879:         final Map<JobVertex, Set<JobVertex>> forwardProducersByJobVertex = new HashMap<>();
880:         jobVertices.forEach(
881:                 (startNodeId, jobVertex) -> {
882:                     Set<JobVertex> forwardConsumers =
883:                             jobVertexBuildContext.getChainInfo(startNodeId).getTransitiveOutEdges()
884:                                     .stream()
885:                                     .filter(
886:                                             edge ->
887:                                                     edge.getPartitioner()
888:                                                             instanceof ForwardPartitioner)
889:                                     .map(StreamEdge::getTargetId)
890:                                     .map(jobVertices::get)
891:                                     .collect(Collectors.toSet());
892: 
893:                     for (JobVertex forwardConsumer : forwardConsumers) {
894:                         forwardProducersByJobVertex.compute(
895:                                 forwardConsumer,
896:                                 (ignored, producers) -> {
897:                                     if (producers == null) {
898:                                         producers = new HashSet<>();
899:                                     }
900:                                     producers.add(jobVertex);
901:                                     return producers;
902:                                 });
903:                     }
904:                 });
905: 
906:         // compute forward groups
907:         final Map<JobVertexID, ForwardGroup> forwardGroupsByJobVertexId =
908:                 ForwardGroupComputeUtil.computeForwardGroups(
909:                         topologicalOrderVertices,
910:                         jobVertex ->
911:                                 forwardProducersByJobVertex.getOrDefault(
912:                                         jobVertex, Collections.emptySet()));
913: 
914:         jobVertices.forEach(
915:                 (startNodeId, jobVertex) -> {
916:                     ForwardGroup forwardGroup = forwardGroupsByJobVertexId.get(jobVertex.getID());
917:                     // set parallelism for vertices in forward group
918:                     if (forwardGroup != null && forwardGroup.isParallelismDecided()) {
919:                         jobVertex.setParallelism(forwardGroup.getParallelism());
920:                         jobVertex.setParallelismConfigured(true);
921:                         jobVertexBuildContext
922:                                 .getChainInfo(startNodeId)
923:                                 .getAllChainedNodes()
924:                                 .forEach(
925:                                         streamNode ->
926:                                                 streamNode.setParallelism(
927:                                                         forwardGroup.getParallelism(), true));
928:                     }
929: 
930:                     // set max parallelism for vertices in forward group
931:                     if (forwardGroup != null && forwardGroup.isMaxParallelismDecided()) {
932:                         jobVertex.setMaxParallelism(forwardGroup.getMaxParallelism());
933:                         jobVertexBuildContext
934:                                 .getChainInfo(startNodeId)
935:                                 .getAllChainedNodes()
936:                                 .forEach(
937:                                         streamNode ->
938:                                                 streamNode.setMaxParallelism(
939:                                                         forwardGroup.getMaxParallelism()));
940:                     }
941:                 });
942:     }
