944:     private static void checkAndReplaceReusableHybridPartitionType(
945:             NonChainedOutput reusableOutput) {
946:         if (reusableOutput.getPartitionType() == ResultPartitionType.HYBRID_SELECTIVE) {
947:             // for can be reused hybrid output, it can be optimized to always use full
948:             // spilling strategy to significantly reduce shuffle data writing cost.
949:             reusableOutput.setPartitionType(ResultPartitionType.HYBRID_FULL);
950:             LOG.info(
951:                     "{} result partition has been replaced by {} result partition to support partition reuse,"
952:                             + " which will reduce shuffle data writing cost.",
953:                     reusableOutput.getPartitionType().name(),
954:                     ResultPartitionType.HYBRID_FULL.name());
955:         }
956:     }
