958:     public static String createChainedName(
959:             Integer vertexID,
960:             List<StreamEdge> chainedOutputs,
961:             Optional<OperatorChainInfo> operatorChainInfo,
962:             Map<Integer, String> chainedNames,
963:             JobVertexBuildContext jobVertexBuildContext) {
964:         StreamGraph streamGraph = jobVertexBuildContext.getStreamGraph();
965:         List<ChainedSourceInfo> chainedSourceInfos =
966:                 operatorChainInfo
967:                         .map(
968:                                 chainInfo ->
969:                                         getChainedSourcesByVertexId(
970:                                                 vertexID, chainInfo, streamGraph))
971:                         .orElse(Collections.emptyList());
972:         final String operatorName =
973:                 nameWithChainedSourcesInfo(
974:                         streamGraph.getStreamNode(vertexID).getOperatorName(), chainedSourceInfos);
975:         if (chainedOutputs.size() > 1) {
976:             List<String> outputChainedNames = new ArrayList<>();
977:             for (StreamEdge chainable : chainedOutputs) {
978:                 outputChainedNames.add(chainedNames.get(chainable.getTargetId()));
979:             }
980:             return operatorName + " -> (" + StringUtils.join(outputChainedNames, ", ") + ")";
981:         } else if (chainedOutputs.size() == 1) {
982:             return operatorName + " -> " + chainedNames.get(chainedOutputs.get(0).getTargetId());
983:         } else {
984:             return operatorName;
985:         }
986:     }
