1468:     public static void tryConvertPartitionerForDynamicGraph(
1469:             List<StreamEdge> chainableOutputs,
1470:             List<StreamEdge> nonChainableOutputs,
1471:             JobVertexBuildContext jobVertexBuildContext) {
1472:         StreamGraph streamGraph = jobVertexBuildContext.getStreamGraph();
1473:         for (StreamEdge edge : chainableOutputs) {
1474:             StreamPartitioner<?> partitioner = edge.getPartitioner();
1475:             if (partitioner instanceof ForwardForConsecutiveHashPartitioner
1476:                     || partitioner instanceof ForwardForUnspecifiedPartitioner) {
1477:                 checkState(
1478:                         streamGraph.isDynamic(),
1479:                         String.format(
1480:                                 "%s should only be used in dynamic graph.",
1481:                                 partitioner.getClass().getSimpleName()));
1482:                 edge.setPartitioner(new ForwardPartitioner<>());
1483:             }
1484:         }
1485:         for (StreamEdge edge : nonChainableOutputs) {
1486:             StreamPartitioner<?> partitioner = edge.getPartitioner();
1487:             if (partitioner instanceof ForwardForConsecutiveHashPartitioner) {
1488:                 checkState(
1489:                         streamGraph.isDynamic(),
1490:                         "ForwardForConsecutiveHashPartitioner should only be used in dynamic graph.");
1491:                 edge.setPartitioner(
1492:                         ((ForwardForConsecutiveHashPartitioner<?>) partitioner)
1493:                                 .getHashPartitioner());
1494:             } else if (partitioner instanceof ForwardForUnspecifiedPartitioner) {
1495:                 checkState(
1496:                         streamGraph.isDynamic(),
1497:                         "ForwardForUnspecifiedPartitioner should only be used in dynamic graph.");
1498:                 edge.setPartitioner(new RescalePartitioner<>());
1499:             }
1500:         }
1501:     }
