1616:     public static ResultPartitionType determineUndefinedResultPartitionType(
1617:             StreamEdge edge, JobVertexBuildContext jobVertexBuildContext) {
1618:         StreamGraph streamGraph = jobVertexBuildContext.getStreamGraph();
1619:         Attribute sourceNodeAttribute =
1620:                 streamGraph.getStreamNode(edge.getSourceId()).getAttribute();
1621:         if (sourceNodeAttribute.isNoOutputUntilEndOfInput()) {
1622:             edge.setBufferTimeout(ExecutionOptions.DISABLED_NETWORK_BUFFER_TIMEOUT);
1623:             return ResultPartitionType.BLOCKING;
1624:         }
1625: 
1626:         StreamPartitioner<?> partitioner = edge.getPartitioner();
1627:         switch (streamGraph.getGlobalStreamExchangeMode()) {
1628:             case ALL_EDGES_BLOCKING:
1629:                 return ResultPartitionType.BLOCKING;
1630:             case FORWARD_EDGES_PIPELINED:
1631:                 if (partitioner instanceof ForwardPartitioner) {
1632:                     return ResultPartitionType.PIPELINED_BOUNDED;
1633:                 } else {
1634:                     return ResultPartitionType.BLOCKING;
1635:                 }
1636:             case POINTWISE_EDGES_PIPELINED:
1637:                 if (partitioner.isPointwise()) {
1638:                     return ResultPartitionType.PIPELINED_BOUNDED;
1639:                 } else {
1640:                     return ResultPartitionType.BLOCKING;
1641:                 }
1642:             case ALL_EDGES_PIPELINED:
1643:                 return ResultPartitionType.PIPELINED_BOUNDED;
1644:             case ALL_EDGES_PIPELINED_APPROXIMATE:
1645:                 return ResultPartitionType.PIPELINED_APPROXIMATE;
1646:             case ALL_EDGES_HYBRID_FULL:
1647:                 return ResultPartitionType.HYBRID_FULL;
1648:             case ALL_EDGES_HYBRID_SELECTIVE:
1649:                 return ResultPartitionType.HYBRID_SELECTIVE;
1650:             default:
1651:                 throw new RuntimeException(
1652:                         "Unrecognized global data exchange mode "
1653:                                 + streamGraph.getGlobalStreamExchangeMode());
1654:         }
1655:     }
