1789:         final Map<Integer, JobVertex> jobVertices = jobVertexBuildContext.getJobVerticesInOrder();
1790:         StreamGraph streamGraph = jobVertexBuildContext.getStreamGraph();
1791: 
1792:         for (Map.Entry<Integer, JobVertex> entry : jobVertices.entrySet()) {
1793:             final JobVertex jobVertex = entry.getValue();
1794:             final Set<Integer> vertexOperators = new HashSet<>();
1795:             vertexOperators.add(entry.getKey());
