128: import java.util.stream.Collectors;
129: 
130: import static org.apache.flink.runtime.jobgraph.tasks.CheckpointCoordinatorConfiguration.MINIMAL_CHECKPOINT_TIME;
131: import static org.apache.flink.util.Preconditions.checkArgument;
132: import static org.apache.flink.util.Preconditions.checkNotNull;
133: import static org.apache.flink.util.Preconditions.checkState;
