135: /** The StreamingJobGraphGenerator converts a {@link StreamGraph} into a {@link JobGraph}. */
136: @Internal
137: public class StreamingJobGraphGenerator {
138: 
139:     private static final Logger LOG = LoggerFactory.getLogger(StreamingJobGraphGenerator.class);
140: 
141:     // ------------------------------------------------------------------------
142: 
143:     @VisibleForTesting
144:     public static JobGraph createJobGraph(StreamGraph streamGraph) {
145:         return new StreamingJobGraphGenerator(
146:                         Thread.currentThread().getContextClassLoader(),
147:                         streamGraph,
148:                         null,
149:                         Runnable::run)
150:                 .createJobGraph();
151:     }
152: 
153:     public static JobGraph createJobGraph(
154:             ClassLoader userClassLoader, StreamGraph streamGraph, @Nullable JobID jobID) {
155:         // TODO Currently, we construct a new thread pool for the compilation of each job. In the
156:         // future, we may refactor the job submission framework and make it reusable across jobs.
157:         final ExecutorService serializationExecutor =
158:                 Executors.newFixedThreadPool(
159:                         Math.max(
160:                                 1,
161:                                 Math.min(
162:                                         Hardware.getNumberCPUCores(),
163:                                         streamGraph.getExecutionConfig().getParallelism())),
164:                         new ExecutorThreadFactory("flink-operator-serialization-io"));
165:         try {
166:             return new StreamingJobGraphGenerator(
167:                             userClassLoader, streamGraph, jobID, serializationExecutor)
168:                     .createJobGraph();
169:         } finally {
170:             serializationExecutor.shutdown();
171:         }
172:     }
173: 
174:     // ------------------------------------------------------------------------
175: 
176:     private final ClassLoader userClassloader;
177:     private final StreamGraph streamGraph;
178: 
179:     private final JobGraph executionPlan;
180:     private final Collection<Integer> builtVertices;
181: 
182:     private final StreamGraphHasher defaultStreamGraphHasher;
183:     private final List<StreamGraphHasher> legacyStreamGraphHashers;
184: 
185:     private final Executor serializationExecutor;
186: 
187:     // We save all the context needed to create the JobVertex in this structure.
188:     private final JobVertexBuildContext jobVertexBuildContext;
189: 
190:     private StreamingJobGraphGenerator(
191:             ClassLoader userClassloader,
192:             StreamGraph streamGraph,
193:             @Nullable JobID jobID,
194:             Executor serializationExecutor) {
195:         this.userClassloader = userClassloader;
196:         this.streamGraph = streamGraph;
197:         this.defaultStreamGraphHasher = new StreamGraphHasherV2();
198:         this.legacyStreamGraphHashers = Arrays.asList(new StreamGraphUserHashHasher());
199: 
200:         this.builtVertices = new HashSet<>();
201:         this.serializationExecutor = Preconditions.checkNotNull(serializationExecutor);
202:         executionPlan = new JobGraph(jobID, streamGraph.getJobName());
203: 
204:         // Generate deterministic hashes for the nodes in order to identify them across
205:         // submission iff they didn't change.
206:         final Map<Integer, byte[]> hashes =
207:                 defaultStreamGraphHasher.traverseStreamGraphAndGenerateHashes(streamGraph);
208: 
209:         // Generate legacy version hashes for backwards compatibility
210:         final List<Map<Integer, byte[]>> legacyHashes =
211:                 new ArrayList<>(legacyStreamGraphHashers.size());
212:         for (StreamGraphHasher hasher : legacyStreamGraphHashers) {
213:             legacyHashes.add(hasher.traverseStreamGraphAndGenerateHashes(streamGraph));
214:         }
215: 
216:         this.jobVertexBuildContext =
217:                 new JobVertexBuildContext(
218:                         streamGraph, new AtomicBoolean(false), hashes, legacyHashes);
219:     }
220: 
221:     private JobGraph createJobGraph() {
222:         preValidate(streamGraph, userClassloader);
223:         executionPlan.setJobType(streamGraph.getJobType());
224:         executionPlan.setDynamic(streamGraph.isDynamic());
225: 
226:         executionPlan.enableApproximateLocalRecovery(
227:                 streamGraph.getCheckpointConfig().isApproximateLocalRecoveryEnabled());
228: 
229:         setChaining();
230: 
231:         if (executionPlan.isDynamic()) {
232:             setVertexParallelismsForDynamicGraphIfNecessary();
233:         }
234: 
235:         // Note that we set all the non-chainable outputs configuration here because the
236:         // "setVertexParallelismsForDynamicGraphIfNecessary" may affect the parallelism of job
237:         // vertices and partition-reuse
238:         final Map<Integer, Map<StreamEdge, NonChainedOutput>> opIntermediateOutputs =
239:                 new HashMap<>();
240:         setAllOperatorNonChainedOutputsConfigs(opIntermediateOutputs, jobVertexBuildContext);
241:         setAllVertexNonChainedOutputsConfigs(opIntermediateOutputs);
242: 
243:         setPhysicalEdges(jobVertexBuildContext);
244: 
245:         markSupportingConcurrentExecutionAttempts(jobVertexBuildContext);
246: 
247:         validateHybridShuffleExecuteInBatchMode(jobVertexBuildContext);
248: 
249:         setSlotSharingAndCoLocation(executionPlan, jobVertexBuildContext);
250: 
251:         setManagedMemoryFraction(jobVertexBuildContext);
252: 
253:         configureCheckpointing(streamGraph, executionPlan);
254: 
255:         executionPlan.setSavepointRestoreSettings(streamGraph.getSavepointRestoreSettings());
256: 
257:         final Map<String, DistributedCache.DistributedCacheEntry> distributedCacheEntries =
258:                 JobGraphUtils.prepareUserArtifactEntries(
259:                         streamGraph.getUserArtifacts().stream()
260:                                 .collect(Collectors.toMap(e -> e.f0, e -> e.f1)),
261:                         executionPlan.getJobID());
262: 
263:         for (Map.Entry<String, DistributedCache.DistributedCacheEntry> entry :
264:                 distributedCacheEntries.entrySet()) {
265:             executionPlan.addUserArtifact(entry.getKey(), entry.getValue());
266:         }
267: 
268:         // set the ExecutionConfig last when it has been finalized
269:         try {
270:             executionPlan.setExecutionConfig(streamGraph.getExecutionConfig());
271:         } catch (IOException e) {
272:             throw new IllegalConfigurationException(
273:                     "Could not serialize the ExecutionConfig."
274:                             + "This indicates that non-serializable types (like custom serializers) were registered");
275:         }
276:         executionPlan.setJobConfiguration(streamGraph.getJobConfiguration());
277: 
278:         addVertexIndexPrefixInVertexName(jobVertexBuildContext, new AtomicInteger(0), executionPlan);
279: 
280:         setVertexDescription(jobVertexBuildContext);
281: 
282:         // Wait for the serialization of operator coordinators and stream config.
283:         serializeOperatorCoordinatorsAndStreamConfig(
284:                 executionPlan, serializationExecutor, jobVertexBuildContext);
285: 
286:         if (!streamGraph.getJobStatusHooks().isEmpty()) {
287:             executionPlan.setJobStatusHooks(streamGraph.getJobStatusHooks());
288:         }
289: 
290:         return executionPlan;
291:     }
292: 
293:     public static void serializeOperatorCoordinatorsAndStreamConfig(
294:             JobGraph jobGraph,
295:             Executor serializationExecutor,
296:             JobVertexBuildContext jobVertexBuildContext) {
297:         try {
298:             FutureUtils.combineAll(
299:                             jobVertexBuildContext.getOperatorInfos().values().stream()
300:                                     .map(
301:                                             operatorInfo ->
302:                                                     operatorInfo
303:                                                             .getVertexConfig()
304:                                                             .triggerSerializationAndReturnFuture(
305:                                                                     serializationExecutor))
306:                                     .collect(Collectors.toList()))
307:                     .get();
308: 
309:             waitForSerializationFuturesAndUpdateJobVertices(jobGraph, jobVertexBuildContext);
310:         } catch (Exception e) {
311:             throw new FlinkRuntimeException("Error in serialization.", e);
312:         }
313:     }
314: 
315:     /**
316:      * Creates an instance of {@link OperatorID} based on the provided operator unique identifier
317:      * (UID).
318:      *
319:      * @param operatorUid the unique identifier of the operator, used to generate the hash
320:      * @return a new {@link OperatorID} instance generated from the specified operator UID
321:      */
322:     public static OperatorID generateOperatorID(String operatorUid) {
323:         return new OperatorID(StreamGraphHasherV2.generateUserSpecifiedHash(operatorUid));
324:     }
325: 
326:     private static void waitForSerializationFuturesAndUpdateJobVertices(
327:             JobGraph jobGraph, JobVertexBuildContext jobVertexBuildContext)
328:             throws ExecutionException, InterruptedException {
329:         for (Map.Entry<
330:                         JobVertexID,
331:                         List<CompletableFuture<SerializedValue<OperatorCoordinator.Provider>>>>
332:                 futuresPerJobVertex :
333:                         jobVertexBuildContext
334:                                 .getCoordinatorSerializationFuturesPerJobVertex()
335:                                 .entrySet()) {
336:             final JobVertexID jobVertexId = futuresPerJobVertex.getKey();
337:             final JobVertex jobVertex = jobGraph.findVertexByID(jobVertexId);
338: 
339:             Preconditions.checkState(
340:                     jobVertex != null,
341:                     "OperatorCoordinator providers were registered for JobVertexID '%s' but no corresponding JobVertex can be found.",
342:                     jobVertexId);
343:             FutureUtils.combineAll(futuresPerJobVertex.getValue())
344:                     .get()
345:                     .forEach(jobVertex::addOperatorCoordinator);
346:         }
347:     }
