349:     public static void addVertexIndexPrefixInVertexName(
350:             JobVertexBuildContext jobVertexBuildContext,
351:             AtomicInteger vertexIndexId,
352:             JobGraph jobGraph) {
353:         if (!jobVertexBuildContext.getStreamGraph().isVertexNameIncludeIndexPrefix()) {
354:             return;
355:         }
356:         Set<JobVertexID> jobVertexIds =
357:                 jobVertexBuildContext.getJobVerticesInOrder().values().stream()
358:                         .map(JobVertex::getID)
359:                         .collect(Collectors.toSet());
360:         // JobVertexBuildContext only contains incrementally generated jobVertex instances. The
361:         // setName method needs to set the names based on the topological order of all jobVertices,
362:         // so it relies on the job graph to compute a difference set.
363:         jobGraph.getVerticesSortedTopologicallyFromSources()
364:                 .forEach(
365:                         vertex -> {
366:                             if (jobVertexIds.contains(vertex.getID())) {
367:                                 vertex.setName(
368:                                         String.format(
369:                                                 "[vertex-%d]%s",
370:                                                 vertexIndexId.getAndIncrement(), vertex.getName()));
371:                             }
372:                         });
373:     }
