375:     public static void setVertexDescription(JobVertexBuildContext jobVertexBuildContext) {
376:         final Map<Integer, JobVertex> jobVertices = jobVertexBuildContext.getJobVerticesInOrder();
377:         final StreamGraph streamGraph = jobVertexBuildContext.getStreamGraph();
378:         for (Map.Entry<Integer, JobVertex> headOpAndJobVertex : jobVertices.entrySet()) {
379:             Integer headOpId = headOpAndJobVertex.getKey();
380:             JobVertex vertex = headOpAndJobVertex.getValue();
381:             StringBuilder builder = new StringBuilder();
382:             switch (streamGraph.getVertexDescriptionMode()) {
383:                 case CASCADING:
384:                     buildCascadingDescription(builder, headOpId, headOpId, jobVertexBuildContext);
385:                     break;
386:                 case TREE:
387:                     buildTreeDescription(
388:                             builder, headOpId, headOpId, "", true, jobVertexBuildContext);
389:                     break;
390:                 default:
391:                     throw new IllegalArgumentException(
392:                             String.format(
393:                                     "Description mode %s not supported",
394:                                     streamGraph.getVertexDescriptionMode()));
395:             }
396:             vertex.setOperatorPrettyName(builder.toString());
397:         }
398:     }
399: 
400:     private static void buildCascadingDescription(
401:             StringBuilder builder,
402:             int headOpId,
403:             int currentOpId,
404:             JobVertexBuildContext jobVertexBuildContext) {
405:         StreamNode node = jobVertexBuildContext.getStreamGraph().getStreamNode(currentOpId);
406:         builder.append(getDescriptionWithChainedSourcesInfo(node, jobVertexBuildContext));
407: 
408:         LinkedList<Integer> chainedOutput =
409:                 getChainedOutputNodes(headOpId, node, jobVertexBuildContext);
410:         if (chainedOutput.isEmpty()) {
411:             return;
412:         }
413:         builder.append(" -> ");
414: 
415:         boolean multiOutput = chainedOutput.size() > 1;
416:         if (multiOutput) {
417:             builder.append("(");
418:         }
419:         while (true) {
420:             Integer outputId = chainedOutput.pollFirst();
421:             buildCascadingDescription(builder, headOpId, outputId, jobVertexBuildContext);
422:             if (chainedOutput.isEmpty()) {
423:                 break;
424:             }
425:             builder.append(" , ");
426:         }
427:         if (multiOutput) {
428:             builder.append(")");
429:         }
430:     }
431: 
432:     private static LinkedList<Integer> getChainedOutputNodes(
433:             int headOpId, StreamNode node, JobVertexBuildContext jobVertexBuildContext) {
434:         LinkedList<Integer> chainedOutput = new LinkedList<>();
435:         Map<Integer, Map<Integer, StreamConfig>> chainedConfigs =
436:                 jobVertexBuildContext.getChainedConfigs();
437:         if (chainedConfigs.containsKey(headOpId)) {
438:             for (StreamEdge edge : node.getOutEdges()) {
439:                 int targetId = edge.getTargetId();
440:                 if (chainedConfigs.get(headOpId).containsKey(targetId)) {
441:                     chainedOutput.add(targetId);
442:                 }
443:             }
444:         }
445:         return chainedOutput;
446:     }
