448:     private static void buildTreeDescription(
449:             StringBuilder builder,
450:             int headOpId,
451:             int currentOpId,
452:             String prefix,
453:             boolean isLast,
454:             JobVertexBuildContext jobVertexBuildContext) {
455:         // Replace the '-' in prefix of current node with ' ', keep ':'
456:         // HeadNode
457:         // :- Node1
458:         // :  :- Child1
459:         // :  +- Child2
460:         // +- Node2
461:         //    :- Child3
462:         //    +- Child4
463:         String currentNodePrefix = "";
464:         String childPrefix = "";
465:         if (currentOpId != headOpId) {
466:             if (isLast) {
467:                 currentNodePrefix = prefix + "+- ";
468:                 childPrefix = prefix + "   ";
469:             } else {
470:                 currentNodePrefix = prefix + ":- ";
471:                 childPrefix = prefix + ":  ";
472:             }
473:         }
474: 
475:         StreamNode node = jobVertexBuildContext.getStreamGraph().getStreamNode(currentOpId);
476:         builder.append(currentNodePrefix);
477:         builder.append(getDescriptionWithChainedSourcesInfo(node, jobVertexBuildContext));
478:         builder.append("\n");
479: 
480:         LinkedList<Integer> chainedOutput =
481:                 getChainedOutputNodes(headOpId, node, jobVertexBuildContext);
482:         while (!chainedOutput.isEmpty()) {
483:             Integer outputId = chainedOutput.pollFirst();
484:             buildTreeDescription(
485:                     builder,
486:                     headOpId,
487:                     outputId,
488:                     childPrefix,
489:                     chainedOutput.isEmpty(),
490:                     jobVertexBuildContext);
491:         }
492:     }
