494:     private static String getDescriptionWithChainedSourcesInfo(
495:             StreamNode node, JobVertexBuildContext jobVertexBuildContext) {
496: 
497:         List<StreamNode> chainedSources;
498:         final Map<Integer, Map<Integer, StreamConfig>> chainedConfigs =
499:                 jobVertexBuildContext.getChainedConfigs();
500:         final StreamGraph streamGraph = jobVertexBuildContext.getStreamGraph();
501: 
502:         if (!chainedConfigs.containsKey(node.getId())) {
503:             // node is not head operator of a vertex
504:             chainedSources = Collections.emptyList();
505:         } else {
506:             chainedSources =
507:                     node.getInEdges().stream()
508:                             .map(StreamEdge::getSourceId)
509:                             .filter(
510:                                     id ->
511:                                             streamGraph.getSourceIDs().contains(id)
512:                                                     && chainedConfigs
513:                                                             .get(node.getId())
514:                                                             .containsKey(id))
515:                             .map(streamGraph::getStreamNode)
516:                             .collect(Collectors.toList());
517:         }
518:         return chainedSources.isEmpty()
519:                 ? node.getOperatorDescription()
520:                 : String.format(
521:                         "%s [%s]",
522:                         node.getOperatorDescription(),
523:                         chainedSources.stream()
524:                                 .map(StreamNode::getOperatorDescription)
525:                                 .collect(Collectors.joining(", ")));
526:     }
