528:     @SuppressWarnings("deprecation")
529:     public static void preValidate(StreamGraph streamGraph, ClassLoader userClassloader) {
530:         CheckpointConfig checkpointConfig = streamGraph.getCheckpointConfig();
531: 
532:         if (checkpointConfig.isCheckpointingEnabled()) {
533:             // temporarily forbid checkpointing for iterative jobs
534:             if (streamGraph.isIterative()
535:                     && checkpointConfig.isUnalignedCheckpointsEnabled()
536:                     && !checkpointConfig.isForceUnalignedCheckpoints()) {
537:                 throw new UnsupportedOperationException(
538:                         "Unaligned Checkpoints are currently not supported for iterative jobs, "
539:                                 + "as rescaling would require alignment (in addition to the reduced checkpointing guarantees)."
540:                                 + "\nThe user can force Unaligned Checkpoints by using 'execution.checkpointing.unaligned.forced'");
541:             }
542:             if (checkpointConfig.isUnalignedCheckpointsEnabled()
543:                     && !checkpointConfig.isForceUnalignedCheckpoints()
544:                     && streamGraph.getStreamNodes().stream()
545:                             .anyMatch(StreamingJobGraphGenerator::hasCustomPartitioner)) {
546:                 throw new UnsupportedOperationException(
547:                         "Unaligned checkpoints are currently not supported for custom partitioners, "
548:                                 + "as rescaling is not guaranteed to work correctly."
549:                                 + "\nThe user can force Unaligned Checkpoints by using 'execution.checkpointing.unaligned.forced'");
550:             }
551: 
552:             for (StreamNode node : streamGraph.getStreamNodes()) {
553:                 StreamOperatorFactory operatorFactory = node.getOperatorFactory();
554:                 if (operatorFactory != null) {
555:                     Class<?> operatorClass =
556:                             operatorFactory.getStreamOperatorClass(userClassloader);
557:                     if (InputSelectable.class.isAssignableFrom(operatorClass)) {
558: 
559:                         throw new UnsupportedOperationException(
560:                                 "Checkpointing is currently not supported for operators that implement InputSelectable:"
561:                                         + operatorClass.getName());
562:                     }
563:                 }
564:             }
565:         }
566: 
567:         if (checkpointConfig.isUnalignedCheckpointsEnabled()
568:                 && getCheckpointingMode(checkpointConfig) != CheckpointingMode.EXACTLY_ONCE) {
569:             LOG.warn("Unaligned checkpoints can only be used with checkpointing mode EXACTLY_ONCE");
570:             checkpointConfig.enableUnalignedCheckpoints(false);
571:         }
572:     }
573: 
574:     private static boolean hasCustomPartitioner(StreamNode node) {
575:         return node.getOutEdges().stream()
576:                 .anyMatch(edge -> edge.getPartitioner() instanceof CustomPartitionerWrapper);
577:     }
