579:     public static void setPhysicalEdges(JobVertexBuildContext jobVertexBuildContext) {
580:         Map<Integer, List<StreamEdge>> physicalInEdgesInOrder =
581:                 new HashMap<Integer, List<StreamEdge>>();
582: 
583:         for (StreamEdge edge : jobVertexBuildContext.getPhysicalEdgesInOrder()) {
584:             int target = edge.getTargetId();
585: 
586:             List<StreamEdge> inEdges =
587:                     physicalInEdgesInOrder.computeIfAbsent(target, k -> new ArrayList<>());
588: 
589:             inEdges.add(edge);
590:         }
591: 
592:         for (Map.Entry<Integer, List<StreamEdge>> inEdges : physicalInEdgesInOrder.entrySet()) {
593:             int vertex = inEdges.getKey();
594:             List<StreamEdge> edgeList = inEdges.getValue();
595: 
596:             jobVertexBuildContext
597:                     .getOperatorInfo(vertex)
598:                     .getVertexConfig()
599:                     .setInPhysicalEdges(edgeList);
600:         }
601:     }
