603:     private Map<Integer, OperatorChainInfo> buildChainedInputsAndGetHeadInputs() {
604: 
605:         final Map<Integer, ChainedSourceInfo> chainedSources = new HashMap<>();
606:         final Map<Integer, OperatorChainInfo> chainEntryPoints = new HashMap<>();
607: 
608:         for (Integer sourceNodeId : streamGraph.getSourceIDs()) {
609:             final StreamNode sourceNode = streamGraph.getStreamNode(sourceNodeId);
610: 
611:             if (sourceNode.getOperatorFactory() != null
612:                     && sourceNode.getOperatorFactory() instanceof SourceOperatorFactory
613:                     && sourceNode.getOutEdges().size() == 1) {
614:                 // as long as only NAry ops support this chaining, we need to skip the other parts
615:                 final StreamEdge sourceOutEdge = sourceNode.getOutEdges().get(0);
616:                 final StreamNode target = streamGraph.getStreamNode(sourceOutEdge.getTargetId());
617:                 final ChainingStrategy targetChainingStrategy =
618:                         Preconditions.checkNotNull(target.getOperatorFactory())
619:                                 .getChainingStrategy();
620: 
621:                 if (targetChainingStrategy == ChainingStrategy.HEAD_WITH_SOURCES
622:                         && isChainableInput(sourceOutEdge, streamGraph)) {
623:                     final OperatorInfo operatorInfo =
624:                             jobVertexBuildContext.createAndGetOperatorInfo(sourceNodeId);
625:                     final OperatorID opId =
626:                             new OperatorID(jobVertexBuildContext.getHash(sourceNodeId));
627:                     final StreamConfig.SourceInputConfig inputConfig =
628:                             new StreamConfig.SourceInputConfig(sourceOutEdge);
629:                     final StreamConfig operatorConfig = new StreamConfig(new Configuration());
630:                     setOperatorConfig(
631:                             sourceNodeId,
632:                             operatorConfig,
633:                             Collections.emptyMap(),
634:                             jobVertexBuildContext);
635:                     setOperatorChainedOutputsConfig(
636:                             operatorConfig, Collections.emptyList(), jobVertexBuildContext);
637:                     // we cache the non-chainable outputs here, and set the non-chained config later
638:                     operatorInfo.addNonChainableOutputs(Collections.emptyList());
639: 
640:                     operatorConfig.setChainIndex(0); // sources are always first
641:                     operatorConfig.setOperatorID(opId);
642:                     operatorConfig.setOperatorName(sourceNode.getOperatorName());
643:                     chainedSources.put(
644:                             sourceNodeId, new ChainedSourceInfo(operatorConfig, inputConfig));
645: 
646:                     final SourceOperatorFactory<?> sourceOpFact =
647:                             (SourceOperatorFactory<?>) sourceNode.getOperatorFactory();
648:                     final OperatorCoordinator.Provider coord =
649:                             sourceOpFact.getCoordinatorProvider(sourceNode.getOperatorName(), opId);
650: 
651:                     final OperatorChainInfo chainInfo =
652:                             chainEntryPoints.computeIfAbsent(
653:                                     sourceOutEdge.getTargetId(),
654:                                     (k) ->
655:                                             new OperatorChainInfo(
656:                                                     sourceOutEdge.getTargetId(),
657:                                                     chainedSources,
658:                                                     streamGraph));
659:                     chainInfo.addCoordinatorProvider(coord);
660:                     chainInfo.recordChainedNode(sourceNodeId);
661:                     continue;
662:                 }
663:             }
664: 
665:             chainEntryPoints.put(
666:                     sourceNodeId, new OperatorChainInfo(sourceNodeId, chainedSources, streamGraph));
667:         }
668: 
669:         return chainEntryPoints;
670:     }
