672:     /**
673:      * Sets up task chains from the source {@link StreamNode} instances.
674:      *
675:      * <p>This will recursively create all {@link JobVertex} instances.
676:      */
677:     private void setChaining() {
678:         // we separate out the sources that run as inputs to another operator (chained inputs)
679:         // from the sources that needs to run as the main (head) operator.
680:         final Map<Integer, OperatorChainInfo> chainEntryPoints =
681:                 buildChainedInputsAndGetHeadInputs();
682:         final Collection<OperatorChainInfo> initialEntryPoints =
683:                 chainEntryPoints.entrySet().stream()
684:                         .sorted(Comparator.comparing(Map.Entry::getKey))
685:                         .map(Map.Entry::getValue)
686:                         .collect(Collectors.toList());
687: 
688:         // iterate over a copy of the values, because this map gets concurrently modified
689:         for (OperatorChainInfo info : initialEntryPoints) {
690:             createChain(
691:                     info.getStartNodeId(),
692:                     1, // operators start at position 1 because 0 is for chained source inputs
693:                     info,
694:                     chainEntryPoints);
695:         }
696:     }
697: 
698:     private List<StreamEdge> createChain(
699:             final Integer currentNodeId,
700:             final int chainIndex,
701:             final OperatorChainInfo chainInfo,
702:             final Map<Integer, OperatorChainInfo> chainEntryPoints) {
703: 
704:         Integer startNodeId = chainInfo.getStartNodeId();
705:         if (!builtVertices.contains(startNodeId)) {
706: 
707:             List<StreamEdge> transitiveOutEdges = new ArrayList<StreamEdge>();
708: 
709:             List<StreamEdge> chainableOutputs = new ArrayList<StreamEdge>();
710:             List<StreamEdge> nonChainableOutputs = new ArrayList<StreamEdge>();
711: 
712:             StreamNode currentNode = streamGraph.getStreamNode(currentNodeId);
713:             Attribute currentNodeAttribute = currentNode.getAttribute();
714:             boolean isNoOutputUntilEndOfInput =
715:                     currentNode.isOutputOnlyAfterEndOfStream()
716:                             || currentNodeAttribute.isNoOutputUntilEndOfInput();
717:             if (isNoOutputUntilEndOfInput) {
718:                 currentNodeAttribute.setNoOutputUntilEndOfInput(true);
719:             }
720: 
721:             for (StreamEdge outEdge : currentNode.getOutEdges()) {
722:                 if (isChainable(outEdge, streamGraph)) {
723:                     chainableOutputs.add(outEdge);
724:                 } else {
725:                     nonChainableOutputs.add(outEdge);
726:                 }
727:             }
728: 
729:             for (StreamEdge chainable : chainableOutputs) {
730:                 StreamNode targetNode = streamGraph.getStreamNode(chainable.getTargetId());
731:                 Attribute targetNodeAttribute = targetNode.getAttribute();
732:                 if (isNoOutputUntilEndOfInput) {
733:                     if (targetNodeAttribute != null) {
734:                         targetNodeAttribute.setNoOutputUntilEndOfInput(true);
735:                     }
736:                 }
737:                 transitiveOutEdges.addAll(
738:                         createChain(
739:                                 chainable.getTargetId(),
740:                                 chainIndex + 1,
741:                                 chainInfo,
742:                                 chainEntryPoints));
743:                 // Mark upstream nodes in the same chain as outputBlocking
744:                 if (targetNodeAttribute != null
745:                         && targetNodeAttribute.isNoOutputUntilEndOfInput()) {
746:                     currentNodeAttribute.setNoOutputUntilEndOfInput(true);
747:                 }
748:             }
749: 
750:             for (StreamEdge nonChainable : nonChainableOutputs) {
751:                 transitiveOutEdges.add(nonChainable);
752:                 createChain(
753:                         nonChainable.getTargetId(),
754:                         1, // operators start at position 1 because 0 is for chained source inputs
755:                         chainEntryPoints.computeIfAbsent(
756:                                 nonChainable.getTargetId(),
757:                                 (k) -> chainInfo.newChain(nonChainable.getTargetId())),
758:                         chainEntryPoints);
759:             }
760: 
761:             chainInfo.addChainedName(
762:                     currentNodeId,
763:                     createChainedName(
764:                             currentNodeId,
765:                             chainableOutputs,
766:                             Optional.ofNullable(chainEntryPoints.get(currentNodeId)),
767:                             chainInfo.getChainedNames(),
768:                             jobVertexBuildContext));
769: 
770:             chainInfo.addChainedMinResources(
771:                     currentNodeId,
772:                     createChainedMinResources(
773:                             currentNodeId, chainableOutputs, chainInfo, jobVertexBuildContext));
774: 
775:             chainInfo.addChainedPreferredResources(
776:                     currentNodeId,
777:                     createChainedPreferredResources(
778:                             currentNodeId, chainableOutputs, chainInfo, jobVertexBuildContext));
779: 
780:             OperatorID currentOperatorId =
781:                     chainInfo.addNodeToChain(
782:                             currentNodeId,
783:                             streamGraph.getStreamNode(currentNodeId).getOperatorName(),
784:                             jobVertexBuildContext);
785: 
786:             if (currentNode.getInputFormat() != null) {
787:                 chainInfo
788:                         .getOrCreateFormatContainer()
789:                         .addInputFormat(currentOperatorId, currentNode.getInputFormat());
790:             }
791: 
792:             if (currentNode.getOutputFormat() != null) {
793:                 chainInfo
794:                         .getOrCreateFormatContainer()
795:                         .addOutputFormat(currentOperatorId, currentNode.getOutputFormat());
796:             }
797:             OperatorInfo operatorInfo =
798:                     jobVertexBuildContext.createAndGetOperatorInfo(currentNodeId);
799: 
800:             StreamConfig config =
801:                     currentNodeId.equals(startNodeId)
802:                             ? createJobVertex(startNodeId, chainInfo)
803:                             : new StreamConfig(new Configuration());
804: 
805:             tryConvertPartitionerForDynamicGraph(
806:                     chainableOutputs, nonChainableOutputs, jobVertexBuildContext);
807:             config.setAttribute(currentNodeAttribute);
808:             setOperatorConfig(
809:                     currentNodeId, config, chainInfo.getChainedSources(), jobVertexBuildContext);
810: 
811:             setOperatorChainedOutputsConfig(config, chainableOutputs, jobVertexBuildContext);
812:             // we cache the non-chainable outputs here, and set the non-chained config later
813:             operatorInfo.addNonChainableOutputs(nonChainableOutputs);
814: 
815:             if (currentNodeId.equals(startNodeId)) {
816:                 chainInfo.setTransitiveOutEdges(transitiveOutEdges);
817:                 jobVertexBuildContext.addChainInfo(startNodeId, chainInfo);
818: 
819:                 config.setChainStart();
820:                 config.setChainIndex(chainIndex);
821:                 config.setOperatorName(streamGraph.getStreamNode(currentNodeId).getOperatorName());
822:                 config.setTransitiveChainedTaskConfigs(
823:                         jobVertexBuildContext.getChainedConfigs().get(startNodeId));
824:             } else {
825:                 config.setChainIndex(chainIndex);
826:                 StreamNode node = streamGraph.getStreamNode(currentNodeId);
827:                 config.setOperatorName(node.getOperatorName());
828:                 jobVertexBuildContext
829:                         .getOrCreateChainedConfig(startNodeId)
830:                         .put(currentNodeId, config);
831:             }
832: 
833:             config.setOperatorID(currentOperatorId);
834: 
835:             if (chainableOutputs.isEmpty()) {
836:                 config.setChainEnd();
837:             }
838:             return transitiveOutEdges;
839: 
840:         } else {
841:             return new ArrayList<>();
842:         }
843:     }
