1030:     private StreamConfig createJobVertex(Integer streamNodeId, OperatorChainInfo chainInfo) {
1031: 
1032:         JobVertex jobVertex;
1033:         StreamNode streamNode = streamGraph.getStreamNode(streamNodeId);
1034: 
1035:         byte[] hash = jobVertexBuildContext.getHash(streamNodeId);
1036: 
1037:         if (hash == null) {
1038:             throw new IllegalStateException(
1039:                     "Cannot find node hash. "
1040:                             + "Did you generate them before calling this method?");
1041:         }
1042: 
1043:         JobVertexID jobVertexId = new JobVertexID(hash);
1044: 
1045:         List<ChainedOperatorHashInfo> chainedOperators =
1046:                 chainInfo.getChainedOperatorHashes(streamNodeId);
1047:         List<OperatorIDPair> operatorIDPairs = new ArrayList<>();
1048:         if (chainedOperators != null) {
1049:             for (ChainedOperatorHashInfo chainedOperator : chainedOperators) {
1050:                 OperatorID userDefinedOperatorID =
1051:                         chainedOperator.getUserDefinedOperatorId() == null
1052:                                 ? null
1053:                                 : new OperatorID(chainedOperator.getUserDefinedOperatorId());
1054:                 operatorIDPairs.add(
1055:                         OperatorIDPair.of(
1056:                                 new OperatorID(chainedOperator.getGeneratedOperatorId()),
1057:                                 userDefinedOperatorID,
1058:                                 chainedOperator.getStreamNode().getOperatorName(),
1059:                                 chainedOperator.getStreamNode().getTransformationUID()));
1060:             }
1061:         }
1062: 
1063:         if (chainInfo.hasFormatContainer()) {
1064:             jobVertex =
1065:                     new InputOutputFormatVertex(
1066:                             chainInfo.getChainedName(streamNodeId), jobVertexId, operatorIDPairs);
1067:             chainInfo
1068:                     .getOrCreateFormatContainer()
1069:                     .write(new TaskConfig(jobVertex.getConfiguration()));
1070:         } else {
1071:             jobVertex =
1072:                     new JobVertex(
1073:                             chainInfo.getChainedName(streamNodeId), jobVertexId, operatorIDPairs);
1074:         }
1075: 
1076:         if (streamNode.getConsumeClusterDatasetId() != null) {
1077:             jobVertex.addIntermediateDataSetIdToConsume(streamNode.getConsumeClusterDatasetId());
1078:         }
1079: 
1080:         final List<CompletableFuture<SerializedValue<OperatorCoordinator.Provider>>>
1081:                 serializationFutures = new ArrayList<>();
1082:         for (OperatorCoordinator.Provider coordinatorProvider :
1083:                 chainInfo.getCoordinatorProviders()) {
1084:             serializationFutures.add(
1085:                     CompletableFuture.supplyAsync(
1086:                             () -> {
1087:                                 try {
1088:                                     return new SerializedValue<>(coordinatorProvider);
1089:                                 } catch (IOException e) {
1090:                                     throw new FlinkRuntimeException(
1091:                                             String.format(
1092:                                                     "Coordinator Provider for node %s is not serializable.",
1093:                                                     chainInfo.getChainedName(streamNodeId)),
1094:                                             e);
1095:                                 }
1096:                             },
1097:                             serializationExecutor));
1098:         }
1099:         if (!serializationFutures.isEmpty()) {
1100:             jobVertexBuildContext.putCoordinatorSerializationFutures(
1101:                     jobVertexId, serializationFutures);
1102:         }
1103: 
1104:         jobVertex.setResources(
1105:                 chainInfo.getChainedMinResources(streamNodeId),
1106:                 chainInfo.getChainedPreferredResources(streamNodeId));
1107: 
1108:         jobVertex.setInvokableClass(streamNode.getJobVertexClass());
1109: 
1110:         int parallelism = streamNode.getParallelism();
1111: 
1112:         if (parallelism > 0) {
1113:             jobVertex.setParallelism(parallelism);
1114:         } else {
1115:             parallelism = jobVertex.getParallelism();
1116:         }
1117: 
1118:         jobVertex.setMaxParallelism(streamNode.getMaxParallelism());
1119: 
1120:         if (LOG.isDebugEnabled()) {
1121:             LOG.debug("Parallelism set: {} for {}", parallelism, streamNodeId);
1122:         }
1123: 
1124:         jobVertexBuildContext.addJobVertex(streamNodeId, jobVertex);
1125:         builtVertices.add(streamNodeId);
1126:         executionPlan.addVertex(jobVertex);
1127: 
1128:         jobVertex.setParallelismConfigured(
1129:                 chainInfo.getAllChainedNodes().stream()
1130:                         .anyMatch(StreamNode::isParallelismConfigured));
1131: 
1132:         return new StreamConfig(jobVertex.getConfiguration());
1133:     }
