1135:     public static void setOperatorConfig(
1136:             Integer vertexId,
1137:             StreamConfig config,
1138:             Map<Integer, ChainedSourceInfo> chainedSources,
1139:             JobVertexBuildContext jobVertexBuildContext) {
1140:         StreamGraph streamGraph = jobVertexBuildContext.getStreamGraph();
1141:         OperatorInfo operatorInfo = jobVertexBuildContext.getOperatorInfo(vertexId);
1142:         StreamNode vertex = streamGraph.getStreamNode(vertexId);
1143: 
1144:         config.setVertexID(vertexId);
1145: 
1146:         // build the inputs as a combination of source and network inputs
1147:         final List<StreamEdge> inEdges = vertex.getInEdges();
1148:         final TypeSerializer<?>[] inputSerializers = vertex.getTypeSerializersIn();
1149: 
1150:         final StreamConfig.InputConfig[] inputConfigs =
1151:                 new StreamConfig.InputConfig[inputSerializers.length];
1152: 
1153:         int inputGateCount = 0;
1154:         for (final StreamEdge inEdge : inEdges) {
1155:             final ChainedSourceInfo chainedSource = chainedSources.get(inEdge.getSourceId());
1156: 
1157:             final int inputIndex =
1158:                     inEdge.getTypeNumber() == 0
1159:                             ? 0 // single input operator
1160:                             : inEdge.getTypeNumber() - 1; // in case of 2 or more inputs
1161: 
1162:             if (chainedSource != null) {
1163:                 // chained source is the input
1164:                 if (inputConfigs[inputIndex] != null) {
1165:                     throw new IllegalStateException(
1166:                             "Trying to union a chained source with another input.");
1167:                 }
1168:                 inputConfigs[inputIndex] = chainedSource.getInputConfig();
1169:                 jobVertexBuildContext
1170:                         .getOrCreateChainedConfig(vertexId)
1171:                         .put(inEdge.getSourceId(), chainedSource.getOperatorConfig());
1172:             } else {
1173:                 // network input. null if we move to a new input, non-null if this is a further edge
1174:                 // that is union-ed into the same input
1175:                 if (inputConfigs[inputIndex] == null) {
1176:                     // PASS_THROUGH is a sensible default for streaming jobs. Only for BATCH
1177:                     // execution can we have sorted inputs
1178:                     StreamConfig.InputRequirement inputRequirement =
1179:                             vertex.getInputRequirements()
1180:                                     .getOrDefault(
1181:                                             inputIndex, StreamConfig.InputRequirement.PASS_THROUGH);
1182:                     inputConfigs[inputIndex] =
1183:                             new StreamConfig.NetworkInputConfig(
1184:                                     inputSerializers[inputIndex],
1185:                                     inputGateCount++,
1186:                                     inputRequirement);
1187:                 }
1188:             }
1189:         }
1190: 
1191:         // set the input config of the vertex if it consumes from cached intermediate dataset.
1192:         if (vertex.getConsumeClusterDatasetId() != null) {
1193:             config.setNumberOfNetworkInputs(1);
1194:             inputConfigs[0] = new StreamConfig.NetworkInputConfig(inputSerializers[0], 0);
1195:         }
1196: 
1197:         config.setInputs(inputConfigs);
1198: 
1199:         config.setTypeSerializerOut(vertex.getTypeSerializerOut());
1200: 
1201:         config.setStreamOperatorFactory(vertex.getOperatorFactory());
1202: 
1203:         final CheckpointConfig checkpointCfg = streamGraph.getCheckpointConfig();
1204: 
1205:         config.setStateBackend(streamGraph.getStateBackend());
1206:         config.setCheckpointStorage(streamGraph.getCheckpointStorage());
1207:         config.setGraphContainingLoops(streamGraph.isIterative());
1208:         config.setTimerServiceProvider(streamGraph.getTimerServiceProvider());
1209:         config.setCheckpointingEnabled(checkpointCfg.isCheckpointingEnabled());
1210:         config.getConfiguration()
1211:                 .set(
1212:                         CheckpointingOptions.ENABLE_CHECKPOINTS_AFTER_TASKS_FINISH,
1213:                         streamGraph.isEnableCheckpointsAfterTasksFinish());
1214:         config.setCheckpointMode(getCheckpointingMode(checkpointCfg));
1215:         config.setUnalignedCheckpointsEnabled(checkpointCfg.isUnalignedCheckpointsEnabled());
1216:         config.setUnalignedCheckpointsSplittableTimersEnabled(
1217:                 checkpointCfg.isUnalignedCheckpointsInterruptibleTimersEnabled());
1218:         config.setAlignedCheckpointTimeout(checkpointCfg.getAlignedCheckpointTimeout());
1219:         config.setMaxSubtasksPerChannelStateFile(checkpointCfg.getMaxSubtasksPerChannelStateFile());
1220:         config.setMaxConcurrentCheckpoints(checkpointCfg.getMaxConcurrentCheckpoints());
1221: 
1222:         for (int i = 0; i < vertex.getStatePartitioners().length; i++) {
1223:             config.setStatePartitioner(i, vertex.getStatePartitioners()[i]);
1224:         }
1225:         config.setStateKeySerializer(vertex.getStateKeySerializer());
1226: 
1227:         Class<? extends TaskInvokable> vertexClass = vertex.getJobVertexClass();
1228: 
1229:         if (vertexClass.equals(StreamIterationHead.class)
1230:                 || vertexClass.equals(StreamIterationTail.class)) {
1231:             config.setIterationId(streamGraph.getBrokerID(vertexId));
1232:             config.setIterationWaitTime(streamGraph.getLoopTimeout(vertexId));
1233:         }
1234: 
1235:         operatorInfo.setVertexConfig(config);
1236:     }
