1248:                                 .getTypeInfo()
1249:                                 .createSerializer(
1250:                                         jobVertexBuildContext
1251:                                                 .getStreamGraph()
1252:                                                 .getExecutionConfig()
1253:                                                 .getSerializerConfig()));
1254:             }
1255:         }
1256:         config.setChainedOutputs(chainableOutputs);
