1349:     private static List<NonChainedOutput> mayReuseNonChainedOutputs(
1350:             int vertexId,
1351:             List<StreamEdge> consumerEdges,
1352:             Map<StreamEdge, NonChainedOutput> outputsConsumedByEdge,
1353:             JobVertexBuildContext jobVertexBuildContext) {
1354:         if (consumerEdges.isEmpty()) {
1355:             return new ArrayList<>();
1356:         }
1357:         List<NonChainedOutput> outputs = new ArrayList<>(consumerEdges.size());
1358:         for (StreamEdge consumerEdge : consumerEdges) {
1359:             checkState(vertexId == consumerEdge.getSourceId(), "Vertex id must be the same.");
1360:             ResultPartitionType partitionType =
1361:                     getResultPartitionType(consumerEdge, jobVertexBuildContext);
1362:             IntermediateDataSetID dataSetId = new IntermediateDataSetID();
1363: 
1364:             boolean isPersistentDataSet =
1365:                     isPersistentIntermediateDataset(partitionType, consumerEdge);
1366:             if (isPersistentDataSet) {
1367:                 partitionType = ResultPartitionType.BLOCKING_PERSISTENT;
1368:                 dataSetId = consumerEdge.getIntermediateDatasetIdToProduce();
1369:             }
1370: 
1371:             if (partitionType.isHybridResultPartition()) {
1372:                 jobVertexBuildContext.setHasHybridResultPartition(true);
1373:                 if (consumerEdge.getPartitioner().isBroadcast()
1374:                         && partitionType == ResultPartitionType.HYBRID_SELECTIVE) {
1375:                     // for broadcast result partition, it can be optimized to always use full
1376:                     // spilling strategy to significantly reduce shuffle data writing cost.
1377:                     LOG.info(
1378:                             "{} result partition has been replaced by {} result partition to support "
1379:                                     + "broadcast optimization, which will reduce shuffle data writing cost.",
1380:                             partitionType.name(),
1381:                             ResultPartitionType.HYBRID_FULL.name());
1382:                     partitionType = ResultPartitionType.HYBRID_FULL;
1383:                 }
1384:             }
1385: 
1386:             createOrReuseOutput(
1387:                     outputs,
1388:                     outputsConsumedByEdge,
1389:                     consumerEdge,
1390:                     isPersistentDataSet,
1391:                     dataSetId,
1392:                     partitionType,
1393:                     jobVertexBuildContext.getStreamGraph());
1394:         }
1395:         return outputs;
1396:     }
