1398:     private static void createOrReuseOutput(
1399:             List<NonChainedOutput> outputs,
1400:             Map<StreamEdge, NonChainedOutput> outputsConsumedByEdge,
1401:             StreamEdge consumerEdge,
1402:             boolean isPersistentDataSet,
1403:             IntermediateDataSetID dataSetId,
1404:             ResultPartitionType partitionType,
1405:             StreamGraph streamGraph) {
1406:         int consumerParallelism =
1407:                 streamGraph.getStreamNode(consumerEdge.getTargetId()).getParallelism();
1408:         int consumerMaxParallelism =
1409:                 streamGraph.getStreamNode(consumerEdge.getTargetId()).getMaxParallelism();
1410:         NonChainedOutput reusableOutput = null;
1411:         if (isPartitionTypeCanBeReuse(partitionType)) {
1412:             for (NonChainedOutput outputCandidate : outputsConsumedByEdge.values()) {
1413:                 // Reusing the same output can improve performance. The target output can be reused
1414:                 // if meeting the following conditions:
1415:                 // 1. all is hybrid partition or are same re-consumable partition.
1416:                 // 2. have the same partitioner, consumer parallelism, persistentDataSetId,
1417:                 // outputTag.
1418:                 if (allHybridOrSameReconsumablePartitionType(
1419:                                 outputCandidate.getPartitionType(), partitionType)
1420:                         && consumerParallelism == outputCandidate.getConsumerParallelism()
1421:                         && consumerMaxParallelism == outputCandidate.getConsumerMaxParallelism()
1422:                         && Objects.equals(
1423:                                 outputCandidate.getPersistentDataSetId(),
1424:                                 consumerEdge.getIntermediateDatasetIdToProduce())
1425:                         && Objects.equals(
1426:                                 outputCandidate.getOutputTag(), consumerEdge.getOutputTag())
1427:                         && Objects.equals(
1428:                                 consumerEdge.getPartitioner(), outputCandidate.getPartitioner())) {
1429:                     reusableOutput = outputCandidate;
1430:                     outputsConsumedByEdge.put(consumerEdge, reusableOutput);
1431:                     checkAndReplaceReusableHybridPartitionType(reusableOutput);
1432:                     break;
1433:                 }
1434:             }
1435:         }
1436:         if (reusableOutput == null) {
1437:             NonChainedOutput output =
1438:                     new NonChainedOutput(
1439:                             consumerEdge.supportsUnalignedCheckpoints(),
1440:                             consumerEdge.getSourceId(),
1441:                             consumerParallelism,
1442:                             consumerMaxParallelism,
1443:                             consumerEdge.getBufferTimeout(),
1444:                             isPersistentDataSet,
1445:                             dataSetId,
1446:                             consumerEdge.getOutputTag(),
1447:                             consumerEdge.getPartitioner(),
1448:                             partitionType);
1449:             outputs.add(output);
1450:             outputsConsumedByEdge.put(consumerEdge, output);
1451:         }
1452:     }
