1454:     private static boolean isPartitionTypeCanBeReuse(ResultPartitionType partitionType) {
1455:         // for non-hybrid partition, partition reuse only works when its re-consumable.
1456:         // for hybrid selective partition, it still has the opportunity to be converted to
1457:         // hybrid full partition to support partition reuse.
1458:         return partitionType.isReconsumable() || partitionType.isHybridResultPartition();
1459:     }
