1461:     private static boolean allHybridOrSameReconsumablePartitionType(
1462:             ResultPartitionType partitionType1, ResultPartitionType partitionType2) {
1463:         return (partitionType1.isReconsumable() && partitionType1 == partitionType2)
1464:                 || (partitionType1.isHybridResultPartition()
1465:                         && partitionType2.isHybridResultPartition());
1466:     }
