1521:     public static void connect(
1522:             Integer headOfChain,
1523:             StreamEdge edge,
1524:             NonChainedOutput output,
1525:             Map<Integer, JobVertex> jobVertices,
1526:             JobVertexBuildContext jobVertexBuildContext) {
1527: 
1528:         jobVertexBuildContext.addPhysicalEdgesInOrder(edge);
1529: 
1530:         Integer downStreamVertexID = edge.getTargetId();
1531: 
1532:         JobVertex headVertex = jobVertices.get(headOfChain);
1533:         JobVertex downStreamVertex = jobVertices.get(downStreamVertexID);
1534: 
1535:         StreamConfig downStreamConfig = new StreamConfig(downStreamVertex.getConfiguration());
1536: 
1537:         downStreamConfig.setNumberOfNetworkInputs(downStreamConfig.getNumberOfNetworkInputs() + 1);
1538: 
1539:         StreamPartitioner<?> partitioner = output.getPartitioner();
1540:         ResultPartitionType resultPartitionType = output.getPartitionType();
1541: 
1542:         checkBufferTimeout(resultPartitionType, edge);
1543: 
1544:         JobEdge jobEdge;
1545:         if (partitioner.isPointwise()) {
1546:             jobEdge =
1547:                     downStreamVertex.connectNewDataSetAsInput(
1548:                             headVertex,
1549:                             DistributionPattern.POINTWISE,
1550:                             resultPartitionType,
1551:                             output.getDataSetId(),
1552:                             partitioner.isBroadcast());
1553:         } else {
1554:             jobEdge =
1555:                     downStreamVertex.connectNewDataSetAsInput(
1556:                             headVertex,
1557:                             DistributionPattern.ALL_TO_ALL,
1558:                             resultPartitionType,
1559:                             output.getDataSetId(),
1560:                             partitioner.isBroadcast());
1561:         }
1562: 
1563:         // set strategy name so that web interface can show it.
1564:         jobEdge.setShipStrategyName(partitioner.toString());
1565:         jobEdge.setForward(partitioner instanceof ForwardPartitioner);
1566:         jobEdge.setDownstreamSubtaskStateMapper(partitioner.getDownstreamSubtaskStateMapper());
1567:         jobEdge.setUpstreamSubtaskStateMapper(partitioner.getUpstreamSubtaskStateMapper());
1568: 
1569:         if (LOG.isDebugEnabled()) {
1570:             LOG.debug(
1571:                     "CONNECTED: {} - {} -> {}",
1572:                     partitioner.getClass().getSimpleName(),
1573:                     headOfChain,
1574:                     downStreamVertexID);
1575:         }
1576:     }
