1584:     private static void checkBufferTimeout(ResultPartitionType type, StreamEdge edge) {
1585:         long bufferTimeout = edge.getBufferTimeout();
1586:         if (!type.canBePipelinedConsumed()
1587:                 && bufferTimeout != ExecutionOptions.DISABLED_NETWORK_BUFFER_TIMEOUT) {
1588:             throw new UnsupportedOperationException(
1589:                     "only canBePipelinedConsumed partition support buffer timeout "
1590:                             + bufferTimeout
1591:                             + " for src operator in edge "
1592:                             + edge
1593:                             + ". \nPlease either disable buffer timeout (via -1) or use the canBePipelinedConsumed partition.");
1594:         }
1595:     }
