1597:     private static ResultPartitionType getResultPartitionType(
1598:             StreamEdge edge, JobVertexBuildContext jobVertexBuildContext) {
1599:         switch (edge.getExchangeMode()) {
1600:             case PIPELINED:
1601:                 return ResultPartitionType.PIPELINED_BOUNDED;
1602:             case BATCH:
1603:                 return ResultPartitionType.BLOCKING;
1604:             case HYBRID_FULL:
1605:                 return ResultPartitionType.HYBRID_FULL;
1606:             case HYBRID_SELECTIVE:
1607:                 return ResultPartitionType.HYBRID_SELECTIVE;
1608:             case UNDEFINED:
1609:                 return determineUndefinedResultPartitionType(edge, jobVertexBuildContext);
1610:             default:
1611:                 throw new UnsupportedOperationException(
1612:                         "Data exchange mode " + edge.getExchangeMode() + " is not supported yet.");
1613:         }
1614:     }
