1657:     public static boolean isChainable(StreamEdge edge, StreamGraph streamGraph) {
1658:         StreamNode downStreamVertex = streamGraph.getTargetVertex(edge);
1659: 
1660:         return downStreamVertex.getInEdges().size() == 1 && isChainableInput(edge, streamGraph);
1661:     }
