1663:     public static boolean isChainableInput(StreamEdge edge, StreamGraph streamGraph) {
1664:         StreamNode upStreamVertex = streamGraph.getSourceVertex(edge);
1665:         StreamNode downStreamVertex = streamGraph.getTargetVertex(edge);
1666: 
1667:         if (!(streamGraph.isChainingEnabled()
1668:                 && upStreamVertex.isSameSlotSharingGroup(downStreamVertex)
1669:                 && areOperatorsChainable(upStreamVertex, downStreamVertex, streamGraph)
1670:                 && arePartitionerAndExchangeModeChainable(
1671:                         edge.getPartitioner(), edge.getExchangeMode(), streamGraph.isDynamic()))) {
1672: 
1673:             return false;
1674:         }
1675: 
1676:         // check that we do not have a union operation, because unions currently only work
1677:         // through the network/byte-channel stack.
1678:         // we check that by testing that each "type" (which means input position) is used only once
1679:         for (StreamEdge inEdge : downStreamVertex.getInEdges()) {
1680:             if (inEdge != edge && inEdge.getTypeNumber() == edge.getTypeNumber()) {
1681:                 return false;
1682:             }
1683:         }
1684:         return true;
1685:     }
