1687:     @VisibleForTesting
1688:     static boolean arePartitionerAndExchangeModeChainable(
1689:             StreamPartitioner<?> partitioner,
1690:             StreamExchangeMode exchangeMode,
1691:             boolean isDynamicGraph) {
1692:         if (partitioner instanceof ForwardForConsecutiveHashPartitioner) {
1693:             checkState(isDynamicGraph);
1694:             return true;
1695:         } else if ((partitioner instanceof ForwardPartitioner)
1696:                 && exchangeMode != StreamExchangeMode.BATCH) {
1697:             return true;
1698:         } else {
1699:             return false;
1700:         }
1701:     }
