1703:     @VisibleForTesting
1704:     static boolean areOperatorsChainable(
1705:             StreamNode upStreamVertex, StreamNode downStreamVertex, StreamGraph streamGraph) {
1706:         StreamOperatorFactory<?> upStreamOperator = upStreamVertex.getOperatorFactory();
1707:         StreamOperatorFactory<?> downStreamOperator = downStreamVertex.getOperatorFactory();
1708:         if (downStreamOperator == null || upStreamOperator == null) {
1709:             return false;
1710:         }
1711: 
1712:         // yielding operators cannot be chained to legacy sources
1713:         // unfortunately the information that vertices have been chained is not preserved at this
1714:         // point
1715:         if (downStreamOperator instanceof YieldingOperatorFactory
1716:                 && getHeadOperator(upStreamVertex, streamGraph).isLegacySource()) {
1717:             return false;
1718:         }
1719: 
1720:         // we use switch/case here to make sure this is exhaustive if ever values are added to the
1721:         // ChainingStrategy enum
1722:         boolean isChainable;
1723: 
1724:         switch (upStreamOperator.getChainingStrategy()) {
1725:             case NEVER:
1726:                 isChainable = false;
1727:                 break;
1728:             case ALWAYS:
1729:             case HEAD:
1730:             case HEAD_WITH_SOURCES:
1731:                 isChainable = true;
1732:                 break;
1733:             default:
1734:                 throw new RuntimeException(
1735:                         "Unknown chaining strategy: " + upStreamOperator.getChainingStrategy());
1736:         }
1737: 
1738:         switch (downStreamOperator.getChainingStrategy()) {
1739:             case NEVER:
1740:             case HEAD:
1741:                 isChainable = false;
1742:                 break;
1743:             case ALWAYS:
1744:                 // keep the value from upstream
1745:                 break;
1746:             case HEAD_WITH_SOURCES:
1747:                 // only if upstream is a source
1748:                 isChainable &= (upStreamOperator instanceof SourceOperatorFactory);
1749:                 break;
1750:             default:
1751:                 throw new RuntimeException(
1752:                         "Unknown chaining strategy: " + downStreamOperator.getChainingStrategy());
1753:         }
1754: 
1755:         // Only vertices with the same parallelism can be chained.
1756:         isChainable &= upStreamVertex.getParallelism() == downStreamVertex.getParallelism();
1757: 
1758:         if (!streamGraph.isChainingOfOperatorsWithDifferentMaxParallelismEnabled()) {
1759:             isChainable &=
1760:                     upStreamVertex.getMaxParallelism() == downStreamVertex.getMaxParallelism();
1761:         }
1762: 
1763:         return isChainable;
1764:     }
