1766:     /** Backtraces the head of an operator chain. */
1767:     private static StreamOperatorFactory<?> getHeadOperator(
1768:             StreamNode upStreamVertex, StreamGraph streamGraph) {
1769:         if (streamGraph.getHeadOperatorForNodeFromCache(upStreamVertex) == null) {
1770:             if (upStreamVertex.getInEdges().size() == 1
1771:                     && isChainable(upStreamVertex.getInEdges().get(0), streamGraph)) {
1772:                 StreamOperatorFactory<?> headOperator =
1773:                         getHeadOperator(
1774:                                 streamGraph.getSourceVertex(upStreamVertex.getInEdges().get(0)),
1775:                                 streamGraph);
1776:                 streamGraph.cacheHeadOperatorForNode(upStreamVertex, headOperator);
1777:             } else {
1778:                 Preconditions.checkNotNull(upStreamVertex.getOperatorFactory());
1779:                 streamGraph.cacheHeadOperatorForNode(
1780:                         upStreamVertex, upStreamVertex.getOperatorFactory());
1781:             }
1782:         }
1783: 
1784:         return streamGraph.getHeadOperatorForNodeFromCache(upStreamVertex);
1785:     }
