1790:         StreamGraph streamGraph = jobVertexBuildContext.getStreamGraph();
1791: 
1792:         for (Map.Entry<Integer, JobVertex> entry : jobVertices.entrySet()) {
1793:             final JobVertex jobVertex = entry.getValue();
