1801: 
1802:             // disable supportConcurrentExecutionAttempts of job vertex if there is any stream node
1803:             // does not support it
1804:             boolean supportConcurrentExecutionAttempts = true;
1805:             for (int nodeId : vertexOperators) {
1806:                 final StreamNode streamNode = streamGraph.getStreamNode(nodeId);
1807:                 if (!streamNode.isSupportsConcurrentExecutionAttempts()) {
1808:                     supportConcurrentExecutionAttempts = false;
1809:                     break;
1810:                 }
1811:             }
1812:             jobVertex.setSupportsConcurrentExecutionAttempts(supportConcurrentExecutionAttempts);
