1822:     private static void setSlotSharing(
1823:             JobGraph jobGraph, JobVertexBuildContext jobVertexBuildContext) {
1824:         StreamGraph streamGraph = jobVertexBuildContext.getStreamGraph();
1825:         final Map<String, SlotSharingGroup> specifiedSlotSharingGroups = new HashMap<>();
1826:         final Map<JobVertexID, SlotSharingGroup> vertexRegionSlotSharingGroups =
1827:                 buildVertexRegionSlotSharingGroups(jobGraph, jobVertexBuildContext);
1828:         final Map<Integer, JobVertex> jobVertices = jobVertexBuildContext.getJobVerticesInOrder();
1829: 
1830:         for (Map.Entry<Integer, JobVertex> entry : jobVertices.entrySet()) {
1831: 
1832:             final JobVertex vertex = entry.getValue();
1833:             final String slotSharingGroupKey =
1834:                     streamGraph.getStreamNode(entry.getKey()).getSlotSharingGroup();
1835: 
1836:             checkNotNull(slotSharingGroupKey, "StreamNode slot sharing group must not be null");
1837: 
1838:             final SlotSharingGroup effectiveSlotSharingGroup;
1839:             if (slotSharingGroupKey.equals(StreamGraphGenerator.DEFAULT_SLOT_SHARING_GROUP)) {
1840:                 // fallback to the region slot sharing group by default
1841:                 effectiveSlotSharingGroup =
1842:                         checkNotNull(vertexRegionSlotSharingGroups.get(vertex.getID()));
1843:             } else {
1844:                 checkState(
1845:                         !jobVertexBuildContext.hasHybridResultPartition(),
1846:                         "hybrid shuffle mode currently does not support setting non-default slot sharing group.");
1847: 
1848:                 effectiveSlotSharingGroup =
1849:                         specifiedSlotSharingGroups.computeIfAbsent(
1850:                                 slotSharingGroupKey,
1851:                                 k -> {
1852:                                     SlotSharingGroup ssg = new SlotSharingGroup();
1853:                                     streamGraph
1854:                                             .getSlotSharingGroupResource(k)
1855:                                             .ifPresent(ssg::setResourceProfile);
1856:                                     return ssg;
1857:                                 });
1858:             }
1859: 
1860:             vertex.setSlotSharingGroup(effectiveSlotSharingGroup);
1861:         }
1862:     }
