1875:     /**
1876:      * Maps a vertex to its region slot sharing group. If {@link
1877:      * StreamGraph#isAllVerticesInSameSlotSharingGroupByDefault()} returns true, all regions will be
1878:      * in the same slot sharing group.
1879:      */
1880:     private static Map<JobVertexID, SlotSharingGroup> buildVertexRegionSlotSharingGroups(
1881:             JobGraph jobGraph, JobVertexBuildContext jobVertexBuildContext) {
1882:         StreamGraph streamGraph = jobVertexBuildContext.getStreamGraph();
1883:         final Map<JobVertexID, SlotSharingGroup> vertexRegionSlotSharingGroups = new HashMap<>();
1884:         final SlotSharingGroup defaultSlotSharingGroup = new SlotSharingGroup();
1885:         streamGraph
1886:                 .getSlotSharingGroupResource(StreamGraphGenerator.DEFAULT_SLOT_SHARING_GROUP)
1887:                 .ifPresent(defaultSlotSharingGroup::setResourceProfile);
1888: 
1889:         final boolean allRegionsInSameSlotSharingGroup =
1890:                 streamGraph.isAllVerticesInSameSlotSharingGroupByDefault();
1891: 
1892:         final Iterable<DefaultLogicalPipelinedRegion> regions =
