1914:     private static void setCoLocation(JobVertexBuildContext jobVertexBuildContext) {
1915:         final Map<String, Tuple2<SlotSharingGroup, CoLocationGroupImpl>> coLocationGroups =
1916:                 new HashMap<>();
1917:         final Map<Integer, JobVertex> jobVertices = jobVertexBuildContext.getJobVerticesInOrder();
1918:         final StreamGraph streamGraph = jobVertexBuildContext.getStreamGraph();
1919: 
1920:         for (Map.Entry<Integer, JobVertex> entry : jobVertices.entrySet()) {
1921: 
1922:             final StreamNode node = streamGraph.getStreamNode(entry.getKey());
1923:             final JobVertex vertex = entry.getValue();
1924:             final SlotSharingGroup sharingGroup = vertex.getSlotSharingGroup();
1925: 
1926:             // configure co-location constraint
1927:             final String coLocationGroupKey = node.getCoLocationGroup();
1928:             if (coLocationGroupKey != null) {
1929:                 if (sharingGroup == null) {
1930:                     throw new IllegalStateException(
1931:                             "Cannot use a co-location constraint without a slot sharing group");
1932:                 }
1933: 
1934:                 Tuple2<SlotSharingGroup, CoLocationGroupImpl> constraint =
1935:                         coLocationGroups.computeIfAbsent(
1936:                                 coLocationGroupKey,
1937:                                 k -> new Tuple2<>(sharingGroup, new CoLocationGroupImpl()));
1938: 
1939:                 if (constraint.f0 != sharingGroup) {
1940:                     throw new IllegalStateException(
1941:                             "Cannot co-locate operators from different slot sharing groups");
1942:                 }
1943: 
1944:                 vertex.updateCoLocationGroup(constraint.f1);
1945:                 constraint.f1.addVertex(vertex);
1946:             }
1947:         }
