1950:     public static void setManagedMemoryFraction(JobVertexBuildContext jobVertexBuildContext) {
1951: 
1952:         final Map<Integer, JobVertex> jobVertices = jobVertexBuildContext.getJobVerticesInOrder();
1953: 
1954:         // all slot sharing groups in this job
1955:         final Set<SlotSharingGroup> slotSharingGroups =
1956:                 Collections.newSetFromMap(new IdentityHashMap<>());
1957: 
1958:         // maps a job vertex ID to its head operator ID
1959:         final Map<JobVertexID, Integer> vertexHeadOperators = new HashMap<>();
1960: 
1961:         // maps a job vertex ID to IDs of all operators in the vertex
1962:         final Map<JobVertexID, Set<Integer>> vertexOperators = new HashMap<>();
1963: 
1964:         for (Map.Entry<Integer, JobVertex> entry : jobVertices.entrySet()) {
1965:             final int headOperatorId = entry.getKey();
1966:             final JobVertex jobVertex = entry.getValue();
1967: 
1968:             final SlotSharingGroup jobVertexSlotSharingGroup = jobVertex.getSlotSharingGroup();
1969: 
1970:             checkState(
1971:                     jobVertexSlotSharingGroup != null,
1972:                     "JobVertex slot sharing group must not be null");
1973:             slotSharingGroups.add(jobVertexSlotSharingGroup);
1974: 
1975:             vertexHeadOperators.put(jobVertex.getID(), headOperatorId);
1976: 
1977:             final Set<Integer> operatorIds = new HashSet<>();
1978:             operatorIds.add(headOperatorId);
1979:             operatorIds.addAll(
1980:                     jobVertexBuildContext
1981:                             .getChainedConfigs()
1982:                             .getOrDefault(headOperatorId, Collections.emptyMap())
1983:                             .keySet());
1984:             vertexOperators.put(jobVertex.getID(), operatorIds);
1985:         }
1986: 
1987:         for (SlotSharingGroup slotSharingGroup : slotSharingGroups) {
1988:             setManagedMemoryFractionForSlotSharingGroup(
1989:                     slotSharingGroup, vertexHeadOperators, vertexOperators, jobVertexBuildContext);
1990:         }
1991:     }
