1993:     private static void setManagedMemoryFractionForSlotSharingGroup(
1994:             final SlotSharingGroup slotSharingGroup,
1995:             final Map<JobVertexID, Integer> vertexHeadOperators,
1996:             final Map<JobVertexID, Set<Integer>> vertexOperators,
1997:             final JobVertexBuildContext jobVertexBuildContext) {
1998:         final StreamGraph streamGraph = jobVertexBuildContext.getStreamGraph();
1999:         final Map<Integer, Map<Integer, StreamConfig>> vertexChainedConfigs =
2000:                 jobVertexBuildContext.getChainedConfigs();
2001:         final Set<Integer> groupOperatorIds =
2002:                 slotSharingGroup.getJobVertexIds().stream()
2003:                         .flatMap((vid) -> vertexOperators.get(vid).stream())
2004:                         .collect(Collectors.toSet());
2005: 
2006:         final Map<ManagedMemoryUseCase, Integer> groupOperatorScopeUseCaseWeights =
2007:                 groupOperatorIds.stream()
2008:                         .flatMap(
2009:                                 (oid) ->
2010:                                         streamGraph.getStreamNode(oid)
2011:                                                 .getManagedMemoryOperatorScopeUseCaseWeights()
2012:                                                 .entrySet().stream())
2013:                         .collect(
2014:                                 Collectors.groupingBy(
2015:                                         Map.Entry::getKey,
2016:                                         Collectors.summingInt(Map.Entry::getValue)));
2017: 
2018:         final Set<ManagedMemoryUseCase> groupSlotScopeUseCases =
2019:                 groupOperatorIds.stream()
2020:                         .flatMap(
2021:                                 (oid) ->
2022:                                         streamGraph.getStreamNode(oid)
2023:                                                 .getManagedMemorySlotScopeUseCases().stream())
2024:                         .collect(Collectors.toSet());
2025: 
2026:         for (JobVertexID jobVertexID : slotSharingGroup.getJobVertexIds()) {
2027:             for (int operatorNodeId : vertexOperators.get(jobVertexID)) {
2028:                 final StreamConfig operatorConfig =
2029:                         jobVertexBuildContext.getOperatorInfo(operatorNodeId).getVertexConfig();
2030:                 final Map<ManagedMemoryUseCase, Integer> operatorScopeUseCaseWeights =
2031:                         streamGraph
2032:                                 .getStreamNode(operatorNodeId)
2033:                                 .getManagedMemoryOperatorScopeUseCaseWeights();
2034:                 final Set<ManagedMemoryUseCase> slotScopeUseCases =
2035:                         streamGraph
2036:                                 .getStreamNode(operatorNodeId)
2037:                                 .getManagedMemorySlotScopeUseCases();
2038:                 setManagedMemoryFractionForOperator(
2039:                         operatorScopeUseCaseWeights,
2040:                         slotScopeUseCases,
2041:                         groupOperatorScopeUseCaseWeights,
2042:                         groupSlotScopeUseCases,
2043:                         operatorConfig);
2044:             }
2045: 
2046:             // need to refresh the chained task configs because they are serialized
2047:             final int headOperatorNodeId = vertexHeadOperators.get(jobVertexID);
2048:             final StreamConfig vertexConfig =
2049:                     jobVertexBuildContext.getOperatorInfo(headOperatorNodeId).getVertexConfig();
2050:             vertexConfig.setTransitiveChainedTaskConfigs(
2051:                     vertexChainedConfigs.get(headOperatorNodeId));
2052:         }
2053:     }
