2055:     private static void setManagedMemoryFractionForOperator(
2056:             final Map<ManagedMemoryUseCase, Integer> operatorScopeUseCaseWeights,
2057:             final Set<ManagedMemoryUseCase> slotScopeUseCases,
2058:             final Map<ManagedMemoryUseCase, Integer> groupManagedMemoryWeights,
2059:             final Set<ManagedMemoryUseCase> groupSlotScopeUseCases,
2060:             final StreamConfig operatorConfig) {
2061: 
2062:         // For each operator, make sure fractions are set for all use cases in the group, even if
2063:         // the operator does not have the use case (set the fraction to 0.0). This allows us to
2064:         // learn which use cases exist in the group from either one of the stream configs.
2065:         for (Map.Entry<ManagedMemoryUseCase, Integer> entry :
2066:                 groupManagedMemoryWeights.entrySet()) {
2067:             final ManagedMemoryUseCase useCase = entry.getKey();
2068:             final int groupWeight = entry.getValue();
2069:             final int operatorWeight = operatorScopeUseCaseWeights.getOrDefault(useCase, 0);
2070:             operatorConfig.setManagedMemoryFractionOperatorOfUseCase(
2071:                     useCase,
2072:                     operatorWeight > 0
2073:                             ? ManagedMemoryUtils.getFractionRoundedDown(operatorWeight, groupWeight)
2074:                             : 0.0);
2075:         }
2076:         for (ManagedMemoryUseCase useCase : groupSlotScopeUseCases) {
2077:             operatorConfig.setManagedMemoryFractionOperatorOfUseCase(
2078:                     useCase, slotScopeUseCases.contains(useCase) ? 1.0 : 0.0);
2079:         }
2080:     }
