2082:     public static void configureCheckpointing(StreamGraph streamGraph, JobGraph jobGraph) {
2083:         CheckpointConfig cfg = streamGraph.getCheckpointConfig();
2084: 
2085:         long interval = cfg.getCheckpointInterval();
2086:         if (interval < MINIMAL_CHECKPOINT_TIME) {
2087:             interval = CheckpointCoordinatorConfiguration.DISABLED_CHECKPOINT_INTERVAL;
2088:         }
2089: 
2090:         //  --- configure options ---
2091: 
2092:         CheckpointRetentionPolicy retentionAfterTermination;
2093:         if (cfg.isExternalizedCheckpointsEnabled()) {
2094:             ExternalizedCheckpointRetention cleanup = cfg.getExternalizedCheckpointRetention();
2095:             // Sanity check
2096:             if (cleanup == null) {
2097:                 throw new IllegalStateException(
2098:                         "Externalized checkpoints enabled, but no cleanup mode configured.");
2099:             }
2100:             retentionAfterTermination =
2101:                     cleanup.deleteOnCancellation()
2102:                             ? CheckpointRetentionPolicy.RETAIN_ON_FAILURE
2103:                             : CheckpointRetentionPolicy.RETAIN_ON_CANCELLATION;
2104:         } else {
2105:             retentionAfterTermination = CheckpointRetentionPolicy.NEVER_RETAIN_AFTER_TERMINATION;
2106:         }
2107: 
2108:         //  --- configure the master-side checkpoint hooks ---
2109: 
2110:         final ArrayList<MasterTriggerRestoreHook.Factory> hooks = new ArrayList<>();
2111: 
2112:         for (StreamNode node : streamGraph.getStreamNodes()) {
2113:             if (node.getOperatorFactory() != null
2114:                     && node.getOperatorFactory() instanceof UdfStreamOperatorFactory) {
2115:                 Function f =
2116:                         ((UdfStreamOperatorFactory) node.getOperatorFactory()).getUserFunction();
2117: 
2118:                 if (f instanceof WithMasterCheckpointHook) {
2119:                     hooks.add(
2120:                             new FunctionMasterCheckpointHookFactory(
2121:                                     (WithMasterCheckpointHook<?>) f));
2122:                 }
2123:             }
2124:         }
2125: 
2126:         // because the hooks can have user-defined code, they need to be stored as
2127:         // eagerly serialized values
2128:         final SerializedValue<MasterTriggerRestoreHook.Factory[]> serializedHooks;
2129:         if (hooks.isEmpty()) {
2130:             serializedHooks = null;
2131:         } else {
2132:             try {
2133:                 MasterTriggerRestoreHook.Factory[] asArray =
2134:                         hooks.toArray(new MasterTriggerRestoreHook.Factory[hooks.size()]);
2135:                 serializedHooks = new SerializedValue<>(asArray);
2136:             } catch (IOException e) {
2137:                 throw new FlinkRuntimeException("Trigger/restore hook is not serializable", e);
2138:             }
2139:         }
2140: 
2141:         // because the state backend can have user-defined code, it needs to be stored as
2142:         // eagerly serialized value
2143:         final SerializedValue<StateBackend> serializedStateBackend;
2144:         if (streamGraph.getStateBackend() == null) {
2145:             serializedStateBackend = null;
2146:         } else {
2147:             try {
2148:                 serializedStateBackend =
2149:                         new SerializedValue<StateBackend>(streamGraph.getStateBackend());
2150:             } catch (IOException e) {
2151:                 throw new FlinkRuntimeException("State backend is not serializable", e);
2152:             }
2153:         }
2154: 
2155:         // because the checkpoint storage can have user-defined code, it needs to be stored as
2156:         // eagerly serialized value
2157:         final SerializedValue<CheckpointStorage> serializedCheckpointStorage;
2158:         if (streamGraph.getCheckpointStorage() == null) {
2159:             serializedCheckpointStorage = null;
2160:         } else {
2161:             try {
2162:                 serializedCheckpointStorage =
2163:                         new SerializedValue<>(streamGraph.getCheckpointStorage());
2164:             } catch (IOException e) {
2165:                 throw new FlinkRuntimeException("Checkpoint storage is not serializable", e);
2166:             }
2167:         }
2168: 
2169:         //  --- done, put it all together ---
2170: 
2171:         JobCheckpointingSettings settings =
2172:                 new JobCheckpointingSettings(
2173:                         CheckpointCoordinatorConfiguration.builder()
2174:                                 .setCheckpointInterval(interval)
2175:                                 .setCheckpointIntervalDuringBacklog(
2176:                                         cfg.getCheckpointIntervalDuringBacklog())
2177:                                 .setCheckpointTimeout(cfg.getCheckpointTimeout())
2178:                                 .setMinPauseBetweenCheckpoints(cfg.getMinPauseBetweenCheckpoints())
2179:                                 .setMaxConcurrentCheckpoints(cfg.getMaxConcurrentCheckpoints())
2180:                                 .setCheckpointRetentionPolicy(retentionAfterTermination)
2181:                                 .setExactlyOnce(
2182:                                         getCheckpointingMode(cfg) == CheckpointingMode.EXACTLY_ONCE)
2183:                                 .setTolerableCheckpointFailureNumber(
2184:                                         cfg.getTolerableCheckpointFailureNumber())
2185:                                 .setUnalignedCheckpointsEnabled(cfg.isUnalignedCheckpointsEnabled())
2186:                                 .setCheckpointIdOfIgnoredInFlightData(
2187:                                         cfg.getCheckpointIdOfIgnoredInFlightData())
2188:                                 .setAlignedCheckpointTimeout(
2189:                                         cfg.getAlignedCheckpointTimeout().toMillis())
2190:                                 .setEnableCheckpointsAfterTasksFinish(
2191:                                         streamGraph.isEnableCheckpointsAfterTasksFinish())
2192:                                 .build(),
2193:                         serializedStateBackend,
2194:                         streamGraph
2195:                                 .getJobConfiguration()
2196:                                 .getOptional(StateChangelogOptions.ENABLE_STATE_CHANGE_LOG)
2197:                                 .map(TernaryBoolean::fromBoolean)
2198:                                 .orElse(TernaryBoolean.UNDEFINED),
2199:                         serializedCheckpointStorage,
2200:                         serializedHooks);
2201: 
2202:         jobGraph.setSnapshotSettings(settings);
