513:     /**
514:      * Adds a new virtual node that is used to connect a downstream vertex to only the outputs with
515:      * the selected side-output {@link OutputTag}.
516:      *
517:      * @param originalId ID of the node that should be connected to.
518:      * @param virtualId ID of the virtual node.
519:      * @param outputTag The selected side-output {@code OutputTag}.
520:      */
521:     public void addVirtualSideOutputNode(
522:             Integer originalId, Integer virtualId, OutputTag outputTag) {
523: 
524:         if (virtualSideOutputNodes.containsKey(virtualId)) {
525:             throw new IllegalStateException("Already has virtual output node with id " + virtualId);
526:         }
527: 
528:         // verify that we don't already have a virtual node for the given originalId/outputTag
529:         // combination with a different TypeInformation. This would indicate that someone is trying
530:         // to read a side output from an operation with a different type for the same side output
531:         // id.
532: 
533:         for (Tuple2<Integer, OutputTag> tag : virtualSideOutputNodes.values()) {
534:             if (!tag.f0.equals(originalId)) {
535:                 // different source operator
536:                 continue;
537:             }
538: 
539:             if (tag.f1.getId().equals(outputTag.getId())
540:                     && !tag.f1.getTypeInfo().equals(outputTag.getTypeInfo())) {
541:                 throw new IllegalArgumentException(
542:                         "Trying to add a side output for the same "
543:                                 + "side-output id with a different type. This is not allowed. Side-output ID: "
544:                                 + tag.f1.getId());
545:             }
546:         }
547: 
548:         virtualSideOutputNodes.put(virtualId, new Tuple2<>(originalId, outputTag));
549:     }
550: 
551:     /**
552:      * Adds a new virtual node that is used to connect a downstream vertex to an input with a
553:      * certain partitioning.
554:      *
555:      * <p>When adding an edge from the virtual node to a downstream node the connection will be made
556:      * to the original node, but with the partitioning given here.
557:      *
558:      * @param originalId ID of the node that should be connected to.
559:      * @param virtualId ID of the virtual node.
560:      * @param partitioner The partitioner
561:      */
562:     public void addVirtualPartitionNode(
563:             Integer originalId,
564:             Integer virtualId,
565:             StreamPartitioner<?> partitioner,
566:             StreamExchangeMode exchangeMode) {
567: 
568:         if (virtualPartitionNodes.containsKey(virtualId)) {
569:             throw new IllegalStateException(
570:                     "Already has virtual partition node with id " + virtualId);
571:         }
572: 
573:         virtualPartitionNodes.put(virtualId, new Tuple3<>(originalId, partitioner, exchangeMode));
574:     }
