576:     /** Determines the slot sharing group of an operation across virtual nodes. */
577:     public String getSlotSharingGroup(Integer id) {
578:         if (virtualSideOutputNodes.containsKey(id)) {
579:             Integer mappedId = virtualSideOutputNodes.get(id).f0;
580:             return getSlotSharingGroup(mappedId);
581:         } else if (virtualPartitionNodes.containsKey(id)) {
582:             Integer mappedId = virtualPartitionNodes.get(id).f0;
583:             return getSlotSharingGroup(mappedId);
584:         } else {
585:             StreamNode node = getStreamNode(id);
586:             return node.getSlotSharingGroup();
587:         }
588:     }
