610:     private void addEdgeInternal(
611:             Integer upStreamVertexID,
612:             Integer downStreamVertexID,
613:             int typeNumber,
614:             StreamPartitioner<?> partitioner,
615:             List<String> outputNames,
616:             OutputTag outputTag,
617:             StreamExchangeMode exchangeMode,
618:             IntermediateDataSetID intermediateDataSetId) {
619: 
620:         if (virtualSideOutputNodes.containsKey(upStreamVertexID)) {
621:             int virtualId = upStreamVertexID;
622:             upStreamVertexID = virtualSideOutputNodes.get(virtualId).f0;
623:             if (outputTag == null) {
624:                 outputTag = virtualSideOutputNodes.get(virtualId).f1;
625:             }
626:             addEdgeInternal(
627:                     upStreamVertexID,
628:                     downStreamVertexID,
629:                     typeNumber,
630:                     partitioner,
631:                     null,
632:                     outputTag,
633:                     exchangeMode,
634:                     intermediateDataSetId);
635:         } else if (virtualPartitionNodes.containsKey(upStreamVertexID)) {
636:             int virtualId = upStreamVertexID;
637:             upStreamVertexID = virtualPartitionNodes.get(virtualId).f0;
638:             if (partitioner == null) {
639:                 partitioner = virtualPartitionNodes.get(virtualId).f1;
640:             }
641:             exchangeMode = virtualPartitionNodes.get(virtualId).f2;
642:             addEdgeInternal(
643:                     upStreamVertexID,
644:                     downStreamVertexID,
645:                     typeNumber,
646:                     partitioner,
647:                     outputNames,
648:                     outputTag,
649:                     exchangeMode,
650:                     intermediateDataSetId);
651:         } else {
652:             createActualEdge(
653:                     upStreamVertexID,
654:                     downStreamVertexID,
655:                     typeNumber,
656:                     partitioner,
657:                     outputTag,
658:                     exchangeMode,
659:                     intermediateDataSetId);
660:         }
661:     }
662: 
663:     private void createActualEdge(
664:             Integer upStreamVertexID,
665:             Integer downStreamVertexID,
666:             int typeNumber,
667:             StreamPartitioner<?> partitioner,
668:             OutputTag outputTag,
669:             StreamExchangeMode exchangeMode,
670:             IntermediateDataSetID intermediateDataSetId) {
671:         StreamNode upstreamNode = getStreamNode(upStreamVertexID);
672:         StreamNode downstreamNode = getStreamNode(downStreamVertexID);
673: 
674:         // If no partitioner was specified and the parallelism of upstream and downstream
675:         // operator matches use forward partitioning, use rebalance otherwise.
676:         if (partitioner == null
677:                 && upstreamNode.getParallelism() == downstreamNode.getParallelism()) {
678:             partitioner =
679:                     dynamic ? new ForwardForUnspecifiedPartitioner<>() : new ForwardPartitioner<>();
680:         } else if (partitioner == null) {
681:             partitioner = new RebalancePartitioner<Object>();
682:         }
683: 
684:         if (partitioner instanceof ForwardPartitioner) {
685:             if (upstreamNode.getParallelism() != downstreamNode.getParallelism()) {
686:                 if (partitioner instanceof ForwardForConsecutiveHashPartitioner) {
687:                     partitioner =
688:                             ((ForwardForConsecutiveHashPartitioner<?>) partitioner)
689:                                     .getHashPartitioner();
690:                 } else {
691:                     throw new UnsupportedOperationException(
692:                             "Forward partitioning does not allow "
693:                                     + "change of parallelism. Upstream operation: "
694:                                     + upstreamNode
695:                                     + " parallelism: "
696:                                     + upstreamNode.getParallelism()
697:                                     + ", downstream operation: "
698:                                     + downstreamNode
699:                                     + " parallelism: "
700:                                     + downstreamNode.getParallelism()
701:                                     + " You must use another partitioning strategy, such as broadcast, rebalance, shuffle or global.");
702:                 }
703:             }
704:         }
705: 
706:         if (exchangeMode == null) {
707:             exchangeMode = StreamExchangeMode.UNDEFINED;
708:         }
709: 
710:         /**
711:          * Just make sure that {@link StreamEdge} connecting same nodes (for example as a result of
712:          * self unioning a {@link DataStream}) are distinct and unique. Otherwise it would be
713:          * difficult on the {@link StreamTask} to assign {@link RecordWriter}s to correct {@link
714:          * StreamEdge}.
715:          */
716:         int uniqueId = getStreamEdges(upstreamNode.getId(), downstreamNode.getId()).size();
717: 
718:         StreamEdge edge =
719:                 new StreamEdge(
720:                         upstreamNode,
721:                         downstreamNode,
722:                         typeNumber,
723:                         partitioner,
724:                         outputTag,
725:                         exchangeMode,
726:                         uniqueId,
727:                         intermediateDataSetId);
728: 
729:         getStreamNode(edge.getSourceId()).addOutEdge(edge);
730:         getStreamNode(edge.getTargetId()).addInEdge(edge);
731:     }
