+        this.keyGroupRange = keyGroupRange;
+        this.optionsContainer = optionsContainer;
+        this.forstBasePath = forstBasePath;
+        this.keySerializerProvider = keySerializerProvider;
+        this.userCodeClassLoader = userCodeClassLoader;
+    }
