+                "Restored previous incremental files status in backend with range {} in operator {}: backend uuid {}, last checkpoint id {}.",
+                keyGroupRange.prettyPrintInterval(),
+                operatorIdentifier,
+                backendUID,
+                lastCompletedCheckpointId);
+    }
