+        try {
+            inputStream = metaStateHandle.openInputStream();
+            cancelStreamRegistry.registerCloseable(inputStream);
+            DataInputView in = new DataInputViewStreamWrapper(inputStream);
+            return readMetaData(in);
+        } finally {
