426:     /**
427:      * Sets the maximum time frequency (milliseconds) for the flushing of the output buffers. By
428:      * default the output buffers flush frequently to provide low latency and to aid smooth
429:      * developer experience. Setting the parameter can result in three logical modes:
430:      *
431:      * <ul>
432:      *   <li>A positive integer triggers flushing periodically by that integer
433:      *   <li>0 triggers flushing after every record thus minimizing latency
434:      *   <li>-1 triggers flushing only when the output buffer is full thus maximizing throughput
435:      * </ul>
436:      *
437:      * @param timeoutMillis The maximum time between two output flushes.
438:      */
439:     public StreamExecutionEnvironment setBufferTimeout(long timeoutMillis) {
440:         if (timeoutMillis < ExecutionOptions.DISABLED_NETWORK_BUFFER_TIMEOUT) {
441:             throw new IllegalArgumentException("Timeout of buffer must be non-negative or -1");
442:         }
443: 
444:         if (timeoutMillis == ExecutionOptions.DISABLED_NETWORK_BUFFER_TIMEOUT) {
445:             this.configuration.set(ExecutionOptions.BUFFER_TIMEOUT_ENABLED, false);
446:         } else {
447:             this.configuration.set(
448:                     ExecutionOptions.BUFFER_TIMEOUT, Duration.ofMillis(timeoutMillis));
449:         }
450:         return this;
451:     }
