372:      *     only SynchronizedActionExecutor can be used to preserve locking semantics.
373:      */
374:     protected StreamTask(
375:             Environment environment,
376:             @Nullable TimerService timerService,
377:             Thread.UncaughtExceptionHandler uncaughtExceptionHandler,
378:             StreamTaskActionExecutor actionExecutor)
379:             throws Exception {
380:         this(
381:                 environment,
382:                 timerService,
383:                 uncaughtExceptionHandler,
384:                 actionExecutor,
385:                 new TaskMailboxImpl(Thread.currentThread()));
