559:     private CheckpointStorageAccess tryApplyFileMergingCheckpoint(
560:             CheckpointStorageAccess checkpointStorageAccess,
561:             @Nullable FileMergingSnapshotManager fileMergingSnapshotManager) {
562:         if (fileMergingSnapshotManager == null) {
563:             return checkpointStorageAccess;
564:         }
565:         try {
566:             CheckpointStorageAccess mergingCheckpointStorageAccess =
567:                     (CheckpointStorageAccess)
568:                             checkpointStorageAccess.toFileMergingStorage(
569:                                     fileMergingSnapshotManager, environment);
570:             mergingCheckpointStorageAccess.initializeBaseLocationsForCheckpoint();
571:             if (mergingCheckpointStorageAccess instanceof FsMergingCheckpointStorageAccess) {
572:                 resourceCloser.registerCloseable(
573:                         () ->
574:                                 ((FsMergingCheckpointStorageAccess) mergingCheckpointStorageAccess)
575:                                         .close());
576:             }
577:             return mergingCheckpointStorageAccess;
578:         } catch (IOException e) {
579:             LOG.warn(
580:                     "Initiating FsMergingCheckpointStorageAccess failed "
581:                             + "with exception: {}, falling back to original checkpoint storage access {}.",
582:                     e.getMessage(),
583:                     checkpointStorageAccess.getClass(),
584:                     e);
585:             return checkpointStorageAccess;
586:         }
587:     }
