902:     @Override
903:     public final void invoke() throws Exception {
904:         // Allow invoking method 'invoke' without having to call 'restore' before it.
905:         if (!isRunning) {
906:             LOG.debug("Restoring during invoke will be called.");
907:             restoreInternal();
908:         }
909: 
910:         // final check to exit early before starting to run
911:         ensureNotCanceled();
912: 
913:         scheduleBufferDebloater();
914: 
915:         // let the task do its work
916:         getEnvironment().getMetricGroup().getIOMetricGroup().markTaskStart();
917:         runMailboxLoop();
918: 
919:         // if this left the run() method cleanly despite the fact that this was canceled,
920:         // make sure the "clean shutdown" is not attempted
921:         ensureNotCanceled();
922: 
923:         afterInvoke();
924:     }
