976:     protected void afterInvoke() throws Exception {
977:         LOG.debug("Finished task {}", getName());
978:         getCompletionFuture().exceptionally(unused -> null).join();
979: 
980:         Set<CompletableFuture<Void>> terminationConditions = new HashSet<>();
981:         // If checkpoints are enabled, waits for all the records get processed by the downstream
982:         // tasks. During this process, this task could coordinate with its downstream tasks to
983:         // continue perform checkpoints.
984:         if (endOfDataReceived && areCheckpointsWithFinishedTasksEnabled()) {
985:             LOG.debug("Waiting for all the records processed by the downstream tasks.");
986: 
987:             for (ResultPartitionWriter partitionWriter : getEnvironment().getAllWriters()) {
988:                 terminationConditions.add(partitionWriter.getAllDataProcessedFuture());
989:             }
990: 
991:             terminationConditions.add(finalCheckpointCompleted);
992:         }
993: 
994:         if (syncSavepoint != null) {
995:             terminationConditions.add(finalCheckpointCompleted);
996:         }
997: 
998:         FutureUtils.waitForAll(terminationConditions)
999:                 .thenRun(mailboxProcessor::allActionsCompleted);
1000: 
1001:         // Resumes the mailbox processor. The mailbox processor would be completed
1002:         // after all records are processed by the downstream tasks.
1003:         mailboxProcessor.runMailboxLoop();
1004: 
1005:         // make sure no further checkpoint and notification actions happen.
1006:         // at the same time, this makes sure that during any "regular" exit where still
1007:         actionExecutor.runThrowing(
1008:                 () -> {
1009:                     // make sure no new timers can come
1010:                     timerService.quiesce().get();
1011:                     systemTimerService.quiesce().get();
1012: 
1013:                     // let mailbox execution reject all new letters from this point
1014:                     mailboxProcessor.prepareClose();
1015:                 });
1016: 
1017:         // processes the remaining mails; no new mails can be enqueued
1018:         mailboxProcessor.drain();
1019: 
1020:         // Set isRunning to false after all the mails are drained so that
1021:         // the queued checkpoint requirements could be triggered normally.
1022:         actionExecutor.runThrowing(
1023:                 () -> {
1024:                     // only set the StreamTask to not running after all operators have been
1025:                     // finished!
1026:                     // See FLINK-7430
1027:                     isRunning = false;
1028:                 });
1029: 
1030:         LOG.debug("Finished operators for task {}", getName());
1031: 
1032:         // make sure all buffered data is flushed
1033:         operatorChain.flushOutputs();
1034: 
1035:         if (areCheckpointsWithFinishedTasksEnabled()) {
1036:             // No new checkpoints could be triggered since mailbox has been drained.
1037:             subtaskCheckpointCoordinator.waitForPendingCheckpoints();
1038:             LOG.debug("All pending checkpoints are finished");
1039:         }
1040: 
1041:         disableInterruptOnCancel();
1042: 
1043:         // make an attempt to dispose the operators such that failures in the dispose call
1044:         // still let the computation fail
1045:         closeAllOperators();
1046:     }
