1055:     @Override
1056:     public final void cleanUp(Throwable throwable) throws Exception {
1057:         LOG.debug(
1058:                 "Cleanup StreamTask (operators closed: {}, cancelled: {})",
1059:                 closedOperators,
1060:                 canceled);
1061: 
1062:         failing = !canceled && throwable != null;
1063: 
1064:         Exception cancelException = null;
1065:         if (throwable != null) {
1066:             try {
1067:                 cancelTask();
1068:             } catch (Throwable t) {
1069:                 cancelException = t instanceof Exception ? (Exception) t : new Exception(t);
1070:             }
1071:         }
1072: 
1073:         disableInterruptOnCancel();
1074: 
1075:         // note: This `.join()` is already uninterruptible, so it doesn't matter if we have already
1076:         // disabled the interruptions or not.
1077:         getCompletionFuture().exceptionally(unused -> null).join();
1078:         // clean up everything we initialized
1079:         isRunning = false;
1080: 
1081:         // clear any previously issued interrupt for a more graceful shutdown
1082:         Thread.interrupted();
1083: 
1084:         try {
1085:             resourceCloser.close();
1086:         } catch (Throwable t) {
1087:             Exception e = t instanceof Exception ? (Exception) t : new Exception(t);
1088:             throw firstOrSuppressed(e, cancelException);
1089:         }
1090:     }
