1102:     @Override
1103:     public final void cancel() throws Exception {
1104:         isRunning = false;
1105:         canceled = true;
1106: 
1107:         FlinkSecurityManager.monitorUserSystemExitForCurrentThread();
1108:         // the "cancel task" call must come first, but the cancelables must be
1109:         // closed no matter what
1110:         try {
1111:             cancelTask();
1112:         } finally {
1113:             FlinkSecurityManager.unmonitorUserSystemExitForCurrentThread();
1114:             getCompletionFuture()
1115:                     .whenComplete(
1116:                             (unusedResult, unusedError) -> {
1117:                                 // WARN: the method is called from the task thread but the callback
1118:                                 // can be invoked from a different thread
1119:                                 mailboxProcessor.allActionsCompleted();
1120:                                 try {
1121:                                     subtaskCheckpointCoordinator.cancel();
1122:                                     cancelables.close();
1123:                                 } catch (IOException e) {
1124:                                     throw new CompletionException(e);
1125:                                 }
1126:                             });
1127:         }
1128:     }
