1380:         FlinkSecurityManager.monitorUserSystemExitForCurrentThread();
1381:         try {
1382:             performCheckpoint(checkpointMetaData, checkpointOptions, checkpointMetrics);
1383:         } catch (CancelTaskException e) {
1384:             LOG.info(
1385:                     "Operator {} was cancelled while performing checkpoint {}.",
1386:                     getName(),
1387:                     checkpointMetaData.getCheckpointId());
1388:             throw e;
1389:         } catch (Exception e) {
1390:             throw new IOException(
1391:                     "Could not perform checkpoint "
1392:                             + checkpointMetaData.getCheckpointId()
1393:                             + " for operator "
1394:                             + getName()
1395:                             + '.',
1396:                     e);
1397:         } finally {
