1721:     @VisibleForTesting
1722:     public static <OUT>
1723:             RecordWriterDelegate<SerializationDelegate<StreamRecord<OUT>>>
1724:                     createRecordWriterDelegate(
1725:                             StreamConfig configuration, Environment environment) {
1726:         List<RecordWriter<SerializationDelegate<StreamRecord<OUT>>>> recordWrites =
1727:                 createRecordWriters(configuration, environment);
1728:         if (recordWrites.size() == 1) {
1729:             return new SingleRecordWriter<>(recordWrites.get(0));
1730:         } else if (recordWrites.size() == 0) {
1731:             return new NonRecordWriter<>();
1732:         } else {
1733:             return new MultipleRecordWriters<>(recordWrites);
1734:         }
1735:     }
1736: 
1737:     private static <OUT>
1738:             List<RecordWriter<SerializationDelegate<StreamRecord<OUT>>>> createRecordWriters(
1739:                     StreamConfig configuration, Environment environment) {
1740:         List<RecordWriter<SerializationDelegate<StreamRecord<OUT>>>> recordWriters =
1741:                 new ArrayList<>();
1742:         List<NonChainedOutput> outputsInOrder =
1743:                 configuration.getVertexNonChainedOutputs(
1744:                         environment.getUserCodeClassLoader().asClassLoader());
1745: 
1746:         int index = 0;
1747:         for (NonChainedOutput streamOutput : outputsInOrder) {
1748:             replaceForwardPartitionerIfConsumerParallelismDoesNotMatch(
1749:                     environment, streamOutput, index);
1750:             recordWriters.add(
1751:                     createRecordWriter(
1752:                             streamOutput,
1753:                             index++,
1754:                             environment,
1755:                             environment.getTaskInfo().getTaskNameWithSubtasks(),
1756:                             streamOutput.getBufferTimeout()));
1757:         }
1758:         return recordWriters;
1759:     }
1760: 
1761:     private static void replaceForwardPartitionerIfConsumerParallelismDoesNotMatch(
1762:             Environment environment, NonChainedOutput streamOutput, int outputIndex) {
1763:         if (streamOutput.getPartitioner() instanceof ForwardPartitioner
1764:                 && environment.getWriter(outputIndex).getNumberOfSubpartitions()
1765:                         != environment.getTaskInfo().getNumberOfParallelSubtasks()) {
1766:             LOG.debug(
1767:                     "Replacing forward partitioner with rebalance for {}",
1768:                     environment.getTaskInfo().getTaskNameWithSubtasks());
1769:             streamOutput.setPartitioner(new RebalancePartitioner<>());
1770:         }
1771:     }
1772: 
1773:     @SuppressWarnings("unchecked")
1774:     private static <OUT> RecordWriter<SerializationDelegate<StreamRecord<OUT>>> createRecordWriter(
1775:             NonChainedOutput streamOutput,
1776:             int outputIndex,
1777:             Environment environment,
1778:             String taskNameWithSubtask,
1779:             long bufferTimeout) {
1780: 
1781:         StreamPartitioner<OUT> outputPartitioner = null;
1782: 
1783:         // Clones the partition to avoid multiple stream edges sharing the same stream partitioner,
1784:         // like the case of https://issues.apache.org/jira/browse/FLINK-14087.
1785:         try {
1786:             outputPartitioner =
1787:                     InstantiationUtil.clone(
1788:                             (StreamPartitioner<OUT>) streamOutput.getPartitioner(),
1789:                             environment.getUserCodeClassLoader().asClassLoader());
1790:         } catch (Exception e) {
1791:             ExceptionUtils.rethrow(e);
1792:         }
1793: 
1794:         LOG.debug(
1795:                 "Using partitioner {} for output {} of task {}",
1796:                 outputPartitioner,
1797:                 outputIndex,
1798:                 taskNameWithSubtask);
1799: 
1800:         ResultPartitionWriter bufferWriter = environment.getWriter(outputIndex);
1801: 
1802:         // we initialize the partitioner here with the number of key groups (aka max. parallelism)
1803:         if (outputPartitioner instanceof ConfigurableStreamPartitioner) {
1804:             int numKeyGroups = bufferWriter.getNumTargetKeyGroups();
1805:             if (0 < numKeyGroups) {
1806:                 ((ConfigurableStreamPartitioner) outputPartitioner).configure(numKeyGroups);
1807:             }
1808:         }
1809: 
1810:         RecordWriter<SerializationDelegate<StreamRecord<OUT>>> output =
1811:                 new RecordWriterBuilder<SerializationDelegate<StreamRecord<OUT>>>()
1812:                         .setChannelSelector(outputPartitioner)
1813:                         .setTimeout(bufferTimeout)
1814:                         .setTaskName(taskNameWithSubtask)
1815:                         .build(bufferWriter);
1816:         output.setMetricGroup(environment.getMetricGroup().getIOMetricGroup());
1817:         return output;
1818:     }
