127:     @VisibleForTesting
128:     public ExecutionJobVertex(
129:             InternalExecutionGraphAccessor graph,
130:             JobVertex jobVertex,
131:             VertexParallelismInformation parallelismInfo,
132:             CoordinatorStore coordinatorStore,
133:             JobManagerJobMetricGroup jobManagerJobMetricGroup)
134:             throws JobException {
135: 
136:         if (graph == null || jobVertex == null) {
137:             throw new NullPointerException();
138:         }
139: 
140:         this.graph = graph;
141:         this.jobVertex = jobVertex;
142: 
143:         this.parallelismInfo = parallelismInfo;
144: 
145:         // verify that our parallelism is not higher than the maximum parallelism
146:         if (this.parallelismInfo.getParallelism() > this.parallelismInfo.getMaxParallelism()) {
147:             throw new JobException(
148:                     String.format(
149:                             "Vertex %s's parallelism (%s) is higher than the max parallelism (%s). Please lower the parallelism or increase the max parallelism.",
150:                             jobVertex.getName(),
151:                             this.parallelismInfo.getParallelism(),
152:                             this.parallelismInfo.getMaxParallelism()));
153:         }
154: 
155:         this.resourceProfile =
156:                 ResourceProfile.fromResourceSpec(jobVertex.getMinResources(), MemorySize.ZERO);
157: 
158:         // take the sharing group
159:         this.slotSharingGroup = checkNotNull(jobVertex.getSlotSharingGroup());
160:         this.coLocationGroup = jobVertex.getCoLocationGroup();
161: 
162:         final List<SerializedValue<OperatorCoordinator.Provider>> coordinatorProviders =
163:                 getJobVertex().getOperatorCoordinators();
164:         if (coordinatorProviders.isEmpty()) {
165:             this.operatorCoordinators = Collections.emptyList();
166:         } else {
167:             final ArrayList<OperatorCoordinatorHolder> coordinators =
168:                     new ArrayList<>(coordinatorProviders.size());
169:             try {
170:                 for (final SerializedValue<OperatorCoordinator.Provider> provider :
171:                         coordinatorProviders) {
172:                     coordinators.add(
173:                             createOperatorCoordinatorHolder(
174:                                     provider,
175:                                     graph.getUserClassLoader(),
176:                                     coordinatorStore,
177:                                     jobManagerJobMetricGroup));
178:                 }
179:             } catch (Exception | LinkageError e) {
180:                 IOUtils.closeAllQuietly(coordinators);
181:                 throw new JobException(
182:                         "Cannot instantiate the coordinator for operator " + getName(), e);
183:             }
184:             this.operatorCoordinators = Collections.unmodifiableList(coordinators);
185:         }
186:     }
