145:         // verify that our parallelism is not higher than the maximum parallelism
146:         if (this.parallelismInfo.getParallelism() > this.parallelismInfo.getMaxParallelism()) {
147:             throw new JobException(
148:                     String.format(
149:                             "Vertex %s's parallelism (%s) is higher than the max parallelism (%s). Please lower the parallelism or increase the max parallelism.",
150:                             jobVertex.getName(),
151:                             this.parallelismInfo.getParallelism(),
152:                             this.parallelismInfo.getMaxParallelism()));
153:         }
154: 
155:         this.resourceProfile =
156:                 ResourceProfile.fromResourceSpec(jobVertex.getMinResources(), MemorySize.ZERO);
