167:             final ArrayList<OperatorCoordinatorHolder> coordinators =
168:                     new ArrayList<>(coordinatorProviders.size());
169:             try {
170:                 for (final SerializedValue<OperatorCoordinator.Provider> provider :
171:                         coordinatorProviders) {
172:                     coordinators.add(
