150:             Map<OperatorIDPair, OperatorState> operatorStates) {
151:         for (ExecutionJobVertex vertex : partlyFinishedVertex.values()) {
152:             if (hasUsedUnionListState(vertex, operatorStates)) {
153:                 throw new PartialFinishingNotSupportedByStateException(
154:                         String.format(
155:                                 "The vertex %s (id = %s) has used"
