169:     private void checkNoPartlyOperatorsFinishedVertexUsedUnionListState(
170:             Map<JobVertexID, ExecutionJobVertex> partlyFinishedVertex,
171:             Map<OperatorIDPair, OperatorState> operatorStates) {
172:         for (Map.Entry<ExecutionJobVertex, Integer> entry :
173:                 vertexOperatorsFinishedTasksCount.entrySet()) {
174:             ExecutionJobVertex vertex = entry.getKey();
175: 
176:             // If the vertex is partly finished, then it must not used UnionListState
177:             // due to it passed the previous check.
178:             if (partlyFinishedVertex.containsKey(vertex.getJobVertexId())) {
179:                 continue;
180:             }
181: 
182:             if (entry.getValue() != vertex.getParallelism()
183:                     && hasUsedUnionListState(vertex, operatorStates)) {
184:                 throw new PartialFinishingNotSupportedByStateException(
185:                         String.format(
186:                                 "The vertex %s (id = %s) has used"
187:                                         + " UnionListState, but part of its tasks has called operators' finish method.",
188:                                 vertex.getName(), vertex.getJobVertexId()));
189:             }
190:         }
191:     }
