193:     private boolean hasUsedUnionListState(
194:             ExecutionJobVertex vertex, Map<OperatorIDPair, OperatorState> operatorStates) {
195:         for (org.apache.flink.runtime.OperatorIDPair operatorIDPair : vertex.getOperatorIDPairs()) {
196:             OperatorState operatorState =
197:                     operatorStates.get(operatorIDPair.getGeneratedOperatorID());
198:             if (operatorState == null) {
199:                 continue;
200:             }
201: 
202:             for (OperatorSubtaskState operatorSubtaskState : operatorState.getStates()) {
203:                 boolean hasUnionListState =
204:                         Stream.concat(
205:                                         operatorSubtaskState.getManagedOperatorState().stream(),
206:                                         operatorSubtaskState.getRawOperatorState().stream())
207:                                 .filter(Objects::nonNull)
208:                                 .flatMap(
209:                                         operatorStateHandle ->
210:                                                 operatorStateHandle.getStateNameToPartitionOffsets()
211:                                                         .values().stream())
212:                                 .anyMatch(
213:                                         stateMetaInfo ->
214:                                                 stateMetaInfo.getDistributionMode()
215:                                                         == OperatorStateHandle.Mode.UNION);
216: 
217:                 if (hasUnionListState) {
218:                     return true;
219:                 }
220:             }
221:         }
222: 
223:         return false;
224:     }
225: 
226:     private void fulfillFullyFinishedOrFinishedOnRestoreOperatorStates(
227:             Map<OperatorIDPair, OperatorState> operatorStates) {
228:         // Completes the operator state for the fully finished operators
229:         for (ExecutionJobVertex jobVertex : fullyFinishedOrFinishedOnRestoreVertices.values()) {
230:             for (org.apache.flink.runtime.OperatorIDPair operatorIDPair : jobVertex.getOperatorIDPairs()) {
231:                 OperatorState operatorState =
232:                         operatorStates.get(operatorIDPair.getGeneratedOperatorID());
233:                 checkState(
234:                         operatorState == null || !operatorState.hasSubtaskStates(),
235:                         "There should be no states or only coordinator state reported for fully finished operators");
236: 
237:                 operatorState =
238:                         new FullyFinishedOperatorState(
239:                                 operatorIDPair.getGeneratedOperatorID(),
240:                                 jobVertex.getParallelism(),
241:                                 jobVertex.getMaxParallelism());
242:                 operatorStates.put(operatorIDPair.getGeneratedOperatorID(), operatorState);
243:             }
244:         }
245:     }
246: 
247:     private void fulfillSubtaskStateForPartiallyFinishedOperators(
248:             Map<OperatorIDPair, OperatorState> operatorStates) {
249:         for (Execution finishedTask : finishedTasks) {
250:             ExecutionJobVertex jobVertex = finishedTask.getVertex().getJobVertex();
251:             for (org.apache.flink.runtime.OperatorIDPair operatorIDPair : jobVertex.getOperatorIDPairs()) {
252:                 OperatorState operatorState =
253:                         operatorStates.get(operatorIDPair.getGeneratedOperatorID());
254: 
255:                 if (operatorState != null && operatorState.isFullyFinished()) {
256:                     continue;
257:                 }
258: 
259:                 if (operatorState == null) {
260:                     operatorState =
261:                             new OperatorState(
262:                                     operatorIDPair.getGeneratedOperatorID(),
263:                                     jobVertex.getParallelism(),
264:                                     jobVertex.getMaxParallelism());
265:                     operatorStates.put(operatorIDPair.getGeneratedOperatorID(), operatorState);
266:                 }
267: 
268:                 operatorState.putState(
269:                         finishedTask.getParallelSubtaskIndex(),
270:                         FinishedOperatorSubtaskState.INSTANCE);
271:             }
272:         }
273:     }
274: }
