490:     private static CompletableFuture<
491:                     Map<IntermediateResultPartitionID, ResultPartitionDeploymentDescriptor>>
492:             registerProducedPartitions(
493:                     ExecutionVertex vertex,
494:                     TaskManagerLocation location,
495:                     ExecutionAttemptID attemptId) {
496: 
497:         ProducerDescriptor producerDescriptor = ProducerDescriptor.create(location, attemptId);
498: 
499:         Collection<IntermediateResultPartition> partitions =
500:                 vertex.getProducedPartitions().values();
501:         Collection<CompletableFuture<ResultPartitionDeploymentDescriptor>> partitionRegistrations =
502:                 new ArrayList<>(partitions.size());
503: 
504:         for (IntermediateResultPartition partition : partitions) {
505:             PartitionDescriptor partitionDescriptor = PartitionDescriptor.from(partition);
506:             CompletableFuture<? extends ShuffleDescriptor> shuffleDescriptorFuture =
507:                     vertex.getExecutionGraphAccessor()
508:                             .getShuffleMaster()
509:                             .registerPartitionWithProducer(
510:                                     vertex.getJobId(), partitionDescriptor, producerDescriptor);
511: 
512:             CompletableFuture<ResultPartitionDeploymentDescriptor> partitionRegistration =
513:                     shuffleDescriptorFuture.thenApply(
514:                             shuffleDescriptor ->
515:                                     createResultPartitionDeploymentDescriptor(
516:                                             partitionDescriptor, partition, shuffleDescriptor));
517:             partitionRegistrations.add(partitionRegistration);
518:         }
519: 
520:         return FutureUtils.combineAll(partitionRegistrations)
521:                 .thenApply(
522:                         rpdds -> {
523:                             Map<IntermediateResultPartitionID, ResultPartitionDeploymentDescriptor>
524:                                     producedPartitions =
525:                                             CollectionUtil.newLinkedHashMapWithExpectedSize(
526:                                                     partitions.size());
527:                             rpdds.forEach(
528:                                     rpdd -> producedPartitions.put(rpdd.getPartitionId(), rpdd));
529:                             return producedPartitions;
530:                         });
531:     }
