571:         }
572: 
573:         // make sure exactly one deployment call happens from the correct state
574:         ExecutionState previous = this.state;
575:         if (previous == SCHEDULED) {
576:             if (!transitionState(previous, DEPLOYING)) {
577:                 // race condition, someone else beat us to the deploying call.
578:                 // this should actually not happen and indicates a race somewhere else
579:                 throw new IllegalStateException(
580:                         "Cannot deploy task: Concurrent deployment call race.");
581:             }
582:         } else {
583:             // vertex may have been cancelled, or it was already scheduled
584:             throw new IllegalStateException(
585:                     "The vertex must be in SCHEDULED state to be deployed. Found state "
586:                             + previous);
587:         }
588: 
589:         if (this != slot.getPayload()) {
590:             throw new IllegalStateException(
591:                     String.format(
592:                             "The execution %s has not been assigned to the assigned slot.", this));
593:         }
594: 
595:         try {
596: 
597:             // race double check, did we fail/cancel and do we need to release the slot?
598:             if (this.state != DEPLOYING) {
599:                 slot.releaseSlot(
600:                         new FlinkException(
601:                                 "Actual state of execution "
602:                                         + this
603:                                         + " ("
604:                                         + state
605:                                         + ") does not match expected state DEPLOYING."));
606:                 return;
607:             }
608: 
609:             LOG.info(
610:                     "Deploying {} (attempt #{}) with attempt id {} and vertex id {} to {} with allocation id {}",
611:                     vertex.getTaskNameWithSubtaskIndex(),
612:                     getAttemptNumber(),
613:                     attemptId,
614:                     vertex.getID(),
615:                     getAssignedResourceLocation(),
616:                     slot.getAllocationId());
617: 
618:             final TaskDeploymentDescriptor deployment =
619:                     vertex.getExecutionGraphAccessor()
620:                             .getTaskDeploymentDescriptorFactory()
621:                             .createDeploymentDescriptor(
622:                                     this,
623:                                     slot.getAllocationId(),
624:                                     taskRestore,
625:                                     producedPartitions.values());
626: 
627:             // null taskRestore to let it be GC'ed
628:             taskRestore = null;
629: 
630:             final TaskManagerGateway taskManagerGateway = slot.getTaskManagerGateway();
631: 
632:             final ComponentMainThreadExecutor jobMasterMainThreadExecutor =
633:                     vertex.getExecutionGraphAccessor().getJobMasterMainThreadExecutor();
634: 
635:             getVertex().notifyPendingDeployment(this);
636:             // We run the submission in the future executor so that the serialization of large TDDs
637:             // does not block
638:             // the main thread and sync back to the main thread once submission is completed.
639:             CompletableFuture.supplyAsync(
640:                             () -> taskManagerGateway.submitTask(deployment, rpcTimeout), executor)
641:                     .thenCompose(Function.identity())
642:                     .whenCompleteAsync(
643:                             (ack, failure) -> {
644:                                 if (failure == null) {
645:                                     vertex.notifyCompletedDeployment(this);
646:                                 } else {
647:                                     final Throwable actualFailure =
648:                                             ExceptionUtils.stripCompletionException(failure);
649: 
650:                                     if (actualFailure instanceof TimeoutException) {
651:                                         String taskname =
652:                                                 vertex.getTaskNameWithSubtaskIndex()
653:                                                         + " ("
654:                                                         + attemptId
655:                                                         + ')';
656: 
657:                                         markFailed(
658:                                                 new Exception(
659:                                                         "Cannot deploy task "
660:                                                                 + taskname
661:                                                                 + " - TaskManager ("
662:                                                                 + getAssignedResourceLocation()
663:                                                                 + ") not responding after a rpcTimeout of "
664:                                                                 + rpcTimeout,
665:                                                         actualFailure));
666:                                     } else {
667:                                         markFailed(actualFailure);
668:                                     }
669:                                 }
670:                             },
671:                             jobMasterMainThreadExecutor);
672: 
673:         } catch (Throwable t) {
674:             markFailed(t);
675:         }
676:     }
