768:     private void updatePartitionConsumers(final IntermediateResultPartition partition) {
769:         final List<ConsumerVertexGroup> consumerVertexGroups = partition.getConsumerVertexGroups();
770:         if (consumerVertexGroups.isEmpty()) {
771:             return;
772:         }
773:         final Set<ExecutionVertexID> updatedVertices = new HashSet<>();
774:         for (ConsumerVertexGroup consumerVertexGroup : consumerVertexGroups) {
775:             for (ExecutionVertexID consumerVertexId : consumerVertexGroup) {
776:                 if (updatedVertices.contains(consumerVertexId)) {
777:                     continue;
778:                 }
779: 
780:                 final ExecutionVertex consumerVertex =
781:                         vertex.getExecutionGraphAccessor()
782:                                 .getExecutionVertexOrThrow(consumerVertexId);
783:                 final Collection<Execution> consumers = consumerVertex.getCurrentExecutions();
784:                 for (Execution consumer : consumers) {
785:                     final ExecutionState consumerState = consumer.getState();
786:                     // ----------------------------------------------------------------
787:                     // Consumer is recovering or running => send update message now
788:                     // Consumer is deploying => cache the partition info which would be
789:                     // sent after switching to running
790:                     // ----------------------------------------------------------------
791:                     if (consumerState == DEPLOYING
792:                             || consumerState == RUNNING
793:                             || consumerState == INITIALIZING) {
794:                         final PartitionInfo partitionInfo = createFinishedPartitionInfo(partition);
795:                         updatedVertices.add(consumerVertexId);
796: 
797:                         if (consumerState == DEPLOYING) {
798:                             consumerVertex.cachePartitionInfo(partitionInfo);
799:                         } else {
800:                             consumer.sendUpdatePartitionInfoRpcCall(
801:                                     Collections.singleton(partitionInfo));
802:                         }
803:                     }
804:                 }
805:             }
806:         }
807:     }
