1029:     private void finishPartitionsAndUpdateConsumers() {
1030:         final List<IntermediateResultPartition> finishedPartitions =
1031:                 getVertex().finishPartitionsIfNeeded();
1032: 
1033:         for (IntermediateResultPartition partition : finishedPartitions) {
1034:             updatePartitionConsumers(partition);
1035:         }
1036:     }
