1133:     /**
1134:      * Process a execution failure. The failure can be fired by JobManager or reported by
1135:      * TaskManager. If it is fired by JobManager and the execution is already deployed, it needs to
1136:      * send a PRC call to remove the task from TaskManager. It also needs to release the produced
1137:      * partitions if it fails before deployed (because the partitions are possibly already created
1138:      * in external shuffle service) or JobManager proactively fails it (in case that it finishes in
1139:      * TaskManager when JobManager tries to fail it). The failure will be notified to SchedulerNG if
1140:      * it is from within the ExecutionGraph. This is to trigger the failure handling of SchedulerNG
1141:      * to recover this failed execution.
1142:      *
1143:      * @param t Failure cause
1144:      * @param cancelTask Indicating whether to send a PRC call to remove task from TaskManager. True
1145:      *     if the failure is fired by JobManager and the execution is already deployed. Otherwise it
1146:      *     should be false.
1147:      * @param userAccumulators User accumulators
1148:      * @param metrics IO metrics
1149:      * @param releasePartitions Indicating whether to release result partitions produced by this
1150:      *     execution. False if the task is FAILED in TaskManager, otherwise true.
1151:      * @param fromSchedulerNg Indicating whether the failure is from the SchedulerNg. It should be
1152:      *     false if it is from within the ExecutionGraph.
1153:      */
1154:     private void processFail(
1155:             Throwable t,
1156:             boolean cancelTask,
1157:             Map<String, Accumulator<?, ?>> userAccumulators,
1158:             IOMetrics metrics,
1159:             boolean releasePartitions,
1160:             boolean fromSchedulerNg) {
1161: 
1162:         assertRunningInJobMasterMainThread();
1163: 
1164:         ExecutionState current = this.state;
1165: 
1166:         if (current == FAILED) {
1167:             // already failed. It is enough to remember once that we failed (its sad enough)
1168:             return;
1169:         }
1170: 
1171:         if (current == CANCELED || current == FINISHED) {
1172:             // we are already aborting or are already aborted or we are already finished
1173:             if (LOG.isDebugEnabled()) {
1174:                 LOG.debug(
1175:                         "Ignoring transition of vertex {} to {} while being {}.",
1176:                         getVertexWithAttempt(),
1177:                         FAILED,
1178:                         current);
1179:             }
1180:             return;
1181:         }
1182: 
1183:         if (current == CANCELING) {
1184:             completeCancelling(userAccumulators, metrics, true);
1185:             return;
1186:         }
1187: 
1188:         if (!fromSchedulerNg) {
1189:             vertex.getExecutionGraphAccessor()
1190:                     .notifySchedulerNgAboutInternalTaskFailure(
1191:                             attemptId, t, cancelTask, releasePartitions);
1192:             return;
1193:         }
1194: 
1195:         checkState(transitionState(current, FAILED, t));
1196: 
1197:         // success (in a manner of speaking)
1198:         this.failureCause =
1199:                 Optional.of(
1200:                         ErrorInfo.createErrorInfoWithNullableCause(t, getStateTimestamp(FAILED)));
1201: 
1202:         updateAccumulatorsAndMetrics(userAccumulators, metrics);
1203: 
1204:         releaseAssignedResource(t);
1205:         vertex.getExecutionGraphAccessor().deregisterExecution(this);
1206: 
1207:         maybeReleasePartitionsAndSendCancelRpcCall(current, cancelTask, releasePartitions);
1208:     }
1209: 
1210:     private void maybeReleasePartitionsAndSendCancelRpcCall(
1211:             final ExecutionState stateBeforeFailed,
1212:             final boolean cancelTask,
1213:             final boolean releasePartitions) {
1214: 
1215:         handlePartitionCleanup(releasePartitions, releasePartitions);
1216: 
1217:         if (cancelTask
1218:                 && (stateBeforeFailed == RUNNING
1219:                         || stateBeforeFailed == INITIALIZING
1220:                         || stateBeforeFailed == DEPLOYING)) {
1221:             if (LOG.isDebugEnabled()) {
1222:                 LOG.debug("Sending out cancel request, to remove task execution from TaskManager.");
1223:             }
1224: 
1225:             try {
