202:             this.initialResourceAllocationTimeout = initialResourceAllocationTimeout;
203:             this.stateTransitionManagerFactory = stateTransitionManagerFactory;
204:             this.previousExecutionGraph = previousExecutionGraph;
205:         }
206: 
207:         public Class<WaitingForResources> getStateClass() {
208:             return WaitingForResources.class;
209:         }
210: 
