37: /**
38:  * {@code DefaultRescaleManager} manages triggering the next rescaling based on when the previous
39:  * rescale operation happened and the available resources. It handles the event based on the
40:  * following phases (in that order):
41:  *
42:  * <ol>
43:  *   <li>Cooldown phase: No rescaling takes place (its upper threshold is defined by {@code
44:  *       scalingIntervalMin}.
45:  *   <li>Soft-rescaling phase: Rescaling is triggered if the desired amount of resources is
46:  *       available.
47:  *   <li>Hard-rescaling phase: Rescaling is triggered if a sufficient amount of resources is
48:  *       available (its lower threshold is defined by (@code scalingIntervalMax}).
49:  * </ol>
50:  *
51:  * <p>Thread-safety: This class is not implemented in a thread-safe manner and relies on the fact
52:  * that any method call happens within a single thread.
53:  *
54:  * @see Executing
55:  */
56: @NotThreadSafe
57: public class DefaultRescaleManager implements RescaleManager {
58: 
59:     private static final Logger LOG = LoggerFactory.getLogger(DefaultRescaleManager.class);
60: 
61:     private final Temporal initializationTime;
62:     private final Supplier<Temporal> clock;
63: 
64:     @VisibleForTesting final Duration scalingIntervalMin;
65:     @VisibleForTesting @Nullable final Duration scalingIntervalMax;
66: 
67:     private final RescaleManager.Context rescaleContext;
68: 
69:     private boolean rescaleScheduled = false;
70: 
71:     @VisibleForTesting final Duration maxTriggerDelay;
72: 
73:     /**
74:      * {@code triggerFuture} is used to allow triggering a scheduled callback. Rather than
75:      * scheduling the callback itself, the callback is just chained with the future. The completion
76:      * of the future is then scheduled which will, as a consequence, run the callback as part of the
77:      * scheduled operation.
78:      *
79:      * <p>{@code triggerFuture} can be used to trigger the callback even earlier (before the
80:      * scheduled delay has passed). See {@link #onTrigger()}.
81:      */
82:     private CompletableFuture<Void> triggerFuture;
83: 
84:     DefaultRescaleManager(
85:             Temporal initializationTime,
86:             RescaleManager.Context rescaleContext,
87:             Duration scalingIntervalMin,
88:             @Nullable Duration scalingIntervalMax,
89:             Duration maxTriggerDelay) {
90:         this(
91:                 initializationTime,
