59: /** State which represents a running job with an {@link ExecutionGraph} and assigned slots. */
60: class Executing extends StateWithExecutionGraph
61:         implements ResourceListener, StateTransitionManager.Context, CheckpointStatsListener {
62: 
63:     private final Context context;
64: 
65:     private final RescalingController sufficientResourcesController;
66:     private final RescalingController desiredResourcesController;
67:     private final StateTransitionManager rescaleManager;
68:     private final int rescaleOnFailedCheckpointCount;
69:     // null indicates that there was no change event observed, yet
70:     @Nullable private AtomicInteger failedCheckpointCountdown;
71: 
72:     Executing(
73:             ExecutionGraph executionGraph,
74:             ExecutionGraphHandler executionGraphHandler,
75:             OperatorCoordinatorHandler operatorCoordinatorHandler,
76:             Logger logger,
77:             Context context,
78:             ClassLoader userCodeClassLoader,
79:             List<ExceptionHistoryEntry> failureCollection,
80:             StateTransitionManager.Factory rescaleManagerFactory,
81:             int minParallelismChangeForRescale,
82:             int rescaleOnFailedCheckpointCount,
83:             Instant lastRescale) {
84:         super(
85:                 context,
86:                 executionGraph,
87:                 executionGraphHandler,
88:                 operatorCoordinatorHandler,
89:                 logger,
90:                 userCodeClassLoader,
91:                 failureCollection);
92:         this.context = context;
93:         Preconditions.checkState(
94:                 executionGraph.getState() == JobStatus.RUNNING, "Assuming running execution graph");
95: 
96:         this.sufficientResourcesController = new EnforceParallelismChangeRescalingController();
97:         this.desiredResourcesController =
98:                 new EnforceMinimalIncreaseRescalingController(minParallelismChangeForRescale);
99:         this.rescaleManager = rescaleManagerFactory.create(this, lastRescale);
100: 
101:         Preconditions.checkArgument(
102:                 rescaleOnFailedCheckpointCount > 0,
103:                 "The rescaleOnFailedCheckpointCount should be larger than 0.");
104:         this.rescaleOnFailedCheckpointCount = rescaleOnFailedCheckpointCount;
105:         this.failedCheckpointCountdown = null;
106: 
107:         deploy();
108: 
109:         // check if new resources have come available in the meantime
110:         context.runIfState(
111:                 this,
112:                 () -> {
113:                     rescaleManager.onChange();
114:                     rescaleManager.onTrigger();
115:                 },
116:                 Duration.ZERO);
117:     }
118: 
119:     @Override
120:     public boolean hasSufficientResources() {
121:         return shouldRescale(sufficientResourcesController);
122:     }
123: 
124:     @Override
125:     public boolean hasDesiredResources() {
126:         return shouldRescale(desiredResourcesController);
127:     }
128: 
129:     private boolean shouldRescale(RescalingController rescalingController) {
130:         return context.getAvailableVertexParallelism()
131:                 .filter(
132:                         availableVertexParallelism ->
133:                                 rescalingController.shouldRescale(
134:                                         extractCurrentVertexParallelism(getExecutionGraph()),
135:                                         availableVertexParallelism))
136:                 .isPresent();
137:     }
138: 
139:     private static VertexParallelism extractCurrentVertexParallelism(
140:             AccessExecutionGraph executionGraph) {
141:         return new VertexParallelism(
142:                 executionGraph.getAllVertices().values().stream()
143:                         .collect(
144:                                 Collectors.toMap(
145:                                         AccessExecutionJobVertex::getJobVertexId,
146:                                         AccessExecutionJobVertex::getParallelism)));
147:     }
148: 
149:     @Override
150:     public void scheduleOperation(Runnable callback, Duration delay) {
151:         context.runIfState(this, callback, delay);
152:     }
153: 
154:     @Override
155:     public void transitionToSubsequentState() {
156:         context.goToRestarting(
157:                 getExecutionGraph(),
158:                 getExecutionGraphHandler(),
159:                 getOperatorCoordinatorHandler(),
160:                 Duration.ofMillis(0L),
161:                 getFailures());
162:     }
163: 
164:     @Override
165:     public JobStatus getJobStatus() {
166:         return JobStatus.RUNNING;
167:     }
168: 
169:     @Override
170:     public void cancel() {
171:         context.goToCanceling(
172:                 getExecutionGraph(),
173:                 getExecutionGraphHandler(),
174:                 getOperatorCoordinatorHandler(),
175:                 getFailures());
176:     }
177: 
178:     @Override
179:     void onFailure(Throwable cause, CompletableFuture<Map<String, String>> failureLabels) {
180:         FailureResultUtil.restartOrFail(
181:                 context.howToHandleFailure(cause, failureLabels), context, this);
182:     }
183: 
184:     @Override
185:     void onGloballyTerminalState(JobStatus globallyTerminalState) {
186:         context.goToFinished(ArchivedExecutionGraph.createFrom(getExecutionGraph()));
187:     }
188: 
189:     private void deploy() {
190:         for (ExecutionJobVertex executionJobVertex :
191:                 getExecutionGraph().getVerticesTopologically()) {
192:             for (ExecutionVertex executionVertex : executionJobVertex.getTaskVertices()) {
193:                 if (executionVertex.getExecutionState() == ExecutionState.CREATED
194:                         || executionVertex.getExecutionState() == ExecutionState.SCHEDULED) {
195:                     deploySafely(executionVertex);
196:                 }
197:             }
198:         }
199:     }
200: 
201:     private void deploySafely(ExecutionVertex executionVertex) {
202:         try {
203:             executionVertex.deploy();
204:         } catch (JobException e) {
205:             handleDeploymentFailure(executionVertex, e);
206:         }
207:     }
208: 
209:     private void handleDeploymentFailure(ExecutionVertex executionVertex, JobException e) {
210:         executionVertex.markFailed(e);
211:     }
212: 
213:     @Override
214:     public void onNewResourcesAvailable() {
215:         rescaleManager.onChange();
216:         initializeFailedCheckpointCountdownIfUnset();
217:     }
218: 
219:     @Override
220:     public void onNewResourceRequirements() {
221:         rescaleManager.onChange();
222:         initializeFailedCheckpointCountdownIfUnset();
223:     }
224: 
225:     @Override
226:     public void onCompletedCheckpoint() {
227:         triggerPotentialRescale();
228:     }
229: 
230:     @Override
231:     public void onFailedCheckpoint() {
232:         if (this.failedCheckpointCountdown != null
233:                 && this.failedCheckpointCountdown.decrementAndGet() <= 0) {
234:             triggerPotentialRescale();
235:         }
236:     }
237: 
238:     private void triggerPotentialRescale() {
239:         rescaleManager.onTrigger();
240:         this.failedCheckpointCountdown = null;
241:     }
242: 
243:     private void initializeFailedCheckpointCountdownIfUnset() {
244:         if (failedCheckpointCountdown == null) {
245:             this.failedCheckpointCountdown = new AtomicInteger(this.rescaleOnFailedCheckpointCount);
246:         }
247:     }
