281:     interface Context
282:             extends StateWithExecutionGraph.Context,
283:                     StateTransitions.ToCancelling,
284:                     StateTransitions.ToFailing,
285:                     StateTransitions.ToRestarting,
286:                     StateTransitions.ToStopWithSavepoint {
287: 
288:         /**
289:          * Asks how to handle the failure.
290:          *
291:          * @param failure failure describing the failure cause
292:          * @param failureLabels future of labels from error classification.
293:          * @return {@link FailureResult} which describes how to handle the failure
294:          */
295:         FailureResult howToHandleFailure(
296:                 Throwable failure, CompletableFuture<Map<String, String>> failureLabels);
297: 
298:         /**
299:          * Returns the {@link VertexParallelism} that can be provided by the currently available
300:          * slots.
301:          */
302:         Optional<VertexParallelism> getAvailableVertexParallelism();
303: 
304:         /**
305:          * Runs the given action after a delay if the state at this time equals the expected state.
306:          *
307:          * @param expectedState expectedState describes the required state at the time of running
308:          *     the action
309:          * @param action action to run if the expected state equals the actual state
310:          * @param delay delay after which to run the action
311:          * @return a ScheduledFuture representing pending completion of the task
312:          */
313:         ScheduledFuture<?> runIfState(State expectedState, Runnable action, Duration delay);
314:     }
