213:     @Override
214:     public void onNewResourcesAvailable() {
215:         subsequentStateTransitionManager.onChange();
216:         initializeFailedCheckpointCountdownIfUnset();
217:     }
218: 
219:     @Override
220:     public void onNewResourceRequirements() {
221:         subsequentStateTransitionManager.onChange();
222:         initializeFailedCheckpointCountdownIfUnset();
223:     }
