233:                 && this.failedCheckpointCountdown.decrementAndGet() <= 0) {
234:             triggerPotentialRescale();
235:         }
236:     }
237: 
238:     private void triggerPotentialRescale() {
239:         subsequentStateTransitionManager.onTrigger();
240:         this.failedCheckpointCountdown = null;
241:     }
242: 
243:     private void initializeFailedCheckpointCountdownIfUnset() {
244:         if (failedCheckpointCountdown == null) {
245:             this.failedCheckpointCountdown = new AtomicInteger(this.rescaleOnFailedCheckpointCount);
246:         }
247:     }
