57: public class DefaultRescaleManager implements RescaleManager {
58: 
59:     private static final Logger LOG = LoggerFactory.getLogger(DefaultRescaleManager.class);
60: 
61:     private final Temporal initializationTime;
62:     private final Supplier<Temporal> clock;
63: 
64:     @VisibleForTesting final Duration cooldownTimeout;
65:     @VisibleForTesting @Nullable final Duration scalingIntervalMax;
66: 
67:     private final RescaleManager.Context rescaleContext;
68: 
69:     private boolean rescaleScheduled = false;
70: 
71:     @VisibleForTesting final Duration maxTriggerDelay;
72: 
73:     /**
74:      * {@code triggerFuture} is used to allow triggering a scheduled callback. Rather than
75:      * scheduling the callback itself, the callback is just chained with the future. The completion
76:      * of the future is then scheduled which will, as a consequence, run the callback as part of the
77:      * scheduled operation.
78:      *
79:      * <p>{@code triggerFuture} can be used to trigger the callback even earlier (before the
80:      * scheduled delay has passed). See {@link #onTrigger()}.
81:      */
82:     private CompletableFuture<Void> triggerFuture;
83: 
84:     DefaultRescaleManager(
85:             Temporal initializationTime,
86:             RescaleManager.Context rescaleContext,
87:             Duration scalingIntervalMin,
88:             @Nullable Duration scalingIntervalMax,
89:             Duration maxTriggerDelay) {
90:         this(
91:                 initializationTime,
92:                 Instant::now,
93:                 rescaleContext,
94:                 scalingIntervalMin,
95:                 scalingIntervalMax,
96:                 maxTriggerDelay);
97:     }
98: 
99:     @VisibleForTesting
100:     DefaultRescaleManager(
101:             Temporal initializationTime,
102:             Supplier<Temporal> clock,
103:             RescaleManager.Context rescaleContext,
104:             Duration scalingIntervalMin,
105:             @Nullable Duration scalingIntervalMax,
106:             Duration maxTriggerDelay) {
107:         this.initializationTime = initializationTime;
108:         this.clock = clock;
109: 
110:         this.maxTriggerDelay = maxTriggerDelay;
111:         this.triggerFuture = FutureUtils.completedVoidFuture();
112: 
113:         Preconditions.checkArgument(
114:                 scalingIntervalMax == null || scalingIntervalMin.compareTo(scalingIntervalMax) <= 0,
115:                 "scalingIntervalMax should at least match or be longer than scalingIntervalMin.");
116:         this.cooldownTimeout = scalingIntervalMin;
117:         this.scalingIntervalMax = scalingIntervalMax;
118: 
119:         this.rescaleContext = rescaleContext;
120:     }
121: 
122:     @Override
123:     public void onChange() {
124:         if (this.triggerFuture.isDone()) {
125:             this.triggerFuture = scheduleOperationWithTrigger(this::evaluateChangeEvent);
126:         }
127:     }
128: 
129:     @Override
130:     public void onTrigger() {
131:         if (!this.triggerFuture.isDone()) {
132:             this.triggerFuture.complete(null);
133:             LOG.debug(
134:                     "A rescale trigger event was observed causing the rescale verification logic to be initiated.");
135:         } else {
136:             LOG.debug(
137:                     "A rescale trigger event was observed outside of a rescale cycle. No action taken.");
138:         }
139:     }
140: 
141:     private void evaluateChangeEvent() {
142:         if (timeSinceLastRescale().compareTo(cooldownTimeout) > 0) {
143:             maybeRescale();
144:         } else if (!rescaleScheduled) {
145:             rescaleScheduled = true;
146:             rescaleContext.scheduleOperation(this::maybeRescale, cooldownTimeout);
147:         }
148:     }
149: 
150:     private CompletableFuture<Void> scheduleOperationWithTrigger(Runnable callback) {
151:         final CompletableFuture<Void> triggerFuture = new CompletableFuture<>();
152:         triggerFuture.thenRun(callback);
153:         this.rescaleContext.scheduleOperation(
154:                 () -> triggerFuture.complete(null), this.maxTriggerDelay);
155: 
156:         return triggerFuture;
157:     }
158: 
159:     private Duration timeSinceLastRescale() {
160:         return Duration.between(this.initializationTime, clock.get());
161:     }
162: 
163:     private void maybeRescale() {
164:         rescaleScheduled = false;
165:         if (rescaleContext.hasDesiredResources()) {
166:             LOG.info("Desired parallelism for job was reached: Rescaling will be triggered.");
167:             rescaleContext.rescale();
168:         } else if (scalingIntervalMax != null) {
169:             LOG.info(
170:                     "The longer the pipeline runs, the more the (small) resource gain is worth the restarting time. "
171:                             + "Last resource added does not meet the configured minimal parallelism change. Forced rescaling will be triggered after {} if the resource is still there.",
172:                     scalingIntervalMax);
173: 
174:             // reasoning for inconsistent scheduling:
175:             // https://lists.apache.org/thread/m2w2xzfjpxlw63j0k7tfxfgs0rshhwwr
176:             if (timeSinceLastRescale().compareTo(scalingIntervalMax) > 0) {
177:                 rescaleWithSufficientResources();
178:             } else {
179:                 rescaleContext.scheduleOperation(
180:                         this::rescaleWithSufficientResources, scalingIntervalMax);
181:             }
182:         }
183:     }
184: 
185:     private void rescaleWithSufficientResources() {
186:         if (rescaleContext.hasSufficientResources()) {
187:             LOG.info(
188:                     "Resources for desired job parallelism couldn't be collected after {}: Rescaling will be enforced.",
189:                     scalingIntervalMax);
190:             rescaleContext.rescale();
191:         }
192:     }
