194:     public static class Factory implements RescaleManager.Factory {
195: 
196:         private final Duration scalingIntervalMin;
197:         @Nullable private final Duration scalingIntervalMax;
198:         private final Duration maximumDelayForTrigger;
199: 
200:         /**
201:          * Creates a {@code Factory} instance based on the {@link AdaptiveScheduler}'s {@code
202:          * Settings} for rescaling.
203:          */
204:         public static Factory fromSettings(AdaptiveScheduler.Settings settings) {
205:             // it's not ideal that we use a AdaptiveScheduler internal class here. We might want to
206:             // change that as part of a more general alignment of the rescaling configuration.
207:             return new Factory(
208:                     settings.getScalingIntervalMin(),
209:                     settings.getScalingIntervalMax(),
210:                     settings.getMaximumDelayForTriggeringRescale());
211:         }
212: 
213:         private Factory(
214:                 Duration scalingIntervalMin,
215:                 @Nullable Duration scalingIntervalMax,
216:                 Duration maximumDelayForTrigger) {
217:             this.scalingIntervalMin = scalingIntervalMin;
218:             this.scalingIntervalMax = scalingIntervalMax;
219:             this.maximumDelayForTrigger = maximumDelayForTrigger;
220:         }
221: 
222:         @Override
223:         public DefaultRescaleManager create(Context rescaleContext, Instant lastRescale) {
224:             return new DefaultRescaleManager(
225:                     lastRescale,
226:                     rescaleContext,
227:                     scalingIntervalMin,
