1373:     private CompletableFuture<ExecutionGraph> createExecutionGraphAndRestoreStateAsync(
1374:             VertexParallelismStore adjustedParallelismStore) {
1375:         backgroundTask.abort();
1376: 
1377:         backgroundTask =
1378:                 backgroundTask.runAfter(
1379:                         () -> createExecutionGraphAndRestoreState(adjustedParallelismStore),
1380:                         ioExecutor);
1381: 
1382:         return FutureUtils.switchExecutor(
1383:                 backgroundTask.getResultFuture(), getMainThreadExecutor());
1384:     }
