1388:             VertexParallelismStore adjustedParallelismStore) throws Exception {
1389:         return executionGraphFactory.createAndRestoreExecutionGraph(
1390:                 jobInformation.copyJobGraph(),
1391:                 completedCheckpointStore,
1392:                 checkpointsCleaner,
1393:                 checkpointIdCounter,
1394:                 checkpointStatsTracker,
1395:                 TaskDeploymentDescriptorFactory.PartitionLocationConstraint.MUST_BE_KNOWN,
1396:                 initializationTimestamp,
1397:                 vertexAttemptNumberStore,
1398:                 adjustedParallelismStore,
1399:                 deploymentTimeMetrics,
1400:                 // adaptive scheduler works in streaming mode, actually it only
1401:                 // supports must be pipelined result partition, mark partition finish is
1402:                 // no need.
1403:                 rp -> false,
1404:                 LOG);
1405:     }
