1505:     /**
1506:      * Transition the scheduler to another state. This method guards against state transitions while
1507:      * there is already a transition ongoing. This effectively means that you can not call this
1508:      * method from a State constructor or State#onLeave.
1509:      *
1510:      * @param targetState State to transition to
1511:      * @param <T> Type of the target state
1512:      * @return A target state instance
1513:      */
1514:     @VisibleForTesting
1515:     <T extends State> T transitionToState(StateFactory<T> targetState) {
1516:         Preconditions.checkState(
1517:                 !isTransitioningState,
1518:                 "State transitions must not be triggered while another state transition is in progress.");
1519:         Preconditions.checkState(
1520:                 state.getClass() != targetState.getStateClass(),
1521:                 "Attempted to transition into the very state the scheduler is already in.");
1522:         componentMainThreadExecutor.assertRunningInMainThread();
1523: 
1524:         try {
1525:             isTransitioningState = true;
1526:             LOG.debug(
1527:                     "Transition from state {} to {}.",
1528:                     state.getClass().getSimpleName(),
1529:                     targetState.getStateClass().getSimpleName());
1530: 
1531:             final JobStatus previousJobStatus = state.getJobStatus();
1532: 
1533:             state.onLeave(targetState.getStateClass());
1534:             T targetStateInstance = targetState.getState();
1535:             state = targetStateInstance;
1536: 
1537:             final JobStatus newJobStatus = state.getJobStatus();
1538: 
1539:             if (previousJobStatus != newJobStatus) {
1540:                 final long timestamp = System.currentTimeMillis();
1541:                 jobStatusListeners.forEach(
1542:                         listener ->
1543:                                 listener.jobStatusChanges(
1544:                                         jobInformation.getJobID(), newJobStatus, timestamp));
1545:             }
1546: 
1547:             return targetStateInstance;
1548:         } finally {
1549:             isTransitioningState = false;
1550:         }
1551:     }
