81: /**
82:  * A util class which attempts to chain all available Python functions.
83:  *
84:  * <p>An operator could be chained to it's predecessor if all of the following conditions are met:
85:  *
86:  * <ul>
87:  *   <li>Both of them are Python operators
88:  *   <li>The parallelism, the maximum parallelism and the slot sharing group are all the same
89:  *   <li>The chaining strategy is ChainingStrategy.ALWAYS and the chaining strategy of the
90:  *       predecessor isn't ChainingStrategy.NEVER
91:  *   <li>This partitioner between them is ForwardPartitioner
92:  * </ul>
93:  *
94:  * <p>The properties of the generated chained operator are as following:
95:  *
96:  * <ul>
97:  *   <li>The name is the concatenation of all the names of the chained operators
98:  *   <li>The parallelism, the maximum parallelism and the slot sharing group are from one of the
99:  *       chained operators as all of them are the same between the chained operators
100:  *   <li>The chaining strategy is the same as the head operator
101:  *   <li>The uid and the uidHash are the same as the head operator
102:  * </ul>
103:  */
104: public class PythonOperatorChainingOptimizer {
105: 
106:     /**
107:      * Perform chaining optimization. It will iterate the transformations defined in the given
108:      * StreamExecutionEnvironment and update them with the chained transformations.
109:      */
110:     @SuppressWarnings("unchecked")
111:     public static void apply(StreamExecutionEnvironment env) throws Exception {
112:         if (env.getConfiguration().get(PythonOptions.PYTHON_OPERATOR_CHAINING_ENABLED)) {
113:             final Field transformationsField =
114:                     StreamExecutionEnvironment.class.getDeclaredField("transformations");
115:             transformationsField.setAccessible(true);
116:             final List<Transformation<?>> transformations =
117:                     (List<Transformation<?>>) transformationsField.get(env);
118:             transformationsField.set(env, optimize(transformations));
119:         }
120:     }
121: 
122:     /**
123:      * Perform chaining optimization. It will iterate the transformations defined in the given
124:      * StreamExecutionEnvironment and update them with the chained transformations. Besides, it will
125:      * return the transformation after chaining optimization for the given transformation.
126:      */
127:     @SuppressWarnings("unchecked")
128:     public static Transformation<?> apply(
129:             StreamExecutionEnvironment env, Transformation<?> transformation) throws Exception {
130:         if (env.getConfiguration().get(PythonOptions.PYTHON_OPERATOR_CHAINING_ENABLED)) {
131:             final Field transformationsField =
132:                     StreamExecutionEnvironment.class.getDeclaredField("transformations");
133:             transformationsField.setAccessible(true);
134:             final List<Transformation<?>> transformations =
135:                     (List<Transformation<?>>) transformationsField.get(env);
136:             final Tuple2<List<Transformation<?>>, Transformation<?>> resultTuple =
137:                     optimize(transformations, transformation);
138:             transformationsField.set(env, resultTuple.f0);
139:             return resultTuple.f1;
140:         } else {
141:             return transformation;
142:         }
143:     }
144: 
145:     /**
146:      * Perform chaining optimization. It will return the chained transformations for the given
147:      * transformation list.
148:      */
149:     public static List<Transformation<?>> optimize(List<Transformation<?>> transformations) {
150:         final Map<Transformation<?>, Set<Transformation<?>>> outputMap =
151:                 buildOutputMap(transformations);
152: 
153:         final LinkedHashSet<Transformation<?>> chainedTransformations = new LinkedHashSet<>();
154:         final Set<Transformation<?>> alreadyTransformed = Sets.newIdentityHashSet();
155:         final Queue<Transformation<?>> toTransformQueue = Queues.newArrayDeque(transformations);
156:         while (!toTransformQueue.isEmpty()) {
157:             final Transformation<?> transformation = toTransformQueue.poll();
158:             if (!alreadyTransformed.contains(transformation)) {
159:                 alreadyTransformed.add(transformation);
160: 
161:                 final ChainInfo chainInfo = chainWithInputIfPossible(transformation, outputMap);
162:                 chainedTransformations.add(chainInfo.newTransformation);
163:                 chainedTransformations.removeAll(chainInfo.oldTransformations);
164:                 alreadyTransformed.addAll(chainInfo.oldTransformations);
165: 
166:                 // Add the chained transformation and its inputs to the to-optimize list
167:                 toTransformQueue.add(chainInfo.newTransformation);
168:                 toTransformQueue.addAll(chainInfo.newTransformation.getInputs());
169:             }
170:         }
171:         return new ArrayList<>(chainedTransformations);
172:     }
173: 
174:     /**
175:      * Perform chaining optimization. It will returns the chained transformations and the
176:      * transformation after chaining optimization for the given transformation.
177:      */
178:     public static Tuple2<List<Transformation<?>>, Transformation<?>> optimize(
179:             List<Transformation<?>> transformations, Transformation<?> targetTransformation) {
180:         final Map<Transformation<?>, Set<Transformation<?>>> outputMap =
181:                 buildOutputMap(transformations);
182: 
183:         final LinkedHashSet<Transformation<?>> chainedTransformations = new LinkedHashSet<>();
184:         final Set<Transformation<?>> alreadyTransformed = Sets.newIdentityHashSet();
185:         final Queue<Transformation<?>> toTransformQueue = Queues.newArrayDeque();
186:         toTransformQueue.add(targetTransformation);
187:         while (!toTransformQueue.isEmpty()) {
188:             final Transformation<?> toTransform = toTransformQueue.poll();
189:             if (!alreadyTransformed.contains(toTransform)) {
190:                 alreadyTransformed.add(toTransform);
191: 
192:                 final ChainInfo chainInfo = chainWithInputIfPossible(toTransform, outputMap);
193:                 chainedTransformations.add(chainInfo.newTransformation);
194:                 chainedTransformations.removeAll(chainInfo.oldTransformations);
195:                 alreadyTransformed.addAll(chainInfo.oldTransformations);
196: 
197:                 // Add the chained transformation and its inputs to the to-optimize list
198:                 toTransformQueue.add(chainInfo.newTransformation);
199:                 toTransformQueue.addAll(chainInfo.newTransformation.getInputs());
200: 
201:                 if (toTransform == targetTransformation) {
202:                     targetTransformation = chainInfo.newTransformation;
203:                 }
204:             }
205:         }
206:         return Tuple2.of(new ArrayList<>(chainedTransformations), targetTransformation);
207:     }
208: 
209:     /**
210:      * Construct the key-value pairs where the value is the output transformations of the key
211:      * transformation.
212:      */
213:     private static Map<Transformation<?>, Set<Transformation<?>>> buildOutputMap(
214:             List<Transformation<?>> transformations) {
215:         final Map<Transformation<?>, Set<Transformation<?>>> outputMap = new HashMap<>();
216:         final Queue<Transformation<?>> toTransformQueue = Queues.newArrayDeque(transformations);
217:         final Set<Transformation<?>> alreadyTransformed = Sets.newIdentityHashSet();
218:         while (!toTransformQueue.isEmpty()) {
219:             Transformation<?> transformation = toTransformQueue.poll();
220:             if (!alreadyTransformed.contains(transformation)) {
221:                 alreadyTransformed.add(transformation);
222:                 for (Transformation<?> input : transformation.getInputs()) {
223:                     Set<Transformation<?>> outputs =
224:                             outputMap.computeIfAbsent(input, i -> Sets.newHashSet());
225:                     outputs.add(transformation);
226:                 }
227:                 toTransformQueue.addAll(transformation.getInputs());
228:             }
229:         }
230:         return outputMap;
231:     }
232: 
233:     private static ChainInfo chainWithInputIfPossible(
234:             Transformation<?> transform, Map<Transformation<?>, Set<Transformation<?>>> outputMap) {
235:         ChainInfo chainInfo = null;
236:         if (transform instanceof OneInputTransformation
237:                 && PythonConfigUtil.isPythonDataStreamOperator(transform)) {
238:             Transformation<?> input = transform.getInputs().get(0);
239:             while (!PythonConfigUtil.isPythonDataStreamOperator(input)) {
240:                 if (input instanceof PartitionTransformation
241:                         && ((PartitionTransformation<?>) input).getPartitioner()
242:                                 instanceof ForwardPartitioner) {
243:                     input = input.getInputs().get(0);
244:                 } else {
245:                     return ChainInfo.of(transform);
246:                 }
247:             }
248: 
249:             if (isChainable(input, transform, outputMap)) {
250:                 Transformation<?> chainedTransformation =
251:                         createChainedTransformation(input, transform);
252:                 Set<Transformation<?>> outputTransformations = outputMap.get(transform);
253:                 if (outputTransformations != null) {
254:                     for (Transformation<?> output : outputTransformations) {
255:                         replaceInput(output, transform, chainedTransformation);
256:                     }
257:                     outputMap.put(chainedTransformation, outputTransformations);
258:                 }
259:                 chainInfo = ChainInfo.of(chainedTransformation, Arrays.asList(input, transform));
260:             }
261:         }
262: 
263:         if (chainInfo == null) {
264:             chainInfo = ChainInfo.of(transform);
265:         }
266: 
267:         return chainInfo;
268:     }
