206:     private void validateAutoGatherStatistic(
207:             boolean autoGatherStatistic, CatalogTable catalogTable) {
208:         if (autoGatherStatistic && catalogTable.isPartitioned()) {
209:             // if auto gather statistic and the table is partitioned,
210:             // the table's option "SINK_PARTITION_COMMIT_POLICY_KIND" should contain 'metastore'
211:             org.apache.flink.configuration.Configuration flinkConf =
212:                     org.apache.flink.configuration.Configuration.fromMap(catalogTable.getOptions());
213:             String policyKind = flinkConf.get(HiveOptions.SINK_PARTITION_COMMIT_POLICY_KIND);
214:             String[] policyStrings = policyKind.split(",");
215:             Arrays.stream(policyStrings)
216:                     .filter(policy -> policy.equalsIgnoreCase(PartitionCommitPolicy.METASTORE))
217:                     .findAny()
218:                     .orElseThrow(
219:                             () ->
220:                                     new ValidationException(
221:                                             String.format(
222:                                                     "When %s is set to true, the option %s for the table %s should contains %s.",
223:                                                     HiveOptions
224:                                                             .TABLE_EXEC_HIVE_SINK_STATISTIC_AUTO_GATHER_ENABLE
225:                                                             .key(),
226:                                                     FileSystemConnectorOptions
227:                                                             .SINK_PARTITION_COMMIT_POLICY_CLASS,
228:                                                     identifier,
229:                                                     PartitionCommitPolicy.METASTORE)));
230:         }
231:     }
232: 
233:     private DataStreamSink<?> consume(
234:             ProviderContext providerContext,
235:             DataStream<RowData> dataStream,
236:             boolean isBounded,
237:             DataStructureConverter converter) {
238:         checkAcidTable(catalogTable.getOptions(), identifier.toObjectPath());
239: 
240:         StorageDescriptor sd;
241:         Properties tableProps = new Properties();
242:         Map<String, String> options = catalogTable.getOptions();
243:         boolean isInsertDirectory =
244:                 Boolean.parseBoolean(
245:                         options.getOrDefault(
246:                                 CatalogPropertiesUtil.FLINK_PROPERTY_PREFIX + IS_INSERT_DIRECTORY,
247:                                 "false"));
248:         boolean isToLocal = false;
249:         if (isInsertDirectory) {
250:             isToLocal =
251:                     Boolean.parseBoolean(
252:                             options.getOrDefault(
253:                                     CatalogPropertiesUtil.FLINK_PROPERTY_PREFIX
254:                                             + IS_TO_LOCAL_DIRECTORY,
255:                                     "false"));
256:             sd =
257:                     org.apache.hadoop.hive.ql.metadata.Table.getEmptyTable(
258:                                     identifier.getDatabaseName(), identifier.getObjectName())
259:                             .getSd();
260:             HiveConf hiveConf = HiveConfUtils.create(jobConf);
261:             HiveTableUtil.setDefaultStorageFormatForDirectory(sd, HiveConfUtils.create(jobConf));
262:             HiveTableUtil.extractRowFormat(sd, catalogTable.getOptions());
263:             HiveTableUtil.extractStoredAs(sd, catalogTable.getOptions(), hiveConf);
264:             HiveTableUtil.extractLocation(sd, catalogTable.getOptions());
265:             tableProps.putAll(sd.getSerdeInfo().getParameters());
266:             tableProps.putAll(catalogTable.getOptions());
267:         } else {
268:             try (HiveMetastoreClientWrapper client =
269:                     HiveMetastoreClientFactory.create(HiveConfUtils.create(jobConf), hiveVersion)) {
270:                 Table table =
271:                         client.getTable(identifier.getDatabaseName(), identifier.getObjectName());
272:                 sd = table.getSd();
273:                 tableProps = HiveReflectionUtils.getTableMetadata(hiveShim, table);
274:             } catch (TException e) {
275:                 throw new CatalogException("Failed to query Hive metaStore", e);
276:             }
277:         }
278: 
279:         try {
280:             Class hiveOutputFormatClz =
281:                     hiveShim.getHiveOutputFormatClass(Class.forName(sd.getOutputFormat()));
282:             boolean isCompressed =
283:                     jobConf.getBoolean(HiveConf.ConfVars.COMPRESSRESULT.varname, false);
284:             HiveWriterFactory writerFactory =
285:                     new HiveWriterFactory(
286:                             jobConf,
287:                             hiveOutputFormatClz,
288:                             sd.getSerdeInfo(),
289:                             resolvedSchema,
290:                             getPartitionKeyArray(),
291:                             tableProps,
292:                             hiveShim,
293:                             isCompressed);
294:             String extension =
295:                     Utilities.getFileExtension(
296:                             jobConf,
297:                             isCompressed,
298:                             (HiveOutputFormat<?, ?>) hiveOutputFormatClz.newInstance());
299: 
300:             OutputFileConfig.OutputFileConfigBuilder fileNamingBuilder =
301:                     OutputFileConfig.builder()
302:                             .withPartPrefix("part-" + UUID.randomUUID())
303:                             .withPartSuffix(extension == null ? "" : extension);
304: 
305:             final int sinkParallelism =
306:                     Optional.ofNullable(configuredSinkParallelism)
307:                             .orElse(dataStream.getParallelism());
308:             boolean sinkParallelismConfigured = configuredSinkParallelism != null;
309:             if (isBounded) {
310:                 TableMetaStoreFactory msFactory =
311:                         isInsertDirectory
312:                                 ? new EmptyMetaStoreFactory(
313:                                         new org.apache.flink.core.fs.Path(sd.getLocation()))
314:                                 : msFactory(autoGatherStatistic);
315:                 // default to use the dest location as the parent directory of staging directory
316:                 String stagingParentDir = sd.getLocation();
317:                 if (isToLocal) {
318:                     // it's for writing to local file system, dest location is a path in local file
319:                     // system. we need to know the scratch path for
320:                     // non-local file system, so that it'll first write to the scratch path and then
321:                     // move to the local path
322:                     Path rootScratchDirPath =
323:                             new Path(
324:                                     HiveConf.getVar(
325:                                             HiveConfUtils.create(jobConf),
326:                                             HiveConf.ConfVars.SCRATCHDIR));
327:                     // TODO: may append something more meaningful than a timestamp, like query ID
328:                     Path scratchDir =
329:                             new Path(
330:                                     rootScratchDirPath, String.valueOf(System.currentTimeMillis()));
331:                     stagingParentDir = scratchDir.toUri().toString();
332:                 }
333:                 return createBatchSink(
334:                         dataStream,
335:                         converter,
336:                         writerFactory,
337:                         msFactory,
338:                         fileNamingBuilder,
339:                         stagingParentDir,
340:                         sd,
341:                         tableProps,
342:                         isToLocal,
343:                         overwrite,
344:                         sinkParallelism,
345:                         sinkParallelismConfigured);
346:             } else {
347:                 if (overwrite) {
348:                     throw new IllegalStateException("Streaming mode not support overwrite.");
349:                 }
350:                 return createStreamSink(
351:                         providerContext,
352:                         dataStream,
353:                         sd,
354:                         tableProps,
355:                         writerFactory,
356:                         fileNamingBuilder,
357:                         sinkParallelism,
358:                         sinkParallelismConfigured);
359:             }
360:         } catch (IOException e) {
361:             throw new FlinkRuntimeException("Failed to create staging dir", e);
362:         } catch (ClassNotFoundException e) {
363:             throw new FlinkHiveException("Failed to get output format class", e);
364:         } catch (IllegalAccessException | InstantiationException e) {
365:             throw new FlinkHiveException("Failed to instantiate output format instance", e);
366:         }
367:     }
