369:     private DataStreamSink<?> createBatchSink(
370:             DataStream<RowData> dataStream,
371:             DataStructureConverter converter,
372:             HiveWriterFactory recordWriterFactory,
373:             TableMetaStoreFactory metaStoreFactory,
374:             OutputFileConfig.OutputFileConfigBuilder fileConfigBuilder,
375:             String stagingParentDir,
376:             StorageDescriptor sd,
377:             Properties tableProps,
378:             boolean isToLocal,
379:             boolean overwrite,
380:             int sinkParallelism,
381:             boolean sinkParallelismConfigured)
382:             throws IOException {
383:         org.apache.flink.configuration.Configuration conf =
384:                 new org.apache.flink.configuration.Configuration();
385:         catalogTable.getOptions().forEach(conf::setString);
386:         boolean autoCompaction = conf.get(FileSystemConnectorOptions.AUTO_COMPACTION);
387:         if (autoCompaction) {
388:             Optional<Integer> compactParallelismOptional =
389:                     conf.getOptional(FileSystemConnectorOptions.COMPACTION_PARALLELISM);
390:             int compactParallelism = compactParallelismOptional.orElse(sinkParallelism);
391:             boolean compactParallelismConfigured =
392:                     compactParallelismOptional.isPresent()
393:                             ||
394:                             // if only sink parallelism is set, compact operator should follow this
395:                             // setting. that means its parallelism equals to sink and marked as
396:                             // configured to disable auto parallelism inference.
397:                             sinkParallelismConfigured;
398:             return createBatchCompactSink(
399:                     dataStream,
400:                     converter,
401:                     recordWriterFactory,
402:                     metaStoreFactory,
403:                     fileConfigBuilder
404:                             .withPartPrefix(
405:                                     BatchCompactOperator.UNCOMPACTED_PREFIX
406:                                             + "part-"
407:                                             + UUID.randomUUID())
408:                             .build(),
409:                     stagingParentDir,
410:                     sd,
411:                     tableProps,
412:                     isToLocal,
413:                     overwrite,
414:                     sinkParallelism,
415:                     compactParallelism,
416:                     sinkParallelismConfigured,
417:                     compactParallelismConfigured);
418:         } else {
419:             return createBatchNoCompactSink(
420:                     dataStream,
421:                     converter,
422:                     recordWriterFactory,
423:                     metaStoreFactory,
424:                     fileConfigBuilder.build(),
425:                     stagingParentDir,
426:                     isToLocal,
427:                     sinkParallelism,
428:                     sinkParallelismConfigured);
429:         }
430:     }
