862:      * effectively avoid DFS pressure.
863:      */
864:     private static class HiveRollingPolicy extends CheckpointRollingPolicy<RowData, String> {
865: 
866:         private final long rollingFileSize;
867:         private final long rollingTimeInterval;
868:         private final long inactivityInterval;
869: 
870:         private HiveRollingPolicy(
871:                 long rollingFileSize, long rollingTimeInterval, long inactivityInterval) {
872:             Preconditions.checkArgument(rollingFileSize > 0L);
873:             Preconditions.checkArgument(rollingTimeInterval > 0L);
874:             Preconditions.checkArgument(inactivityInterval > 0L);
875:             this.rollingFileSize = rollingFileSize;
876:             this.rollingTimeInterval = rollingTimeInterval;
877:             this.inactivityInterval = inactivityInterval;
878:         }
879: 
880:         @Override
881:         public boolean shouldRollOnCheckpoint(PartFileInfo<String> partFileState) {
882:             return true;
883:         }
884: 
885:         @Override
886:         public boolean shouldRollOnEvent(PartFileInfo<String> partFileState, RowData element) {
887:             return false;
888:         }
889: 
890:         @Override
891:         public boolean shouldRollOnProcessingTime(
892:                 PartFileInfo<String> partFileState, long currentTime) {
893:             try {
894:                 return currentTime - partFileState.getCreationTime() >= rollingTimeInterval
895:                         || currentTime - partFileState.getLastUpdateTime() >= inactivityInterval
896:                         || partFileState.getSize() > rollingFileSize;
897:             } catch (IOException e) {
898:                 throw new UncheckedIOException(e);
899:             }
900:         }
901:     }
