206:                                 dualInputOperator.getOperatorInfo().getFirstInputType(),
207:                                 dn.getKeysForInput1(),
208:                                 getSortOrders(dn.getKeysForInput1(), dn.getSortOrders())));
209:                 dn.setComparator2(
210:                         createComparator(
211:                                 dualInputOperator.getOperatorInfo().getSecondInputType(),
212:                                 dn.getKeysForInput2(),
213:                                 getSortOrders(dn.getKeysForInput2(), dn.getSortOrders())));
214: 
215:                 dn.setPairComparator(
216:                         createPairComparator(
217:                                 dualInputOperator.getOperatorInfo().getFirstInputType(),
218:                                 dualInputOperator.getOperatorInfo().getSecondInputType()));
219:             }
220: 
221:             traverseChannel(dn.getInput1());
222:             traverseChannel(dn.getInput2());
223: 
224:             // don't forget the broadcast inputs
225:             for (Channel c : dn.getBroadcastInputs()) {
226:                 traverseChannel(c);
227:             }
228: 
229:         }
230:         // catch the sources of the iterative step functions
231:         else if (node instanceof BulkPartialSolutionPlanNode
232:                 || node instanceof SolutionSetPlanNode
233:                 || node instanceof WorksetPlanNode) {
234:             // Do nothing :D
235:         } else if (node instanceof NAryUnionPlanNode) {
236:             // Traverse to all child channels
237:             for (Channel channel : node.getInputs()) {
238:                 traverseChannel(channel);
239:             }
240:         } else {
241:             throw new CompilerPostPassException(
242:                     "Unknown node type encountered: " + node.getClass().getName());
243:         }
244:     }
