246:     private void traverseChannel(Channel channel) {
247: 
248:         PlanNode source = channel.getSource();
249:         Operator<?> javaOp = source.getProgramOperator();
250: 
251:         //		if (!(javaOp instanceof BulkIteration) && !(javaOp instanceof JavaPlanNode)) {
252:         //			throw new RuntimeException("Wrong operator type found in post pass: " + javaOp);
253:         //		}
254: 
255:         TypeInformation<?> type = javaOp.getOperatorInfo().getOutputType();
256: 
257:         if (javaOp instanceof GroupReduceOperatorBase
258:                 && (source.getDriverStrategy() == DriverStrategy.SORTED_GROUP_COMBINE
259:                         || source.getDriverStrategy() == DriverStrategy.ALL_GROUP_REDUCE_COMBINE)) {
260:             GroupReduceOperatorBase<?, ?, ?> groupNode = (GroupReduceOperatorBase<?, ?, ?>) javaOp;
261:             type = groupNode.getInput().getOperatorInfo().getOutputType();
262:         } else if (javaOp instanceof PlanUnwrappingReduceGroupOperator
263:                 && source.getDriverStrategy().equals(DriverStrategy.SORTED_GROUP_COMBINE)) {
264:             PlanUnwrappingReduceGroupOperator<?, ?, ?> groupNode =
265:                     (PlanUnwrappingReduceGroupOperator<?, ?, ?>) javaOp;
266:             type = groupNode.getInput().getOperatorInfo().getOutputType();
267:         }
268: 
269:         // the serializer always exists
270:         channel.setSerializer(createSerializer(type));
271: 
272:         // parameterize the ship strategy
273:         if (channel.getShipStrategy().requiresComparator()) {
274:             channel.setShipStrategyComparator(
275:                     createComparator(
276:                             type,
277:                             channel.getShipStrategyKeys(),
278:                             getSortOrders(
279:                                     channel.getShipStrategyKeys(),
280:                                     channel.getShipStrategySortOrder())));
281:         }
282: 
283:         // parameterize the local strategy
284:         if (channel.getLocalStrategy().requiresComparator()) {
285:             channel.setLocalStrategyComparator(
286:                     createComparator(
287:                             type,
288:                             channel.getLocalStrategyKeys(),
289:                             getSortOrders(
290:                                     channel.getLocalStrategyKeys(),
291:                                     channel.getLocalStrategySortOrder())));
292:         }
293: 
294:         // descend to the channel's source
295:         traverse(channel.getSource());
296:     }
