304:     private static boolean hasMainMethod(Class<?> entryClass) {
305:         Method mainMethod;
306:         try {
307:             mainMethod = entryClass.getMethod("main", String[].class);
308:         } catch (NoSuchMethodException e) {
309:             return false;
310:         } catch (Throwable t) {
311:             throw new RuntimeException(
312:                     "Could not look up the main(String[]) method from the class "
313:                             + entryClass.getName()
314:                             + ": "
315:                             + t.getMessage(),
316:                     t);
317:         }
318: 
319:         return Modifier.isStatic(mainMethod.getModifiers())
320:                 && Modifier.isPublic(mainMethod.getModifiers());
321:     }
