512:     /**
513:      * Takes all JAR files that are contained in this program's JAR file and extracts them to the
514:      * system's temp directory.
515:      *
516:      * @return The file names of the extracted temporary files.
517:      * @throws ProgramInvocationException Thrown, if the extraction process failed.
518:      */
519:     public static List<File> extractContainedLibraries(URL jarFile)
520:             throws ProgramInvocationException {
521:         try (final JarFile jar = new JarFile(new File(jarFile.toURI()))) {
522: 
523:             final List<JarEntry> containedJarFileEntries = getContainedJarEntries(jar);
524:             if (containedJarFileEntries.isEmpty()) {
525:                 return Collections.emptyList();
526:             }
527: 
528:             final List<File> extractedTempLibraries =
529:                     new ArrayList<>(containedJarFileEntries.size());
530:             boolean incomplete = true;
531: 
532:             try {
533:                 final Random rnd = new Random();
534:                 final byte[] buffer = new byte[4096];
535: 
536:                 for (final JarEntry entry : containedJarFileEntries) {
537:                     // '/' as in case of zip, jar
538:                     // java.util.zip.ZipEntry#isDirectory always looks only for '/' not for
539:                     // File.separator
540:                     final String name = entry.getName().replace('/', '_');
541:                     final File tempFile = copyLibToTempFile(name, rnd, jar, entry, buffer);
542:                     extractedTempLibraries.add(tempFile);
543:                 }
544: 
545:                 incomplete = false;
546:             } finally {
547:                 if (incomplete) {
548:                     deleteExtractedLibraries(extractedTempLibraries);
549:                 }
550:             }
551: 
552:             return extractedTempLibraries;
553:         } catch (Throwable t) {
554:             throw new ProgramInvocationException(
555:                     "Unknown I/O error while extracting contained jar files.", t);
556:         }
557:     }
