323:     private static void callMainMethod(Class<?> entryClass, String[] args)
324:             throws ProgramInvocationException {
325:         Method mainMethod;
326:         if (!Modifier.isPublic(entryClass.getModifiers())) {
327:             throw new ProgramInvocationException(
328:                     "The class " + entryClass.getName() + " must be public.");
329:         }
330: 
331:         try {
332:             mainMethod = entryClass.getMethod("main", String[].class);
333:         } catch (NoSuchMethodException e) {
334:             throw new ProgramInvocationException(
335:                     "The class " + entryClass.getName() + " has no main(String[]) method.");
336:         } catch (Throwable t) {
337:             throw new ProgramInvocationException(
338:                     "Could not look up the main(String[]) method from the class "
339:                             + entryClass.getName()
340:                             + ": "
341:                             + t.getMessage(),
342:                     t);
343:         }
344: 
345:         if (!Modifier.isStatic(mainMethod.getModifiers())) {
346:             throw new ProgramInvocationException(
347:                     "The class " + entryClass.getName() + " declares a non-static main method.");
348:         }
349:         if (!Modifier.isPublic(mainMethod.getModifiers())) {
350:             throw new ProgramInvocationException(
351:                     "The class " + entryClass.getName() + " declares a non-public main method.");
352:         }
353: 
354:         try {
355:             mainMethod.invoke(null, (Object) args);
356:         } catch (IllegalArgumentException e) {
357:             throw new ProgramInvocationException(
358:                     "Could not invoke the main method, arguments are not matching.", e);
359:         } catch (IllegalAccessException e) {
360:             throw new ProgramInvocationException(
361:                     "Access to the main method was denied: " + e.getMessage(), e);
362:         } catch (InvocationTargetException e) {
363:             Throwable exceptionInMethod = e.getTargetException();
364:             if (exceptionInMethod instanceof Error) {
365:                 throw (Error) exceptionInMethod;
366:             } else if (exceptionInMethod instanceof ProgramParametrizationException) {
367:                 throw (ProgramParametrizationException) exceptionInMethod;
368:             } else if (exceptionInMethod instanceof ProgramInvocationException) {
369:                 throw (ProgramInvocationException) exceptionInMethod;
370:             } else {
371:                 throw new ProgramInvocationException(
372:                         "The main method caused an error: " + exceptionInMethod.getMessage(),
373:                         exceptionInMethod);
374:             }
375:         } catch (Throwable t) {
376:             throw new ProgramInvocationException(
377:                     "An error occurred while invoking the program's main method: " + t.getMessage(),
378:                     t);
379:         }
