382:     private static String getEntryPointClassNameFromJar(URL jarFile)
383:             throws ProgramInvocationException {
384:         JarFile jar;
385:         Manifest manifest;
386:         String className;
387: 
388:         // Open jar file
389:         try {
390:             jar = new JarFile(new File(jarFile.toURI()));
391:         } catch (URISyntaxException use) {
392:             throw new ProgramInvocationException(
393:                     "Invalid file path '" + jarFile.getPath() + "'", use);
394:         } catch (IOException ioex) {
395:             throw new ProgramInvocationException(
396:                     "Error while opening jar file '"
397:                             + jarFile.getPath()
398:                             + "'. "
399:                             + ioex.getMessage(),
400:                     ioex);
401:         }
402: 
403:         // jar file must be closed at the end
404:         try {
405:             // Read from jar manifest
406:             try {
407:                 manifest = jar.getManifest();
408:             } catch (IOException ioex) {
409:                 throw new ProgramInvocationException(
410:                         "The Manifest in the jar file could not be accessed '"
411:                                 + jarFile.getPath()
412:                                 + "'. "
413:                                 + ioex.getMessage(),
414:                         ioex);
415:             }
416: 
417:             if (manifest == null) {
418:                 throw new ProgramInvocationException(
419:                         "No manifest found in jar file '"
420:                                 + jarFile.getPath()
421:                                 + "'. The manifest is need to point to the program's main class.");
422:             }
423: 
424:             Attributes attributes = manifest.getMainAttributes();
425: 
426:             // check for a "program-class" entry first
427:             className = attributes.getValue(PackagedProgram.MANIFEST_ATTRIBUTE_ASSEMBLER_CLASS);
428:             if (className != null) {
429:                 return className;
430:             }
431: 
432:             // check for a main class
433:             className = attributes.getValue(PackagedProgram.MANIFEST_ATTRIBUTE_MAIN_CLASS);
434:             if (className != null) {
435:                 return className;
436:             } else {
437:                 throw new ProgramInvocationException(
438:                         "Neither a '"
439:                                 + MANIFEST_ATTRIBUTE_MAIN_CLASS
440:                                 + "', nor a '"
441:                                 + MANIFEST_ATTRIBUTE_ASSEMBLER_CLASS
442:                                 + "' entry was found in the jar file.");
443:             }
444:         } finally {
445:             try {
446:                 jar.close();
447:             } catch (Throwable t) {
448:                 throw new ProgramInvocationException(
449:                         "Could not close the JAR file: " + t.getMessage(), t);
450:             }
451:         }
452:     }
