559:     private static File copyLibToTempFile(
560:             String name, Random rnd, JarFile jar, JarEntry input, byte[] buffer)
561:             throws ProgramInvocationException {
562:         final File output = createTempFile(rnd, input, name);
563:         try (final OutputStream out = new FileOutputStream(output);
564:                 final InputStream in = new BufferedInputStream(jar.getInputStream(input))) {
565:             int numRead = 0;
566:             while ((numRead = in.read(buffer)) != -1) {
567:                 out.write(buffer, 0, numRead);
568:             }
569:             return output;
570:         } catch (IOException e) {
571:             throw new ProgramInvocationException(
572:                     "An I/O error occurred while extracting nested library '"
573:                             + input.getName()
574:                             + "' to temporary file '"
575:                             + output.getAbsolutePath()
576:                             + "'.");
577:         }
578:     }
