580:     private static File createTempFile(Random rnd, JarEntry entry, String name)
581:             throws ProgramInvocationException {
582:         try {
583:             final File tempFile = File.createTempFile(rnd.nextInt(Integer.MAX_VALUE) + "_", name);
584:             tempFile.deleteOnExit();
585:             return tempFile;
586:         } catch (IOException e) {
587:             throw new ProgramInvocationException(
588:                     "An I/O error occurred while creating temporary file to extract nested library '"
589:                             + entry.getName()
590:                             + "'.",
591:                     e);
592:         }
593:     }
