595:     private static List<JarEntry> getContainedJarEntries(JarFile jar) {
596:         return jar.stream()
597:                 .filter(
598:                         jarEntry -> {
599:                             final String name = jarEntry.getName();
600:                             return name.length() > 8
601:                                     && name.startsWith("lib/")
602:                                     && name.endsWith(".jar");
603:                         })
604:                 .collect(Collectors.toList());
605:     }
