53: /** An {@link ApplicationClusterEntryPoint} for Kubernetes. */
54: @Internal
55: public final class KubernetesApplicationClusterEntrypoint extends ApplicationClusterEntryPoint {
56: 
57:     private KubernetesApplicationClusterEntrypoint(
58:             final Configuration configuration, final PackagedProgram program) {
59:         super(configuration, program, KubernetesResourceManagerFactory.getInstance());
60:     }
61: 
62:     public static void main(final String[] args) {
63:         // startup checks and logging
64:         EnvironmentInformation.logEnvironmentInfo(
65:                 LOG, KubernetesApplicationClusterEntrypoint.class.getSimpleName(), args);
66:         SignalHandler.register(LOG);
67:         JvmShutdownSafeguard.installAsShutdownHook(LOG);
68: 
69:         final Configuration dynamicParameters =
70:                 ClusterEntrypointUtils.parseParametersOrExit(
71:                         args,
72:                         new DynamicParametersConfigurationParserFactory(),
73:                         KubernetesApplicationClusterEntrypoint.class);
74:         final Configuration configuration =
75:                 KubernetesEntrypointUtils.loadConfiguration(dynamicParameters);
76: 
77:         PackagedProgram program = null;
78:         try {
79:             PluginManager pluginManager =
80:                     PluginUtils.createPluginManagerFromRootFolder(configuration);
81:             LOG.info(
82:                     "Install default filesystem for fetching user artifacts in Kubernetes Application Mode.");
83:             FileSystem.initialize(configuration, pluginManager);
84:             SecurityContext securityContext = installSecurityContext(configuration);
85:             program = securityContext.runSecured(() -> getPackagedProgram(configuration));
86:         } catch (Exception e) {
87:             LOG.error("Could not create application program.", e);
88:             System.exit(1);
89:         }
90: 
91:         try {
92:             configureExecution(configuration, program);
93:         } catch (Exception e) {
94:             LOG.error("Could not apply application configuration.", e);
95:             System.exit(1);
96:         }
97: 
98:         final KubernetesApplicationClusterEntrypoint kubernetesApplicationClusterEntrypoint =
99:                 new KubernetesApplicationClusterEntrypoint(configuration, program);
100: 
101:         ClusterEntrypoint.runClusterEntrypoint(kubernetesApplicationClusterEntrypoint);
102:     }
103: 
104:     private static PackagedProgram getPackagedProgram(final Configuration configuration)
105:             throws FlinkException {
106: 
107:         final ApplicationConfiguration applicationConfiguration =
108:                 ApplicationConfiguration.fromConfiguration(configuration);
109: 
110:         final PackagedProgramRetriever programRetriever =
111:                 getPackagedProgramRetriever(
112:                         configuration,
113:                         applicationConfiguration.getProgramArguments(),
114:                         applicationConfiguration.getApplicationClassName());
115:         return programRetriever.getPackagedProgram();
116:     }
117: 
118:     private static PackagedProgramRetriever getPackagedProgramRetriever(
119:             final Configuration configuration,
120:             final String[] programArguments,
121:             @Nullable final String jobClassName)
122:             throws FlinkException {
123: 
124:         final File userLibDir = ClusterEntrypointUtils.tryFindUserLibDirectory().orElse(null);
125: 
126:         // No need to do pipelineJars validation if it is a PyFlink job.
127:         if (!(PackagedProgramUtils.isPython(jobClassName)
128:                 || PackagedProgramUtils.isPython(programArguments))) {
129:             final List<File> pipelineJarFiles = fetchJarFileForApplicationMode(configuration);
130:             Preconditions.checkArgument(pipelineJarFiles.size() == 1, "Should only have one jar");
131:             return DefaultPackagedProgramRetriever.create(
132:                     userLibDir,
133:                     pipelineJarFiles.get(0),
134:                     jobClassName,
135:                     programArguments,
136:                     configuration);
137:         }
138: 
139:         return DefaultPackagedProgramRetriever.create(
140:                 userLibDir, jobClassName, programArguments, configuration);
141:     }
142: 
143:     /**
144:      * Fetch the user jar from path.
145:      *
146:      * @param configuration Flink Configuration
147:      * @return User jar File
148:      */
149:     public static List<File> fetchJarFileForApplicationMode(Configuration configuration) {
150:         String targetDir = generateJarDir(configuration);
151:         return configuration.get(PipelineOptions.JARS).stream()
152:                 .map(
153:                         FunctionUtils.uncheckedFunction(
154:                                 uri -> ArtifactUtils.fetch(uri, configuration, targetDir)))
155:                 .collect(Collectors.toList());
156:     }
157: 
158:     public static String generateJarDir(Configuration configuration) {
159:         return String.join(
160:                 File.separator,
161:                 new String[] {
162:                     new File(configuration.get(ArtifactFetchOptions.USER_ARTIFACTS_BASE_DIR))
163:                             .getAbsolutePath(),
164:                     configuration.get(KubernetesConfigOptions.NAMESPACE),
165:                     configuration.get(KubernetesConfigOptions.CLUSTER_ID)
166:                 });
167:     }
168: }
