87:             LOG.error("Could not create application program.", e);
88:             System.exit(1);
89:         }
90: 
91:         try {
92:             configureExecution(configuration, program);
93:         } catch (Exception e) {
94:             LOG.error("Could not apply application configuration.", e);
95:             System.exit(1);
96:         }
97: 
98:         final KubernetesApplicationClusterEntrypoint kubernetesApplicationClusterEntrypoint =
99:                 new KubernetesApplicationClusterEntrypoint(configuration, program);
100: 
101:         ClusterEntrypoint.runClusterEntrypoint(kubernetesApplicationClusterEntrypoint);
102:     }
