104:     private static PackagedProgram getPackagedProgram(final Configuration configuration)
105:             throws FlinkException {
106: 
107:         final ApplicationConfiguration applicationConfiguration =
108:                 ApplicationConfiguration.fromConfiguration(configuration);
109: 
110:         final PackagedProgramRetriever programRetriever =
111:                 getPackagedProgramRetriever(
112:                         configuration,
113:                         applicationConfiguration.getProgramArguments(),
114:                         applicationConfiguration.getApplicationClassName());
115:         return programRetriever.getPackagedProgram();
116:     }
