118:     private static PackagedProgramRetriever getPackagedProgramRetriever(
119:             final Configuration configuration,
120:             final String[] programArguments,
121:             @Nullable final String jobClassName)
122:             throws FlinkException {
123: 
124:         final File userLibDir = ClusterEntrypointUtils.tryFindUserLibDirectory().orElse(null);
125: 
126:         // No need to do pipelineJars validation if it is a PyFlink job.
127:         if (!(PackagedProgramUtils.isPython(jobClassName)
128:                 || PackagedProgramUtils.isPython(programArguments))) {
129:             final List<File> pipelineJarFiles = fetchJarsForApplicationMode(configuration);
130:             Preconditions.checkArgument(pipelineJarFiles.size() == 1, "Should only have one jar");
131:             return DefaultPackagedProgramRetriever.create(
132:                     userLibDir,
133:                     pipelineJarFiles.get(0),
134:                     jobClassName,
135:                     programArguments,
136:                     configuration);
137:         }
138: 
139:         return DefaultPackagedProgramRetriever.create(
140:                 userLibDir, jobClassName, programArguments, configuration);
141:     }
