149:     public static List<File> fetchJarsForApplicationMode(Configuration configuration) {
150:         String targetDir = generateJarDir(configuration);
151:         return configuration.get(PipelineOptions.JARS).stream()
152:                 .map(
153:                         FunctionUtils.uncheckedFunction(
154:                                 uri -> ArtifactUtils.fetch(uri, configuration, targetDir)))
155:                 .collect(Collectors.toList());
156:     }
