158:     public static String generateJarDir(Configuration configuration) {
159:         return String.join(
160:                 File.separator,
161:                 new String[] {
162:                     new File(configuration.get(ArtifactFetchOptions.USER_ARTIFACTS_BASE_DIR))
163:                             .getAbsolutePath(),
164:                     configuration.get(KubernetesConfigOptions.NAMESPACE),
165:                     configuration.get(KubernetesConfigOptions.CLUSTER_ID)
166:                 });
