243:     private ClusterClientProvider<String> deployClusterInternal(
244:             String entryPoint, ClusterSpecification clusterSpecification, boolean detached)
245:             throws ClusterDeploymentException {
246:         final ClusterEntrypoint.ExecutionMode executionMode =
247:                 detached
248:                         ? ClusterEntrypoint.ExecutionMode.DETACHED
249:                         : ClusterEntrypoint.ExecutionMode.NORMAL;
250:         flinkConfig.set(
251:                 ClusterEntrypoint.INTERNAL_CLUSTER_EXECUTION_MODE, executionMode.toString());
252: 
253:         flinkConfig.set(KubernetesConfigOptionsInternal.ENTRY_POINT_CLASS, entryPoint);
254: 
255:         // Rpc, blob, rest, taskManagerRpc ports need to be exposed, so update them to fixed values.
256:         KubernetesUtils.checkAndUpdatePortConfigOption(
257:                 flinkConfig, BlobServerOptions.PORT, Constants.BLOB_SERVER_PORT);
258:         KubernetesUtils.checkAndUpdatePortConfigOption(
259:                 flinkConfig, TaskManagerOptions.RPC_PORT, Constants.TASK_MANAGER_RPC_PORT);
260:         KubernetesUtils.checkAndUpdatePortConfigOption(
261:                 flinkConfig, RestOptions.BIND_PORT, Constants.REST_PORT);
262: 
263:         if (HighAvailabilityMode.isHighAvailabilityModeActivated(flinkConfig)) {
264:             flinkConfig.set(HighAvailabilityOptions.HA_CLUSTER_ID, clusterId);
265:             KubernetesUtils.checkAndUpdatePortConfigOption(
266:                     flinkConfig,
267:                     HighAvailabilityOptions.HA_JOB_MANAGER_PORT_RANGE,
268:                     flinkConfig.get(JobManagerOptions.PORT));
269:         }
270: 
271:         try {
272:             final KubernetesJobManagerParameters kubernetesJobManagerParameters =
273:                     new KubernetesJobManagerParameters(flinkConfig, clusterSpecification);
274: 
275:             final FlinkPod podTemplate =
276:                     kubernetesJobManagerParameters
277:                             .getPodTemplateFilePath()
278:                             .map(
279:                                     file ->
280:                                             KubernetesUtils.loadPodFromTemplateFile(
281:                                                     client, file, Constants.MAIN_CONTAINER_NAME))
282:                             .orElse(new FlinkPod.Builder().build());
283:             final KubernetesJobManagerSpecification kubernetesJobManagerSpec =
284:                     KubernetesJobManagerFactory.buildKubernetesJobManagerSpecification(
285:                             podTemplate, kubernetesJobManagerParameters);
286: 
287:             client.createJobManagerComponent(kubernetesJobManagerSpec);
288: 
289:             return createClusterClientProvider(clusterId);
290:         } catch (Exception e) {
291:             try {
292:                 LOG.warn(
293:                         "Failed to create the Kubernetes cluster \"{}\", try to clean up the residual resources.",
294:                         clusterId);
295:                 client.stopAndCleanupCluster(clusterId);
296:             } catch (Exception e1) {
297:                 LOG.info(
298:                         "Failed to stop and clean up the Kubernetes cluster \"{}\".",
299:                         clusterId,
300:                         e1);
301:             }
302:             throw new ClusterDeploymentException(
303:                     "Could not create Kubernetes cluster \"" + clusterId + "\".", e);
304:         }
305:     }
