19: package org.apache.flink.container.entrypoint;
20: 
21: import org.apache.flink.api.common.JobID;
22: import org.apache.flink.client.cli.CliFrontendParser;
23: import org.apache.flink.runtime.entrypoint.FlinkParseException;
24: import org.apache.flink.runtime.entrypoint.parser.ParserResultFactory;
25: import org.apache.flink.runtime.jobgraph.SavepointRestoreSettings;
26: 
27: import org.apache.commons.cli.CommandLine;
28: import org.apache.commons.cli.Option;
29: import org.apache.commons.cli.Options;
30: 
31: import javax.annotation.Nonnull;
32: import javax.annotation.Nullable;
33: 
34: import java.util.Properties;
35: 
36: import static org.apache.flink.runtime.entrypoint.parser.CommandLineOptions.CONFIG_DIR_OPTION;
37: import static org.apache.flink.runtime.entrypoint.parser.CommandLineOptions.DYNAMIC_PROPERTY_OPTION;
38: import static org.apache.flink.runtime.entrypoint.parser.CommandLineOptions.HOST_OPTION;
39: import static org.apache.flink.runtime.entrypoint.parser.CommandLineOptions.REST_PORT_OPTION;
40: 
41: /**
42:  * Parser factory which generates a {@link StandaloneApplicationClusterConfiguration} from a given
43:  * list of command line arguments.
44:  */
45: public class StandaloneApplicationClusterConfigurationParserFactory
46:         implements ParserResultFactory<StandaloneApplicationClusterConfiguration> {
47: 
48:     private static final Option JOB_CLASS_NAME_OPTION =
49:             Option.builder("j")
50:                     .longOpt("job-classname")
51:                     .required(false)
52:                     .hasArg(true)
53:                     .argName("job class name")
54:                     .desc("Class name of the job to run.")
55:                     .build();
56: 
57:     private static final Option JOB_ID_OPTION =
58:             Option.builder("jid")
59:                     .longOpt("job-id")
60:                     .required(false)
61:                     .hasArg(true)
62:                     .argName("job id")
63:                     .desc("Job ID of the job to run.")
64:                     .build();
65: 
66:     private static final Option JOB_JARS =
67:             Option.builder("jarfile")
68:                     .longOpt("jar-file")
69:                     .required(false)
70:                     .hasArg(true)
71:                     .argName("job jar file")
72:                     .desc("Jar File of the job to run.")
73:                     .build();
74: 
75:     @Override
76:     public Options getOptions() {
77:         final Options options = new Options();
78:         options.addOption(CONFIG_DIR_OPTION);
79:         options.addOption(JOB_JARS);
80:         options.addOption(REST_PORT_OPTION);
81:         options.addOption(JOB_CLASS_NAME_OPTION);
82:         options.addOption(JOB_ID_OPTION);
83:         options.addOption(DYNAMIC_PROPERTY_OPTION);
84:         options.addOption(HOST_OPTION);
85:         options.addOption(CliFrontendParser.SAVEPOINT_PATH_OPTION);
86:         options.addOption(CliFrontendParser.SAVEPOINT_ALLOW_NON_RESTORED_OPTION);
87: 
88:         return options;
89:     }
90: 
91:     @Override
92:     public StandaloneApplicationClusterConfiguration createResult(@Nonnull CommandLine commandLine)
93:             throws FlinkParseException {
94:         final String configDir = commandLine.getOptionValue(CONFIG_DIR_OPTION.getOpt());
95:         final Properties dynamicProperties =
96:                 commandLine.getOptionProperties(DYNAMIC_PROPERTY_OPTION.getOpt());
97:         final int restPort = getRestPort(commandLine);
98:         final String hostname = commandLine.getOptionValue(HOST_OPTION.getOpt());
99:         final SavepointRestoreSettings savepointRestoreSettings =
100:                 CliFrontendParser.createSavepointRestoreSettings(commandLine);
101:         final JobID jobId = getJobId(commandLine);
102:         final String jobClassName = commandLine.getOptionValue(JOB_CLASS_NAME_OPTION.getOpt());
103:         final String jarFile = commandLine.getOptionValue(JOB_JARS.getOpt());
104: 
105:         return new StandaloneApplicationClusterConfiguration(
106:                 configDir,
107:                 dynamicProperties,
108:                 commandLine.getArgs(),
109:                 hostname,
110:                 restPort,
111:                 savepointRestoreSettings,
112:                 jobId,
113:                 jobClassName,
114:                 jarFile);
115:     }
116: 
117:     private int getRestPort(CommandLine commandLine) throws FlinkParseException {
118:         final String restPortString = commandLine.getOptionValue(REST_PORT_OPTION.getOpt(), "-1");
119:         try {
120:             return Integer.parseInt(restPortString);
121:         } catch (NumberFormatException e) {
122:             throw createFlinkParseException(REST_PORT_OPTION, e);
123:         }
124:     }
125: 
126:     @Nullable
127:     private static JobID getJobId(CommandLine commandLine) throws FlinkParseException {
128:         String jobId = commandLine.getOptionValue(JOB_ID_OPTION.getOpt());
129:         if (jobId == null) {
130:             return null;
131:         }
132:         try {
133:             return JobID.fromHexString(jobId);
134:         } catch (IllegalArgumentException e) {
135:             throw createFlinkParseException(JOB_ID_OPTION, e);
136:         }
137:     }
138: 
139:     private static FlinkParseException createFlinkParseException(Option option, Exception cause) {
140:         return new FlinkParseException(
141:                 String.format("Failed to parse '--%s' option", option.getLongOpt()), cause);
142:     }
143: }
